local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>Uraaagh—</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5071_50710101_3_dialog_content = "...",
  ui_story_5071_50710101_4_dialog_content = "Urgh... *coughs*",
  ui_story_5071_50710101_5_dialog_content = "No...",
  ui_story_5071_50710101_6_dialog_content = "I heard he killed everyone!",
  ui_story_5071_50710101_7_dialog_content = "He's the only one who walked out of <color=#FFB400>the Pit</color> alive. It must be true.",
  ui_story_5071_50710101_8_dialog_content = "I can't believe what I'm hearing. He even killed his closest brother to gain power...",
  ui_story_5071_50710101_9_dialog_content = "We... Can we really leave the future of Umbraton to a person like this?",
  ui_story_5071_50710101_10_dialog_content = "...",
  ui_story_5071_50710101_11_dialog_content = "And now...",
  ui_story_5071_50710101_12_dialog_content = "Are you...",
  ui_story_5071_50710101_13_dialog_content = "<size=50>... happy?</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5071_50710101_15_dialog_content = "!",
  ui_story_5071_50710101_16_dialog_content = "All who took shadow form risk being devoured by the shadow.",
  ui_story_5071_50710101_17_dialog_content = "The past isn't the only thing swept under the rug by shadow, right, my brother?",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  ui_story_5071_50710101_19_dialog_content = "Father, it's me, Bethel.",
  ui_story_5071_50710101_20_dialog_content = "Come in.",
  ui_story_5071_50710101_21_dialog_content = "Father, I already—",
  ui_story_5071_50710101_22_dialog_content = "...",
  ui_story_5071_50710101_23_dialog_content = "Are you okay, father? I've never seen you this exhausted...",
  ui_story_5071_50710101_24_dialog_content = "Haha, moderation is the key, no matter how much you like fine wine. I guess I'm at the age when I have to be careful about such things.",
  ui_story_5071_50710101_25_dialog_content = "Please do not make light of it like that.",
  ui_story_5071_50710101_26_dialog_content = "Dismiss that as a jest then. Let's talk about you.",
  ui_story_5071_50710101_27_dialog_content = "Sure. I'm prepared for the trip.",
  ui_story_5071_50710101_28_dialog_content = "The road to Twin Pavilions Bay has been fixed and secured enough that Eclipsite sightings are rare.",
  ui_story_5071_50710101_29_dialog_content = "But keep your eyes out for what our Shadow cannot see.",
  ui_story_5071_50710101_30_dialog_content = "Naturally, my girl, I believe you'll handle the meeting with the \"clients\" there perfectly.",
  ui_story_5071_50710101_31_dialog_content = "I won't let you down, father.",
  ui_story_5071_50710101_32_dialog_content = "Bethel, as the head of the guild, the only duty you have is to Umbraton, not to someone.",
  ui_story_5071_50710101_33_dialog_content = "Father...",
  ui_story_5071_50710101_34_dialog_content = "Alright, I should get going too. Let me walk you out.",
  ui_story_5071_50710101_35_dialog_content = "...",
  ui_story_5071_50710101_36_dialog_content = "A guild that rose from the shadows to soar freely through the skies...",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>Your dream</color>... Has it already come true?",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5071_50710101_39_dialog_content = "Make no mistake about it, I smell gossip in the air!",
  ui_story_5071_50710101_40_dialog_content = "Hmm?",
  ui_story_5071_50710101_41_dialog_content = "Hello, I am Brandy, reporter for The Daily Scoop!",
  ui_story_5071_50710101_42_dialog_content = "May I ask your opinion on the supersized <color=#FFB400>Cloudrover Airship</color> built by Cloudrover Guild?",
  ui_story_5071_50710101_43_dialog_content = "No comment.",
  ui_story_5071_50710101_44_dialog_content = "That was a quick strikeout. These tycoons are as hard as clams to pry open.",
  ui_story_5071_50710101_45_dialog_content = "But look who's here—",
  ui_story_5071_50710101_46_dialog_content = "PlayerName! Over here, over here!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5071_50710101_48_dialog_content = "Are you invited to today's <color=#FFB400>maiden launch</color>, PlayerName? How about a word on the airship?",
  ui_story_5071_50710101_49_dialog_content = "It feels familiar.",
  ui_story_5071_50710101_50_dialog_content = "Even though the technology used in this airship is different from that of Colossi, it's still a massive vessel capable of flight.",
  ui_story_5071_50710101_51_dialog_content = "It feels impressive.",
  ui_story_5071_50710101_52_dialog_content = "I've only ever seen smaller airships before. I had no idea Lady Sheol had made an airship massive enough to carry her entire guild...",
  ui_story_5071_50710101_53_dialog_content = "This Cloudrover Airship is the pinnacle of airships, but not as big as your Soroz, right, PlayerName?",
  ui_story_5071_50710101_54_dialog_content = "No, but... In terms of size, it's probably still as big as Eulogoz, where they held that concert before.",
  ui_story_5071_50710101_55_dialog_content = "Ah, I see tomorrow's headline now!",
  ui_story_5071_50710101_56_dialog_content = "\"Caelestite proclaims: Cloudrover Airship is no match for Soroz!\"",
  ui_story_5071_50710101_57_dialog_content = "W-Wait, why are you twisting my words around like that?",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_5071_50710101_59_dialog_content = "Fear no harm or failure. Persistence will turn into luck!",
  ui_story_5071_50710101_60_dialog_content = "It's been a long time, my dear friends! How are you all?",
  ui_story_5071_50710101_61_dialog_content = "Isn't that... Goldie, that idol who is currently really popular in Umbraton? The Cloudrover Guild is as impressive as ever if they can get her to attend!",
  ui_story_5071_50710101_62_dialog_content = "Don't you know? Lady Sheol, the leader of the Cloudrover Guild, is the one who made her famous!",
  ui_story_5071_50710101_63_dialog_content = "The Cloudrover Guild has even dipped its hands into the entertainment industry? Just how many industries is Lady Sheol involved in?",
  ui_story_5071_50710101_64_dialog_content = "Who cares about idols or airships? They are all just gimmicks... The only reason I'm here is because the Shadowlord is attending.",
  ui_story_5071_50710101_65_dialog_content = "Please take it easy, everyone. The ceremony will begin soon!",
  ui_story_5071_50710101_66_dialog_content = "Until then, I'd like to perform a brand-new single for you—",
  ui_story_5071_50710101_67_dialog_content = "<size=45>Dreams Within Reach!</size>",
  ui_story_5071_50710101_68_dialog_content = "Please aspire to ride the wind and touch the sky soon with me!",
  ui_story_5071_50710101_69_dialog_content = "♪ In the boundless sky, clouds manifest hope, as dreams rise over the horizon like the morning sun ♪",
  ui_story_5071_50710101_70_dialog_content = "♪ Spread your wings, soar to the sky, and touch the brilliant light ♪",
  ui_story_5071_50710101_71_dialog_content = "(That's Goldie for you, huh? All it took was her singing to get all of those angry passengers to calm down. They're even nodding to the beat of her song now.)",
  ui_story_5071_50710101_72_dialog_content = "(Still... If Goldie's here, then her shrieking fan club should also be here to rupture my eardrums, right?)",
  ui_story_5071_50710101_73_dialog_content = "(I don't recognize any of the people that Lady Sheol invited aboard the airship...)",
  ui_story_5071_50710101_74_dialog_content = "He's here! He's here! The Shadowlord is here! Let's head over—",
  ui_story_5071_50710101_75_dialog_content = "(The Shadowlord's here too? This must be a special event after all...)",
  ui_story_5071_50710101_76_dialog_content = "Timely as always, Shadowlord. One more minute and you would miss the ribbon-cutting.",
  ui_story_5071_50710101_77_dialog_content = "Making an entrance at the proper time when attending events like this is a secret I learned from you, Lady Sheol.",
  ui_story_5071_50710101_78_dialog_content = "Shadowlord! I'm so happy to see you on such a joyous occasion!",
  ui_story_5071_50710101_79_dialog_content = "My dear Shadowlord, do you still remember me?",
  ui_story_5071_50710101_80_dialog_content = "Shadowlord, I requested a private meeting with you some time ago. Have you had the time to read my invitation yet?",
  ui_story_5071_50710101_81_dialog_content = "Shadowlord! Don't forget about me! Shadowlord—",
  ui_story_5071_50710101_82_dialog_content = "Ladies and gentlemen, the Shadowlord has taken it upon himself to meet with every one of you aboard the airship today.",
  ui_story_5071_50710101_83_dialog_content = "Of course, only those who requested an audience with him well in advance are granted such an honor.",
  ui_story_5071_50710101_84_dialog_content = "But for now, let us all turn our attention to our wonderful songstress and her spirited performance.",
  ui_story_5071_50710101_85_dialog_content = "Honestly, I never knew meeting with the Shadowlord required so many rules.",
  ui_story_5071_50710101_86_dialog_content = "...",
  ui_story_5071_50710101_87_dialog_content = "Forgive me, I haven't had the chance to properly introduce myself. I am Hanstie, leader of the Continental Guild. This is my first time here, and I'm unaccustomed to Umbraton's formalities. Please excuse me if I disrupted anyone's enjoyment of the festivities.",
  ui_story_5071_50710101_88_dialog_content = "Look... Isn't that Ms. Hanstie from the Continental Guild? I heard that she never shows up to anything! Lady Sheol sure is charismatic... or is this the charisma of the Shadowlord?",
  ui_story_5071_50710101_89_dialog_content = "The Continental Guild? There's such a guild in Umbraton?",
  ui_story_5071_50710101_90_dialog_content = "The Continental Guild has started doing business in small towns outside of Umbraton in recent years. Although it just established a foothold in Umbraton, its development momentum shouldn't be taken lightly!",
  ui_story_5071_50710101_91_dialog_content = "What an honor to have you present, Ms. Hanstie.",
  ui_story_5071_50710101_92_dialog_content = "The Cloudrover Guild has invited every reputable guild leader in Umbraton for this event. How could I possibly miss an opportunity like this?",
  ui_story_5071_50710101_93_dialog_content = "What's more, when I heard that the famous Shadowlord was making an appearance, I knew I had to be here.",
  ui_story_5071_50710101_94_dialog_content = "Ah, you must be Lady Sheol, leader of the <color=#FFB400>Cloudrover Guild</color> and a figure I can only look up to.",
  ui_story_5071_50710101_95_dialog_content = "You jest, Ms. Hanstie.",
  ui_story_5071_50710101_96_dialog_content = "The <color=#FFB400>Continental Guild</color>'s network permeates the entire Astra. The sky and the land can and do co-exist.",
  ui_story_5071_50710101_97_dialog_content = "Your airship is quite impressive, I must say.",
  ui_story_5071_50710101_98_dialog_content = "It's Cloudrover Guild's honor to have Ms. Hanstie's favor.",
  ui_story_5071_50710101_99_dialog_content = "Now then Shadowlord, may I have a word with you in private?",
  ui_story_5071_50710101_100_dialog_content = "Pardon me, Ms. Hanstie—",
  ui_story_5071_50710101_101_dialog_content = "I was speaking to the Shadowlord, my adorable little octopus.",
  ui_story_5071_50710101_102_dialog_content = "...",
  ui_story_5071_50710101_103_dialog_content = "I will consider your request thoroughly, Ms. Hanstie.",
  ui_story_5071_50710101_104_dialog_content = "Very well then. I eagerly await your reply.",
  ui_story_5071_50710101_105_dialog_content = "Set up a meeting time between me and the lady, Kleken.",
  ui_story_5071_50710101_106_dialog_content = "... As you wish, my lord.",
  ui_story_5071_50710101_107_dialog_content = "(Wait, the Shadowlord is breaking his own rules for that flamboyant woman?)",
  ui_story_5071_50710101_108_dialog_content = "How much longer are you going to zone out in a corner, PlayerName?",
  ui_story_5071_50710101_109_dialog_content = "G-Greetings, Shadowlord! Everyone was so busy just now that I didn't have a chance to say hi sooner.",
  ui_story_5071_50710101_110_dialog_content = "Come, our turn to be on the stage.",
  ui_story_5071_50710101_111_dialog_content = "Huh?",
  ui_story_5071_50710101_112_dialog_content = "I hope everyone loved that song! Next, we welcome—",
  ui_story_5071_50710101_113_dialog_content = "Shadowlord Istvan, Cloudrover Guild leader Lady Sheol, and PlayerName, Astra's guest of honor, who will cut the ribbon together!",
  ui_story_5071_50710101_114_dialog_content = "I didn't know they'd have ceremonies like this...",
  ui_story_5071_50710101_115_dialog_content = "It's okay, dear, don't be nervous. Just cut the ribbon with the scissors in hand.",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>Snip!</color>",
  ui_story_5071_50710101_117_dialog_content = "The Cloudrover Airship is funded and built by Lady Sheol's Cloudrover Guild, a super-vessel combining tourism, shopping, recreation, and resorts all in one.",
  ui_story_5071_50710101_118_dialog_content = "From now on, ordinary Aurorians like me can play, shop, and live up in the sky like the Caelestite!",
  ui_story_5071_50710101_119_dialog_content = "After today's launch, the airship will circle Umbraton and put on a fireworks show above the town in the evening. It gets cooler the more I think about it!",
  ui_story_5071_50710101_120_dialog_content = "But don't just fixate yourself on the views and forget all the events on board!",
  ui_story_5071_50710101_121_dialog_content = "Other than meet-n-greet with me and the special screening from Umbraton's Alleywood, the airship will also host the most transparent, convenient airborne auction ever!",
  ui_story_5071_50710101_122_dialog_content = "So, let's all count it down now!",
  ui_story_5071_50710101_123_dialog_content = "Three—",
  ui_story_5071_50710101_124_dialog_content = "Two—",
  ui_story_5071_50710101_125_dialog_content = "One!",
  ui_story_5071_50710101_126_dialog_content = "The Cloudrover Airship...",
  ui_story_5071_50710101_127_dialog_content = "<size=50>Takes flight!</size>",
  ui_story_5071_50710101_128_dialog_content = "Oh! It's flying now. It's really flying!",
  ui_story_5071_50710101_129_dialog_content = "You're so easily impressed. It's not like you haven't been on an airship before. When I was in Lumopolis, I saw this happen every day.",
  ui_story_5071_50710101_130_dialog_content = "Although Lumopolis is nice, that island can't move at all. In any case, I really admire Lady Sheol's keen eye for investment.",
  ui_story_5071_50710101_131_dialog_content = "A keen eye indeed.",
  ui_story_5071_50710101_132_dialog_content = "But anything that takes to the skies...",
  ui_story_5071_50710101_X132_dialog_content = "Must come down eventually.",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>In the luxury suite of the Cloudrover Airship</color>",
  ui_story_5071_50710201_2_dialog_content = "Honorable Shadowlord, I'm so thankful we finally have the chance to meet today...",
  ui_story_5071_50710201_3_dialog_content = "Thanks to your generous assistance, my son finally realized his wish to attend school in Lumopolis!",
  ui_story_5071_50710201_4_dialog_content = "Haha, that is exciting news.",
  ui_story_5071_50710201_5_dialog_content = "Your son is very smart and has his own ideas. His hard work led up to this.",
  ui_story_5071_50710201_6_dialog_content = "However, you seem worried?",
  ui_story_5071_50710201_7_dialog_content = "I-I simply worry that the nobles and their children will harass him because of his status...",
  ui_story_5071_50710201_8_dialog_content = "My, what am I saying... Shadowlord, please forgive me for speaking such nonsense.",
  ui_story_5071_50710201_9_dialog_content = "It's natural to worry about that. Your son is very talented...",
  ui_story_5071_50710201_10_dialog_content = "I look forward to his safe return and founding an Umbraton school more than anyone else.",
  ui_story_5071_50710201_11_dialog_content = "I promise all your concerns will never come to pass.",
  ui_story_5071_50710201_12_dialog_content = "Hearing you say that makes my heart feel as light as a feather, my lord!",
  ui_story_5071_50710201_13_dialog_content = "I brought a few bottles of wine from our family's vineyard. Please accept them as a token of our gratitude, as well as our apology for taking up so much of your time...",
  ui_story_5071_50710201_14_dialog_content = "No worries. Farewell.",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>Aboard the Cloudrover Airship, at Goldie's handshake event</color>",
  ui_story_5071_50710201_16_dialog_content = "Thanks for your constant support, PlayerName!",
  ui_story_5071_50710201_17_dialog_content = "I won't let you down, and I'll keep making good music!",
  ui_story_5071_50710201_18_dialog_content = "Don't mention it! You really have a special connection with the sky, don't you? Today's song was also—",
  ui_story_5071_50710201_19_dialog_content = "Hey! Aren't we only supposed to get a minute with Goldie? You're going way over your time!",
  ui_story_5071_50710201_20_dialog_content = "Sorry, PlayerName. Don't forget to visit me at the office when you have time!",
  ui_story_5071_50710201_21_dialog_content = "Goldie! Goldie! We want to chat with you a little longer too!",
  ui_story_5071_50710201_22_dialog_content = "In no time at all, Goldie has turned so many people into her fans...",
  ui_story_5071_50710201_23_dialog_content = "Looks like all of my old friends are pretty busy right now... Guess I'll have to walk around by myself.",
  ui_story_5071_50710201_24_dialog_content = "Sir, do you still remember me? I-I used to live next door to you!",
  ui_story_5071_50710201_25_dialog_content = "You weren't home when your parents passed away... I also pitched in to cover their funeral expenses...",
  ui_story_5071_50710201_26_dialog_content = "Thank you for the generous help in giving them a peaceful resting place.",
  ui_story_5071_50710201_27_dialog_content = "Y-Yes, but... but I need your help now more than ever!",
  ui_story_5071_50710201_28_dialog_content = "Thanks to you, I was able to open a number of general stores. My business doesn't hold a candle to the Cloudrover Guild, but it does well enough around here.",
  ui_story_5071_50710201_29_dialog_content = "Unfortunately, the nearby shops have been working together to put me out of business lately. I'm already on the verge of bankruptcy...",
  ui_story_5071_50710201_30_dialog_content = "I don't know what else to do, my lord. Please help me...",
  ui_story_5071_50710201_31_dialog_content = "You want me to help you get rid of them?",
  ui_story_5071_50710201_32_dialog_content = "W-Would that be acceptable?",
  ui_story_5071_50710201_33_dialog_content = "Why not just join the guild? As long as you operate according to the regulations, they will offer you substantial protection.",
  ui_story_5071_50710201_34_dialog_content = "I... I was told that joining the guild requires a hefty membership fee...",
  ui_story_5071_50710201_35_dialog_content = "How would you know if you never stepped through their door to find out the truth?",
  ui_story_5071_50710201_36_dialog_content = "I knew it! Those scoundrels were lying to me all along!",
  ui_story_5071_50710201_37_dialog_content = "Then... Could I possibly join your guild?",
  ui_story_5071_50710201_38_dialog_content = "I'm not the leader of the guild, but I can tell you its door is always open to anyone.",
  ui_story_5071_50710201_39_dialog_content = "Trust me. You'll only regret not doing it sooner.",
  ui_story_5071_50710201_40_dialog_content = "Oh, thank you! Thank you so much, Shadowlord! From now on, I'll always pledge my support to you... and to the guild's decisions as well!",
  ui_story_5071_50710201_41_dialog_content = "The people who buried your parents should have left this world a long time ago. It seems that man and I share a similar \"hobby.\"",
  ui_story_5071_50710201_42_dialog_content = "That's not the point, Kleken. Tell him what he should do next.",
  ui_story_5071_50710201_43_dialog_content = "Very well, Shadowlord.",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>Outside the Cloudrover Airship's cinema</color>",
  ui_story_5071_50710201_45_dialog_content = "Hmm, \"A youthful tale based on a true story, 'Chasing Alleywood' is now playing with one ticket remaining.\"",
  ui_story_5071_50710201_46_dialog_content = "Is this Lilica's latest work? This would explain why I haven't heard from her for such a long time...",
  ui_story_5071_50710201_47_dialog_content = "Well, I don't have anything better to do, so I may as well show some support!",
  ui_story_5071_50710201_48_dialog_content = "Excuse me, I'd like to buy the last ticket for \"Chasing Alleywood,\" please!",
  ui_story_5071_50710201_49_dialog_content = "H-Huh? Brandy swiped the last ticket for herself!",
  ui_story_5071_50710201_50_dialog_content = "What's the matter with this child? Why won't he talk?",
  ui_story_5071_50710201_51_dialog_content = "Is he lost? Why aren't his parents looking for him?",
  ui_story_5071_50710201_52_dialog_content = "Whose child is this?",
  ui_story_5071_50710201_53_dialog_content = "What's with all those people over there? Another event?",
  ui_story_5071_50710201_54_dialog_content = "*sniffling*",
  ui_story_5071_50710201_55_dialog_content = "Huh? A little kid?",
  ui_story_5071_50710201_56_dialog_content = "Waaah—",
  ui_story_5071_50710201_57_dialog_content = "H-Hey! Why does he suddenly grab onto me like this?",
  ui_story_5071_50710201_58_dialog_content = "They must be family... That poor boy didn't hesitate to run over to him.",
  ui_story_5071_50710201_59_dialog_content = "Are you this boy's older brother? How could you leave him alone like that? Just look at his poor, crying face!",
  ui_story_5071_50710201_60_dialog_content = "You should be more careful from now on!",
  ui_story_5071_50710201_61_dialog_content = "...",
  ui_story_5071_50710201_62_dialog_content = "...",
  ui_story_5071_50710201_63_dialog_content = "Hmm... May I ask who you are?",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>*stomach growling*</color>",
  ui_story_5071_50710201_65_dialog_content = "I... I'm so hungry...",
  ui_story_5071_50710201_66_dialog_content = "I trust you have been well, Shadowlord?",
  ui_story_5071_50710201_67_dialog_content = "Marquis? I thought you've been spending all your time reading with your granddaughter in your Lumopolis estate lately.",
  ui_story_5071_50710201_68_dialog_content = "Haha, if I hadn't come, I fear a certain group and their so-called \"reforms\" would have robbed me of all that I own here in Umbraton.",
  ui_story_5071_50710201_69_dialog_content = "Tell me, with the exorbitant membership fees charged by the guild, how could they have been unable to eat their fill lately?",
  ui_story_5071_50710201_70_dialog_content = "Haha, that's a different story, sir.",
  ui_story_5071_50710201_71_dialog_content = "That small guild of yours was shut down due to a violation of the guild regulations.",
  ui_story_5071_50710201_72_dialog_content = "As long as corrections are made and the... dubious practices ditched, it's allowed to reopen.",
  ui_story_5071_50710201_73_dialog_content = "Also, most of the membership fees paid are turned over to Lumopolis as \"property tax\" as agreed.",
  ui_story_5071_50710201_74_dialog_content = "The rest is spent on the regular upkeep of the guild—",
  ui_story_5071_50710201_75_dialog_content = "Your deceitful words remind me much of your adopted daughter. If I didn't know any better, I'd say she could pass as one of your own.",
  ui_story_5071_50710201_76_dialog_content = "Why would you bother to see me when you've already heard the pitch from the guild leader then?",
  ui_story_5071_50710201_77_dialog_content = "Dispense with the charade already, Istvan...",
  ui_story_5071_50710201_78_dialog_content = "You know what Umbraton needs to sustain its current prosperity, don't you?",
  ui_story_5071_50710201_79_dialog_content = "It's the same thing that the Istvan Gang needed at its inception, remember?",
  ui_story_5071_50710201_80_dialog_content = "Your hands are far dirtier than anyone else's aboard this airship. Do you honestly think you can wash your sins away?",
  ui_story_5071_50710201_81_dialog_content = "These \"reforms\" will only be your undoing!",
  ui_story_5071_50710201_82_dialog_content = "Haha, is that so?",
  ui_story_5071_50710201_83_dialog_content = "Well, I'm somewhat looking forward to finding out...",
  ui_story_5071_50710201_84_dialog_content = "How a reform to put Umbraton on the right track could be detrimental to me.",
  ui_story_5071_50710201_85_dialog_content = "Munch, munch, gulp...",
  ui_story_5071_50710201_86_dialog_content = "Hey, slow down or else you're gonna choke!",
  ui_story_5071_50710201_87_dialog_content = "Two roast chickens, four pizzas, and five slices of cake... When did you take your last meal?",
  ui_story_5071_50710201_88_dialog_content = "Munch, munch... I-It's been three hours since my last meal... I was starving just now...",
  ui_story_5071_50710201_89_dialog_content = "You were starving after only three hours?",
  ui_story_5071_50710201_90_dialog_content = "I... I get nervous when I'm around strangers... so nervous that I burn through all my energy, so...",
  ui_story_5071_50710201_91_dialog_content = "Um... I'll be sure to pay you back for the meal!",
  ui_story_5071_50710201_92_dialog_content = "B-But could you please... help me find Lady Sheol?",
  ui_story_5071_50710201_93_dialog_content = "Lady... Sheol?",
  ui_story_5071_50710201_94_dialog_content = "M-My name's Vergil. I'm one of Lady Sheol's employees...",
  ui_story_5071_50710201_95_dialog_content = "I... I didn't realize Lady Sheol hired children to work for her.",
  ui_story_5071_50710201_96_dialog_content = "P-P-P-Please don't misunderstand! I'm the one who asked her to hire me!",
  ui_story_5071_50710201_97_dialog_content = "I don't know exactly what's going on, but I can sense Lady Sheol's presence nearby—",
  ui_story_5071_50710201_98_dialog_content = "Hold it right there!",
  ui_story_5071_50710201_99_dialog_content = "Target spotted!",
  ui_story_5071_50710201_100_dialog_content = "The guard doggies are here!",
  ui_story_5071_50710201_101_dialog_content = "Doggy attack!",
  ui_story_5071_50710201_102_dialog_content = "Isn't that... where the Shadowlord is meeting with people?",
  ui_story_5071_50710302_1_dialog_content = "Are you okay, madam?",
  ui_story_5071_50710302_2_dialog_content = "I... I'm fine. Thank you for your help.",
  ui_story_5071_50710302_3_dialog_content = "Patty, Patsy, can you tell me what's going on?",
  ui_story_5071_50710302_4_dialog_content = "Us doggies make for the best guards!",
  ui_story_5071_50710302_5_dialog_content = "No one gets past us unless they have a reservation!",
  ui_story_5071_50710302_6_dialog_content = "You sure are loyal puppies, but let's not cause such a big commotion next time.",
  ui_story_5071_50710302_7_dialog_content = "You might fall off stirring up a ruckus like that.",
  ui_story_5071_50710302_8_dialog_content = "Doggies never show fear!",
  ui_story_5071_50710302_9_dialog_content = "But it wouldn't be a good idea to disturb the Shadowlord's meeting inside.",
  ui_story_5071_50710302_10_dialog_content = "No disturbing the Shadowlord... Even we know that much!",
  ui_story_5071_50710302_11_dialog_content = "So, madam, which guild leader are you with? Please pardon me, but I don't remember sending out an invitation to someone like you.",
  ui_story_5071_50710302_12_dialog_content = "The resemblance is uncanny... When I take a closer look, you're almost exactly the same...",
  ui_story_5071_50710302_13_dialog_content = "?",
  ui_story_5071_50710302_14_dialog_content = "L... Lady Sheol!",
  ui_story_5071_50710302_15_dialog_content = "Vergil? What are you doing here? Didn't I tell you to wait for me at the auction?",
  ui_story_5071_50710302_16_dialog_content = "I-I was starving just now, so I went out to look for some food... But there were so many people outside that I ended up getting lost.",
  ui_story_5071_50710302_17_dialog_content = "But this nice person saved me, and he even paid for a big, tasty meal for me to eat!",
  ui_story_5071_50710302_18_dialog_content = "Haha... It was nothing.",
  ui_story_5071_50710302_19_dialog_content = "You've already made friends with PlayerName? I thought little Vergil wouldn't talk to strangers.",
  ui_story_5071_50710302_20_dialog_content = "Th-That's because... PlayerName gives off the scent of antiques for some reason, and it really puts me at ease...",
  ui_story_5071_50710302_21_dialog_content = "Well, that is true. You could call PlayerName a newly minted antique.",
  ui_story_5071_50710302_22_dialog_content = "PlayerName... Wait, don't tell me you're the legendary Caelestite!",
  ui_story_5071_50710302_23_dialog_content = "You have yet to answer my question, madam. Who are you and what are you doing here?",
  ui_story_5071_50710302_24_dialog_content = "A friendly reminder, the security for this ship isn't any gentler than the Shadowlord's pups.",
  ui_story_5071_50710302_25_dialog_content = "I... I am Yvonne, a writer. Cross Street Publishing House invited me here as a special guest.",
  ui_story_5071_50710302_26_dialog_content = "Please forgive me for causing a scene just now. I didn't realize that I needed a reservation to see the Shadowlord aboard the airship today.",
  ui_story_5071_50710302_27_dialog_content = "Yvonne... Wait, you mean THE Ms. Yvonne, the world-famous writer?",
  ui_story_5071_50710302_28_dialog_content = "... I'm surprised someone as young as you is familiar with my works, considering I haven't written anything new in years.",
  ui_story_5071_50710302_29_dialog_content = "Ms. Yvonne's writing is a testament to Umbraton's past. Every literate person in town has read your work.",
  ui_story_5071_50710302_30_dialog_content = "But you rarely show yourself in public, so why today...",
  ui_story_5071_50710302_31_dialog_content = "I was much younger back then and was always worried or preoccupied by one thing or another. Now that I'm older, I've gotten a bit more courageous than before.",
  ui_story_5071_50710302_32_dialog_content = "If it weren't for this, I never would have come aboard this airship alone for my unfinished manuscript.",
  ui_story_5071_50710302_33_dialog_content = "Manuscript?",
  ui_story_5071_50710302_34_dialog_content = "After my last book received such awful reviews, I was certain that I would never write again.",
  ui_story_5071_50710302_35_dialog_content = "But before long, I met and befriended a certain <color=#FFB400>artist</color> who shared a number of riveting tales with me.",
  ui_story_5071_50710302_36_dialog_content = "These stories, which were based on true events, were far more exciting than even the most carefully-worded work of fiction. I could hardly sleep after hearing them!",
  ui_story_5071_50710302_37_dialog_content = "I thought these tales deserved better than to gather dust in Umbraton's long-forgotten past. At my friend's urging, I picked up my pen once more...",
  ui_story_5071_50710302_38_dialog_content = "The story I'm working on is wonderful as it is, but I fear that certain details are still missing. For this reason, I sought to interview the Shadowlord today.",
  ui_story_5071_50710302_39_dialog_content = "... Even in spite of the danger, and my uncertainty as to whether or not he will share his knowledge with a failed writer such as myself.",
  ui_story_5071_50710302_40_dialog_content = "Danger? What's so dangerous about writing stories?",
  ui_story_5071_50710302_41_dialog_content = "If this book were to be published, everyone would know the reason behind it.",
  ui_story_5071_50710302_42_dialog_content = "I see you're keeping your readers in suspense like a good writer would.",
  ui_story_5071_50710302_43_dialog_content = "Lady Sheol, I may be overstepping my boundaries by asking, but would you please introduce me to the Shadowlord? I promise I won't take up too much of his valuable time!",
  ui_story_5071_50710302_44_dialog_content = "Well, if I refused to help, the literary circles in Umbraton would accuse us businesspeople of being uncultured money-grabbers again.",
  ui_story_5071_50710302_45_dialog_content = "Not that I ever cared about such criticism... however, I am a big fan of your books!",
  ui_story_5071_50710302_46_dialog_content = "And it's not the first time the Shadowlord has made an exception today anyway. Please give me a minute.",
  ui_story_5071_50710302_47_dialog_content = "Ahem, Ms. Yvonne? Would it be okay if Vergil got an autograph from you? He's too embarrassed to ask you himself...",
  ui_story_5071_50710302_48_dialog_content = "An autograph? That's nothing to be ashamed of, little boy! I'm just grateful that you enjoy my work this much. I only have some blank notepaper on hand, will that be a problem?",
  ui_story_5071_50710302_49_dialog_content = "N... Not at all!",
  ui_story_5071_50710302_50_dialog_content = "There, just for you. It isn't much, but if we have a chance to meet again, I'd love to present you with a copy of...",
  ui_story_5071_50710302_51_dialog_content = "That reminds me! Which of my books do you like best?",
  ui_story_5071_50710302_52_dialog_content = "I-I-I-I-I... I really enjoyed \"Mrs. Red Mercury\"!",
  ui_story_5071_50710302_53_dialog_content = "That title...",
  ui_story_5071_50710302_54_option_content = "It sounds familiar...",
  ui_story_5071_50710302_55_dialog_content = "I think I have a copy of that story on the Colossus!",
  ui_story_5071_50710302_56_option_content = "Sure enough, I've never heard of it...",
  ui_story_5071_50710302_57_dialog_content = "The story... is about a beautiful, yet cold and mysterious guild leader named Mrs. Red Mercury.",
  ui_story_5071_50710302_58_dialog_content = "In the name of love, she abandons her noble status without hesitation and travels to Umbraton.",
  ui_story_5071_50710302_59_dialog_content = "But after her husband dies, she takes control of multiple small guilds and silently avenges her fallen love.",
  ui_story_5071_50710302_60_dialog_content = "Are you talking about \"Mrs. Red Mercury\"? I love that book too.",
  ui_story_5071_50710302_61_dialog_content = "I-Is that so? I'm so glad that you like it...",
  ui_story_5071_50710302_62_dialog_content = "I've sent words, Ms. Yvonne. We shall hear back soon.",
  ui_story_5071_50710302_63_dialog_content = "That's wonderful news... Thank you so much, Lady Sheol!",
  ui_story_5071_50710302_64_dialog_content = "Fate can be such a strange thing, and I didn't want to say anything before... But you bear a striking resemblance to Lady <color=#FFB400>Melissa</color>.",
  ui_story_5071_50710302_65_dialog_content = "You know Melissa? So the book really was...",
  ui_story_5071_50710302_66_dialog_content = "Yes. The character of Mrs. Red Mercury is based on Lady Melissa, an actual person.",
  ui_story_5071_50710302_67_dialog_content = "Lady Melissa? Who's that?",
  ui_story_5071_50710302_68_dialog_content = "You don't know either, huh? If I had to guess... This Lady Melissa is someone really important to Lady Sheol.",
  ui_story_5071_50710302_69_dialog_content = "...",
  ui_story_5071_50710302_70_dialog_content = "Ms. Yvonne, I'm truly grateful for your faithful description of her in the book, giving me the chance to feel her charisma.",
  ui_story_5071_50710302_71_dialog_content = "I was told that Melissa's child was kidnapped and poisoned by her enemies... But now I see that she inherited her mother's tenacity.",
  ui_story_5071_50710302_72_dialog_content = "I don't often regret something, but now I'm having second thoughts about never investing in the publishing business. Maybe I could have met you sooner then.",
  ui_story_5071_50710302_73_dialog_content = "I'm sure we'll have plenty of opportunities to meet in the future, so long as you don't mind my prying into the past.",
  ui_story_5071_50710302_74_dialog_content = "I love stories, especially when they're about her...",
  ui_story_5071_50710302_75_dialog_content = "Moreover, I'm very interested in publishing the book you're writing now.",
  ui_story_5071_50710302_76_dialog_content = "Th-That would be...",
  ui_story_5071_50710302_77_dialog_content = "I couldn't begin to imagine the look of radiant joy on Lady Melissa's face if she could see how successful her daughter had become.",
  ui_story_5071_50710302_78_dialog_content = "Your generosity with your clients is admirable, Lady Sheol. I just wish you knew how much trouble it would create for your associates.",
  ui_story_5071_50710302_79_dialog_content = "We have a reply already?",
  ui_story_5071_50710302_80_dialog_content = "So this is the illustrious Ms. Yvonne?",
  ui_story_5071_50710302_81_dialog_content = "The Shadowlord has agreed to an audience. Right this way, please.",
  ui_story_5071_50710302_82_dialog_content = "!",
  ui_story_5071_50710302_83_dialog_content = "I'm eternally grateful for your help, Lady Sheol!",
  ui_story_5071_50710302_84_dialog_content = "You did say it's fate, yourself. I look forward to talking about your past work with you after your meeting with the Shadowlord.",
  ui_story_5071_50710302_85_dialog_content = "It would be my honor.",
  ui_story_5071_50710302_86_dialog_content = "...",
  ui_story_5071_50710302_87_dialog_content = "Why are you just standing there, dear PlayerName?",
  ui_story_5071_50710302_88_dialog_content = "Or...",
  ui_story_5071_50710302_89_dialog_content = "Have you taken a sudden interest in my past?",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>About ten years ago</color>",
  ui_story_5071_50710401_2_dialog_content = "Look! Are those people from the coalition that ended the Darkover Crisis?",
  ui_story_5071_50710401_3_dialog_content = "They're moving towards Lumopolis... Could they be knights of Lumopolis?",
  ui_story_5071_50710401_4_dialog_content = "Lumopolis Knights all wear shiny uniforms, whereas these people look dark and gray. It's most likely that they are from Umbraton.",
  ui_story_5071_50710401_5_dialog_content = "Didn't the Eclipsites raze Umbraton to the ground a long time ago? People still live there?",
  ui_story_5071_50710401_6_dialog_content = "I heard that many of them survived thanks to the help they received from Lumopolis.",
  ui_story_5071_50710401_7_dialog_content = "It's so nice to have such a powerful force watching over them. No matter how bad things get, their master will help them once they start wagging their tails.",
  ui_story_5071_50710401_8_dialog_content = "Shhh! Keep it down! These people can kill an Eclipsite with a slap, so you better be careful.",
  ui_story_5071_50710401_9_dialog_content = "Hold on. Isn't that Sheol? Hey, what are you doing?",
  ui_story_5071_50710401_10_dialog_content = "Rather than being sarcastic, why not just go talk to them? They are heroes who vanquished Eclipsites, after all.",
  ui_story_5071_50710401_11_dialog_content = "Sheol... Although you helped us drive away the Eclipsites many times, these people might be more dangerous than the Eclipsites. Be careful and try not to get yourself killed!",
  ui_story_5071_50710401_12_dialog_content = "Relax. I don't think anyone has a problem with money and taking advantage, right?",
  ui_story_5071_50710401_13_dialog_content = "Stop right there! Who are you?",
  ui_story_5071_50710401_14_dialog_content = "Don't get so wound up. See, I'm not an Eclipsite.",
  ui_story_5071_50710401_15_dialog_content = "I just want to remind everyone that it's hot and dry here, so if you're parched, there's free ice water in my shop!",
  ui_story_5071_50710401_16_dialog_content = "Unfortunately, there is no such thing as a free lunch in this world.",
  ui_story_5071_50710401_17_dialog_content = "No free lunch, but the water is free. Of course, if lunch is what you want, I sell that too!",
  ui_story_5071_50710401_18_dialog_content = "Authentic roasted desert scorpion combo boxes, something you won't get in Umbraton.",
  ui_story_5071_50710401_19_dialog_content = "Don't bother. We should get going.",
  ui_story_5071_50710401_20_dialog_content = "Shouldn't you take a break after coming all this way? You may not be tired, but what about the soldiers?",
  ui_story_5071_50710401_21_dialog_content = "Haha, they say the people here are known for their explosive temperaments, but you seem to be an exception.",
  ui_story_5071_50710401_22_dialog_content = "Everyone who wants water and a good meal, follow me!",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>Sheol takes off a glove and starts waving it around, trying her best to catch the attention of everyone around her.</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>Under the bright sunlight, a slender mark on Sheol's forearm emits a reddish glow, looking just like a snake's flickering tongue.</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>Istvan seeks out the origin of the sound and starts to observe this girl's appearance carefully.</color>",
  ui_story_5071_50710401_26_dialog_content = "Wait! I-Is that you, Melissa? No... You're...",
  ui_story_5071_50710401_27_dialog_content = "Sheol?",
  ui_story_5071_50710401_28_dialog_content = "Huh? I don't recall telling you my name.",
  ui_story_5071_50710401_29_dialog_content = "I'm somewhat known around here, but how did you...",
  ui_story_5071_50710401_30_dialog_content = "I finally found you!",
  ui_story_5071_50710401_31_dialog_content = "Haha, I thought I'd never have a chance to fulfill this promise ever again...",
  ui_story_5071_50710401_32_dialog_content = "Come! Let us return to Umbraton, your true home!",
  ui_story_5071_50710401_33_dialog_content = "(... It seems the villagers were right about how capricious and unreasonable people from Umbraton are.)",
  ui_story_5071_50710401_34_dialog_content = "Well, I do want to visit Umbraton, but I still have a shop to look after...",
  ui_story_5071_50710401_35_dialog_content = "And look at the time... I must go back there now!",
  ui_story_5071_50710401_36_dialog_content = "Please don't misunderstand—",
  ui_story_5071_50710401_37_dialog_content = "Not an inch closer!",
  ui_story_5071_50710402_1_dialog_content = "Hahah, as expected of Melissa's daughter! Even without proper training, your combat skills are not to be ignored.",
  ui_story_5071_50710402_2_dialog_content = "What do you want? I'm just a small-time trader, what value do I have to you?",
  ui_story_5071_50710402_3_dialog_content = "Forgive me for not explaining things more clearly. The truth is, I'm helping an old friend find her long-lost daughter.",
  ui_story_5071_50710402_4_dialog_content = "I grew up in the desert. What ties do I have with Umbraton?",
  ui_story_5071_50710402_5_dialog_content = "If I'm not mistaken, you have a small snake-shaped marking on your arm. Is that right?",
  ui_story_5071_50710402_6_dialog_content = "You spotted that only a second ago.",
  ui_story_5071_50710402_7_dialog_content = "Yes... But your name was inscribed on the clothes you were wearing when you disappeared: \"Sheol.\"",
  ui_story_5071_50710402_8_dialog_content = "Judging from your reaction, that seems to be what others call you as well.",
  ui_story_5071_50710402_9_dialog_content = "... Tell me, whose daughter am I?",
  ui_story_5071_50710402_10_dialog_content = "An old friend of mine by the name of Lady Melissa.",
  ui_story_5071_50710402_11_dialog_content = "If she was really my mother, why didn't she come for me herself?",
  ui_story_5071_50710402_12_dialog_content = "Because she... died of illness long ago.",
  ui_story_5071_50710402_13_dialog_content = "How convenient.",
  ui_story_5071_50710402_14_dialog_content = "...",
  ui_story_5071_50710402_15_dialog_content = "I've been carrying this all along, hoping to give it to you one day.",
  ui_story_5071_50710402_16_dialog_content = "It's... pure gold?",
  ui_story_5071_50710402_17_dialog_content = "It was left to you by your late mother. If you can use Luminatics, then you should know how to wield it.",
  ui_story_5071_50710402_18_dialog_content = "And you're just going to give it to me?",
  ui_story_5071_50710402_19_dialog_content = "When you've had enough time to consider things, come find me in Umbraton.",
  ui_story_5071_50710402_20_dialog_content = "You can count on me taking this, but not necessarily coming to see you.",
  ui_story_5071_50710402_21_dialog_content = "I'm certain you will.",
  ui_story_5071_50710402_22_dialog_content = "... What a strange fellow.",
  ui_story_5071_50710402_23_dialog_content = "But is there really such a thing as a free lunch?",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>Knock, knock, knock—</color>",
  ui_story_5071_50710402_25_dialog_content = "Enter.",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>*Footsteps*</color>",
  ui_story_5071_50710402_27_dialog_content = "Sheol?",
  ui_story_5071_50710402_28_dialog_content = "Haha, didn't I say you would come see me someday? Though from what I hear, you've been in Umbraton for quite some time now. Have you adjusted to life in this town?",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>Slap—</color>",
  ui_story_5071_50710402_30_dialog_content = "Please take a look.",
  ui_story_5071_50710402_31_dialog_content = "Hmm?",
  ui_story_5071_50710402_32_dialog_content = "I see the great Istvan Gang is dabbling in commodities now.",
  ui_story_5071_50710402_33_dialog_content = "The problem is you have no idea how to pick your supplier.",
  ui_story_5071_50710402_34_dialog_content = "The Flamefox Guild that supplies you had the gall to defraud the nobles in Lumopolis... As for the specifics, they're summarized in this file.",
  ui_story_5071_50710402_35_dialog_content = "Even I could trace it quite easily, so I'd imagine the Lumo Guards knew about it.",
  ui_story_5071_50710402_36_dialog_content = "It's only a matter of days before that \"dependable\" supplier of yours is thrown to rot in jail.",
  ui_story_5071_50710402_37_dialog_content = "When Flamefox is no more, not only do you lose your supplier, but you also have angry customers to deal with.",
  ui_story_5071_50710402_38_dialog_content = "Is this why you came here today?",
  ui_story_5071_50710402_39_dialog_content = "Let's not get tense, Shadowlord.",
  ui_story_5071_50710402_40_dialog_content = "I'm not here to kick you when you're down but to offer a win-win.",
  ui_story_5071_50710402_41_dialog_content = "If you don't mind me saying, you gangsters need professional business help.",
  ui_story_5071_50710402_42_dialog_content = "Of course, I have an exclusive special offer with your name on it.",
  ui_story_5071_50710402_43_dialog_content = "(I see. She had no intention of coming to me for help, and even started a small guild with her own two hands here in Umbraton...)",
  ui_story_5071_50710402_44_dialog_content = "(She doesn't want me to underestimate her abilities, so she comes to me with a business proposition that puts us on equal footing. Is that it?)",
  ui_story_5071_50710402_45_dialog_content = "Hahahaha! Very well then, I'll leave this shipment in your capable hands, Lady Sheol.",
  ui_story_5071_50710402_46_dialog_content = "But now I owe you a favor. Tell me what you desire, and I promise to make it yours.",
  ui_story_5071_50710402_47_dialog_content = "I always believe the only one who can fulfill my own wish is myself.",
  ui_story_5071_50710402_48_dialog_content = "I see, then I'll continue holding onto this wish for you. Should you ever change your mind, all you have to do is say so.",
  ui_story_5071_50710402_49_dialog_content = "I appreciate the offer, but I hope I never have to cash it in.",
  ui_story_5071_50710402_50_dialog_content = "Even I am surprised by your resemblance to your mother, and not just in terms of appearance...",
  ui_story_5071_50710402_51_dialog_content = "What... was she like?",
  ui_story_5071_50710402_52_dialog_content = "Much like yourself, she was a decisive and prudent guild leader. I have nothing but the utmost respect for her.",
  ui_story_5071_50710402_53_dialog_content = "Unfortunately, no amount of praise could coalesce into a clear image. I still can't grasp her...",
  ui_story_5071_50710402_54_dialog_content = "Forgive the intrusion, Shadowlord!",
  ui_story_5071_50710402_55_dialog_content = "As you predicted, the Flamefox Guild never intended to pay for our goods from the very beginning! It's all our fault for not investigating them more thoroughly!",
  ui_story_5071_50710402_56_dialog_content = "Their leader was just recently arrested by Lumopolis authorities... meaning that we probably lose our investment in this deal.",
  ui_story_5071_50710402_57_dialog_content = "Our people have reached out to other guilds with urgent requests. Should we prepare contracts for them?",
  ui_story_5071_50710402_58_dialog_content = "No. I've already found a perfectly suitable business partner for the job. Tell them to wait for further instructions.",
  ui_story_5071_50710402_59_dialog_content = "Understood!",
  ui_story_5071_50710402_60_dialog_content = "Wait, the dumb plan was your guys' fault? On second thought, that means you knew what Flamefox was doing all along?",
  ui_story_5071_50710402_61_dialog_content = "There's no need to dwell on the past any longer. We should be celebrating our newfound business collaboration, wouldn't you agree?",
  ui_story_5071_50710402_62_dialog_content = "But if they found you other guilds, why did you choose me? Is it because of my mother—",
  ui_story_5071_50710402_63_dialog_content = "Because you, Lady Sheol, are far more prudent and cooperative than those leaders who claim to be able to lead large guilds.",
  ui_story_5071_50710402_64_dialog_content = "The prospect of working with someone such as yourself brings me much joy.",
  ui_story_5071_50710402_65_dialog_content = "Then, to a happy partnership.",
  ui_story_5071_50710402_66_dialog_content = "Now then, how should I address your guild?",
  ui_story_5071_50710402_67_dialog_content = "The Cloudrover Guild.",
  ui_story_5071_50710402_68_dialog_content = "... It seems you long for that floating island in the sky as well.",
  ui_story_5071_50710402_69_dialog_content = "Lumopolis? That is truly an appealing island, but I want a free-roving version more.",
  ui_story_5071_50710402_70_dialog_content = "Roam anywhere, trade freely... What, you don't think that's realistic?",
  ui_story_5071_50710402_71_dialog_content = "Not even in the slightest. All I wish to say is that—",
  ui_story_5071_50710402_72_dialog_content = "I look forward to working with you.",
  ui_story_5071_50710402_73_dialog_content = "(I accidentally took a peek into Lady Sheol's memories. I've never seen her look so emotional before...)",
  ui_story_5071_50710402_74_dialog_content = "Why are you just standing there, dear PlayerName?",
  ui_story_5071_50710402_75_dialog_content = "Or...",
  ui_story_5071_50710402_76_dialog_content = "Have you taken a sudden interest in my past?",
  ui_story_5071_50710402_77_dialog_content = "I...",
  ui_story_5071_50710402_78_dialog_content = "I can see why you're so surprised. This is my first time seeing Lady Sheol this happy too!",
  ui_story_5071_50710402_79_dialog_content = "Since you like Ms. Yvonne so much, Vergil...",
  ui_story_5071_50710402_80_dialog_content = "Why don't I put money into a publishing house and sign her to an exclusive?",
  ui_story_5071_50710402_81_dialog_content = "Huh? I-Is that really okay?",
  ui_story_5071_50710402_82_dialog_content = "On the condition that you write a book on antiques for me first.",
  ui_story_5071_50710402_83_dialog_content = "I-I... I've been trying all along...",
  ui_story_5071_50710402_84_dialog_content = "Huh? Vergil, you actually—",
  ui_story_5071_50710402_85_dialog_content = "Heheh, Vergil may be a child, but he's an honest-to-goodness antique expert who can appraise anything!",
  ui_story_5071_50710402_86_dialog_content = "I-It's not really that impressive...",
  ui_story_5071_50710402_87_dialog_content = "Perfect timing! I picked up a stack of manuscript papers earlier. Could you tell us who it belongs to, Vergil?",
  ui_story_5071_50710402_88_dialog_content = "This is the kind of writing paper that everyone uses nowadays—",
  ui_story_5071_50710402_89_dialog_content = "Huh? Wait a minute! This is...",
  ui_story_5071_50710501_1_dialog_content = "You sure this is Ms. Yvonne's manuscript?",
  ui_story_5071_50710501_2_dialog_content = "It is! As far as I know, this is a brand-new story that's never been published before!",
  ui_story_5071_50710501_3_dialog_content = "But these pages look so old. Why hasn't it been published yet?",
  ui_story_5071_50710501_4_dialog_content = "There are plenty of reasons why authors aren't able to publish their work in time. Also, take a look at the last few pages of this manuscript—they're still fairly new!",
  ui_story_5071_50710501_5_dialog_content = "This must be the manuscript for Ms. Yvonne's unfinished book, the one she started writing years ago before going on hiatus! Ahhh, I can't wait to read it!",
  ui_story_5071_50710501_6_dialog_content = "Don't you think we should return it to its rightful owner first, Vergil?",
  ui_story_5071_50710501_7_dialog_content = "Ahhh, just the first line of this manuscript is enough to bring tears to my eyes! The last time I read one of Ms. Yvonne's works, I was no taller than an antique stool from Longzhou!",
  ui_story_5071_50710501_8_dialog_content = "Is it really that good? Let me take a look...",
  ui_story_5071_50710501_9_dialog_content = "A road paved with countless green bricks led to a Lumopolis post. Outside the post gate an open field, a pile of white stones could be seen.",
  ui_story_5071_50710501_10_dialog_content = "The local children who came here to play hide-and-seek would often be confronted by a meddlesome passerby.",
  ui_story_5071_50710501_11_dialog_content = "\"What do you little monsters think you're doing? Don't you know what this place used to be?\"",
  ui_story_5071_50710501_12_dialog_content = "With his belly poking out, one child fearlessly responded, \"Wasn't it called 'the Pit'?\"",
  ui_story_5071_50710501_13_dialog_content = "\"Yes, and it was much different than the fight clubs in the city. Do you have any idea how many people have died here?\"",
  ui_story_5071_50710501_14_dialog_content = "Seeing the children suddenly fall silent, the busybody grew even more excited. \"A hundred people would go in, but only one would survive!\"",
  ui_story_5071_50710501_15_dialog_content = "Those busybodies were right. The Pit had always been a place where the nobles entertained themselves with the deaths of others.",
  ui_story_5071_50710501_16_dialog_content = "They tied up all kinds of criminals with iron chains as thick as a bowl like animals and threw them into the Pit to fight.",
  ui_story_5071_50710501_17_dialog_content = "Of course, there were those who entered the Pit voluntarily and fearlessly just to win a bite to eat or to be noticed by a noble.",
  ui_story_5071_50710501_18_dialog_content = "However, there were also those who had been tricked into entering the Pit...",
  ui_story_5071_50710501_19_dialog_content = "If I could let the Judge in Lumopolis know that the Sheriff of Umbraton is in cahoots with the gangs...",
  ui_story_5071_50710501_20_dialog_content = "He'd certainly deal with the scum that only cared about making money over others' lives!",
  ui_story_5071_50710501_21_dialog_content = "But is the Judge really here?",
  ui_story_5071_50710501_22_dialog_content = "No, no—",
  ui_story_5071_50710501_23_dialog_content = "Stop!",
  ui_story_5071_50710501_24_dialog_content = "Please make way for me to pass!",
  ui_story_5071_50710501_25_dialog_content = "But the guards are after you. Are you a criminal?",
  ui_story_5071_50710501_26_dialog_content = "No, I'm not! You look like you're from Umbraton too, so please help me!",
  ui_story_5071_50710501_27_dialog_content = "I came to file a suit with the Lumo Hall of Justice regarding the dirty deals some nobles were doing in Umbraton, only for them to persecute me in return.",
  ui_story_5071_50710501_28_dialog_content = "I didn't mind going to jail, but they threw me in the Pit! They wanted to kill me...",
  ui_story_5071_50710501_29_dialog_content = "I can't believe you beat me to the punch! So the Hall of Justice is on the take too? Or maybe the entire Lumopolis...",
  ui_story_5071_50710501_30_dialog_content = "Where do you think you're going?",
  ui_story_5071_50710501_31_dialog_content = "They have surrounded us! I guess I'm done for.",
  ui_story_5071_50710501_32_dialog_content = "Don't speak too soon.",
  ui_story_5071_50710501_33_dialog_content = "Hey! Yes, I'm talking to you. Get outta the way!",
  ui_story_5071_50710501_34_dialog_content = "This guy can't fight worth a bean, so what has he done so wrong to be sent to his death?",
  ui_story_5071_50710501_35_dialog_content = "He doesn't have to fight. We just need to make sure there are enough people. Will you take his place?",
  ui_story_5071_50710501_36_dialog_content = "How unreasonable! They're not planning to leave me alive...",
  ui_story_5071_50710501_37_dialog_content = "Forget it. This is the end. I wasn't liked by my father, nor would I be liked by others anyway—",
  ui_story_5071_50710501_38_dialog_content = "I'll take his place.",
  ui_story_5071_50710501_39_dialog_content = "What? You don't even know me, and you would die for me?",
  ui_story_5071_50710501_40_dialog_content = "I know what I'm doing.",
  ui_story_5071_50710501_41_dialog_content = "You look like you're very educated and know better than me how to save Umbraton. If I can't make it back, promise me—",
  ui_story_5071_50710501_42_dialog_content = "Keep Umbraton alive.",
  ui_story_5071_50710501_43_dialog_content = "...",
  ui_story_5071_50710501_44_dialog_content = "It looks like one more warrior has volunteered to fight for us today!",
  ui_story_5071_50710501_45_dialog_content = "Today is your lucky day, fighters! If any of you can best him and live to tell the tale, one of these fine noblemen has agreed to double the reward!",
  ui_story_5071_50710501_46_dialog_content = "Ahahahaha—",
  ui_story_5071_50710501_47_dialog_content = "Get that horned freak!",
  ui_story_5071_50710501_48_dialog_content = "...",
  ui_story_5071_50710501_49_dialog_content = "Kill him!",
  ui_story_5071_50710501_50_dialog_content = "The people who have been cast into the Pit have already sold their souls to devils.",
  ui_story_5071_50710501_51_dialog_content = "Get him! Hurry up, you worthless fools!",
  ui_story_5071_50710501_52_dialog_content = "It's clear that they're only being used by those bloodthirsty nobles...",
  ui_story_5071_50710501_53_dialog_content = "Stop him! We'll split the prize money if you do!",
  ui_story_5071_50710501_54_dialog_content = "But only one of us can live, right?",
  ui_story_5071_50710501_55_dialog_content = "Not that horned demon anyway!",
  ui_story_5071_50710501_56_dialog_content = "Then let's not waste any more time. Come at me!",
  ui_story_5071_50710502_1_dialog_content = "Every savage blow was met with roars and shouts from the crowd. One after another, the warriors in the Pit began to fall.",
  ui_story_5071_50710502_2_dialog_content = "Some spectators shielded their faces or retreated to the furthest row in the stands, fearful that the next blazing, blue fist would reach them.",
  ui_story_5071_50710502_3_dialog_content = "The young man who was as burly as a beast and as ferocious as a demon finally stopped after knocking down his last opponents. After that, the spectators finally let out a sigh of relief.",
  ui_story_5071_50710502_4_dialog_content = "He won! He actually won even though everyone in the Pit was attacking him!",
  ui_story_5071_50710502_5_dialog_content = "His injuries are quite serious. Those people hid weapons and made many cuts on his body...",
  ui_story_5071_50710502_6_dialog_content = "I counted—he took more than a thousand slashes!",
  ui_story_5071_50710502_7_dialog_content = "A thousand wounds?",
  ui_story_5071_50710502_8_dialog_content = "...",
  ui_story_5071_50710502_9_dialog_content = "Can we go now?",
  ui_story_5071_50710502_10_dialog_content = "The person you protected can leave. As for you—",
  ui_story_5071_50710502_11_dialog_content = "Listen...",
  ui_story_5071_50710502_12_dialog_content = "Are you listening?",
  ui_story_5071_50710502_13_dialog_content = "Ahhh! Wh-What?",
  ui_story_5071_50710502_14_dialog_content = "You two are so immersed that you've completely forgotten about me.",
  ui_story_5071_50710502_15_dialog_content = "As much as I'd love to join you, I've got urgent business to tend to.",
  ui_story_5071_50710502_16_dialog_content = "Still, you should give it back to Ms. Yvonne as soon as you can.",
  ui_story_5071_50710502_17_dialog_content = "Oh, and Vergil, don't miss your auction assignment.",
  ui_story_5071_50710502_18_dialog_content = "I won't!",
  ui_story_5071_50710502_19_dialog_content = "Ms. Yvonne should be meeting with the Shadowlord right now. Why don't we go look for her over there?",
  ui_story_5071_50710502_20_dialog_content = "B-But I was just getting to the riveting part...",
  ui_story_5071_50710502_21_dialog_content = "C-Can't I read a little more?",
  ui_story_5071_50710502_22_dialog_content = "A-Ahem, fine... But only a little more, okay?",
  ui_story_5071_50710502_23_dialog_content = "Okay! Just a little more won't hurt!",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>In the luxury suite of the Cloudrover Airship</color>",
  ui_story_5071_50710601_2_dialog_content = "Thank you for granting an audience with me, honorable Shadowlord. I hereby offer you the utmost respect on behalf of the Continental Guild.",
  ui_story_5071_50710601_3_dialog_content = "You are Ms. Hanstie, the enigmatic leader of the Continental Guild? I remember that wasn't your surname.",
  ui_story_5071_50710601_4_dialog_content = "That makes two of us.",
  ui_story_5071_50710601_5_dialog_content = "... You've changed much.",
  ui_story_5071_50710601_6_dialog_content = "You think so? Oh, do you mean my leg?",
  ui_story_5071_50710601_7_dialog_content = "Even though I spent a lot of money on escaping when the Darkover overwhelmed Umbraton, I still ran into Eclipsites on the way...",
  ui_story_5071_50710601_8_dialog_content = "But that's fine since I wouldn't realize the benefits of a cybernetic leg otherwise.",
  ui_story_5071_50710601_9_dialog_content = "Haha, you're different indeed, more optimistic and resilient than before.",
  ui_story_5071_50710601_10_dialog_content = "It's bound to happen, given how much I went through.",
  ui_story_5071_50710601_11_dialog_content = "Your guild is also quite impressive and unconventional in how it often makes risky investments proscribed by the Umbraton Guild.",
  ui_story_5071_50710601_12_dialog_content = "Heheh, I see the shadow has been watching me.",
  ui_story_5071_50710601_13_dialog_content = "But you certainly aren't treating me like an old friend. Here I am visiting with good intentions, only for you to try to knock me down a peg.",
  ui_story_5071_50710601_14_dialog_content = "We're old friends, that is why I want the best for you.",
  ui_story_5071_50710601_15_dialog_content = "I don't quite understand though, isn't <color=#FFB400>your Umbraton</color> a free, tolerant town?",
  ui_story_5071_50710601_16_dialog_content = "You can obviously bring in big casinos to generate more profits for Umbraton and even easily clear the sizeable \"property tax\" to Lumopolis, so why don't you do it?",
  ui_story_5071_50710601_17_dialog_content = "You didn't start off worshipping money. Back then, you were into the arts and literature, always with a pen or paintbrush in hand—",
  ui_story_5071_50710601_18_dialog_content = "I'm not the only one who's changed.",
  ui_story_5071_50710601_19_dialog_content = "I can't believe that broke fellow I knew could grab the Shepherd's Staff and turn into <color=#FFB400>Istvan</color>.",
  ui_story_5071_50710601_20_dialog_content = "...",
  ui_story_5071_50710601_21_dialog_content = "You're right. Nothing stays the same forever. Umbraton is undergoing reform now.",
  ui_story_5071_50710601_22_dialog_content = "This is neither your Umbraton nor mine.",
  ui_story_5071_50710601_23_dialog_content = "Here, you can trade freely, except for the underground, criminal variety—that was <color=#FFB400>Valon</color>'s dream too.",
  ui_story_5071_50710601_24_dialog_content = "Why you...",
  ui_story_5071_50710601_25_dialog_content = "How tragic... Why does this have to happen to the protagonist?",
  ui_story_5071_50710601_26_dialog_content = "So even after receiving an audience with the City Lord, he was still framed by nobles and thrown in prison?",
  ui_story_5071_50710601_27_dialog_content = "The City Lord of Lumopolis never wanted to hear the protagonist's thoughts on Umbraton. He only saw the town as a pet that could fight... Once it didn't serve him any purpose, he lost interest.",
  ui_story_5071_50710601_28_dialog_content = "This book's story is a lot more complicated than the previous ones... I wonder what the protagonist will do once he gets out of jail?",
  ui_story_5071_50710601_29_dialog_content = "Maybe we should... read a little more?",
  ui_story_5071_50710601_30_dialog_content = "Yeah, just a little more!",
  ui_story_5071_50710601_31_dialog_content = "The air in the cemetery felt even colder than in the town, possibly because he had spent so much time standing there.",
  ui_story_5071_50710601_32_dialog_content = "When he left home, the only words he spoke to his parents were \"I'm leaving now.\" Now, after so many years, he failed to muster even the simplest phrase: \"I'm back.\"",
  ui_story_5071_50710601_33_dialog_content = "Footsteps slowly approached him from behind his back. \"State your business,\" he said coldly to the visitor without turning around.",
  ui_story_5071_50710601_34_dialog_content = "Soon the visitor replied: \"Kade... You've finally returned.\"",
  ui_story_5071_50710601_35_dialog_content = "Kade turned his head towards the person, a vaguely familiar face. \"Do I know you?\"",
  ui_story_5071_50710601_36_dialog_content = "You saved a certain person in the Pit all those years ago... And that person was me.",
  ui_story_5071_50710601_37_dialog_content = "You suffered for many years because of me. I can't just turn my back on you.",
  ui_story_5071_50710601_38_dialog_content = "If you don't have a place to return to, maybe you can come home with me? I'll treat you just like my very own brother!",
  ui_story_5071_50710601_39_dialog_content = "But I don't even know your name...",
  ui_story_5071_50710601_40_dialog_content = "Valon. Just call me Valon.",
  ui_story_5071_50710601_41_dialog_content = "Soon, the two young men discovered a common interest...",
  ui_story_5071_50710601_42_dialog_content = "... I've been practicing ever since I came back from the Pit.",
  ui_story_5071_50710601_43_dialog_content = "Practicing how to play chess?",
  ui_story_5071_50710601_44_dialog_content = "Luminatics. I hope to be as powerful as you someday, so that I can also dominate the battlefield.",
  ui_story_5071_50710601_45_dialog_content = "If that's the case, then I want to be just as skilled as you when it comes to chess.",
  ui_story_5071_50710601_46_dialog_content = "Haha, I never knew you liked chess too. Who taught you how to play?",
  ui_story_5071_50710601_47_dialog_content = "My father...",
  ui_story_5071_50710601_48_dialog_content = "I'm sorry, I shouldn't have asked... But from now on, my father can be your father too!",
  ui_story_5071_50710601_49_dialog_content = "I'm sure father likes you enough to adopt you! That way, we can become real brothers!",
  ui_story_5071_50710601_50_dialog_content = "...",
  ui_story_5071_50710601_51_dialog_content = "So please don't refuse, just like how I didn't refuse when you took my place in Deadly Arena.",
  ui_story_5071_50710601_52_dialog_content = "I'm just worried. Nothing about Umbraton has changed since the last time I was here. Nothing at all.",
  ui_story_5071_50710601_53_dialog_content = "... I've thought about that too. If Umbraton keeps waiting for Lumopolis' help, it will never change.",
  ui_story_5071_50710601_54_dialog_content = "We need to rely on our own strength if we want to exterminate the bloodsucking insects that are draining the life out of our town.",
  ui_story_5071_50710601_55_dialog_content = "I wonder who chose the name \"Umbraton\" for this place? Who were they to decide that we should always live in the shadows? The future is ours to decide!",
  ui_story_5071_50710601_56_dialog_content = "The future... Yes, the future of this town should be a free and unified one—a future where no one can control us any longer!",
  ui_story_5071_50710601_57_dialog_content = "I wish for the same thing, but freeing ourselves from the darkness of our past isn't something that can be done overnight...",
  ui_story_5071_50710601_58_dialog_content = "Perhaps we'll have to learn to live in peace with them, even become part of them for quite some time...",
  ui_story_5071_50710601_59_dialog_content = "No. We need to be rid of their foul influence, and it needs to be soon! No compromises.",
  ui_story_5071_50710601_60_dialog_content = "Huh?",
  ui_story_5071_50710601_61_dialog_content = "What is it?",
  ui_story_5071_50710601_62_dialog_content = "Someone's listening at the door... Should we do something about it?",
  ui_story_5071_50710601_63_dialog_content = "Ah... That's just <color=#FFB400>Ava</color>, the daughter of one of my father's friends. Don't worry, she's a friend of mine as well.",
  ui_story_5071_50710601_64_dialog_content = "We're not just friends, you know!",
  ui_story_5071_50710601_65_dialog_content = "Kade was always impressed by Valon's initiative. One day, Valon decided to approach his father, the leader of a merchant guild, for support...",
  ui_story_5071_50710601_66_dialog_content = "Absolutely not!",
  ui_story_5071_50710601_67_dialog_content = "But why not? We're trying to do the right thing!",
  ui_story_5071_50710601_68_dialog_content = "Those bloodthirsty gangs and the guilds that behave no better than them... They're a cancer to all of Umbraton!",
  ui_story_5071_50710601_69_dialog_content = "If we act quickly and decisively, we can root them all out one by one!",
  ui_story_5071_50710601_70_dialog_content = "If they could be eradicated so easily, someone would have done it long ago. Despite its chaotic nature, Umbraton maintains a certain balance that mustn't be overthrown.",
  ui_story_5071_50710601_71_dialog_content = "How many times have I warned you about being so naive? Did you learn nothing from your last lesson?",
  ui_story_5071_50710601_72_dialog_content = "You only survived because Kade was there, but what about next time?",
  ui_story_5071_50710601_73_dialog_content = "You and Kade won't be the only ones who suffer for your mistakes. Our entire family will be at risk!",
  ui_story_5071_50710601_74_dialog_content = "Father!",
  ui_story_5071_50710601_75_dialog_content = "Valon and his father had always been at constant odds. Thankfully, now Kade was there to support him...",
  ui_story_5071_50710601_76_dialog_content = "Father isn't even willing to listen to my strategy for Umbraton's future.",
  ui_story_5071_50710601_77_dialog_content = "But I am. Go ahead, tell me about it.",
  ui_story_5071_50710601_78_dialog_content = "Tell me, do you know why our guilds suffer so much at the hands of the gangs these days? It's because everyone is only looking out for themselves.",
  ui_story_5071_50710601_79_dialog_content = "I think every guild should come together and form a single body where they can enjoy shared benefits and protections. We can call it—",
  ui_story_5071_50710601_80_dialog_content = "The Umbraton Guild?",
  ui_story_5071_50710601_81_dialog_content = "Yes, we'll call it the Umbraton Guild! Only when everyone's interests are shared can we help one another defeat the common enemy!",
  ui_story_5071_50710601_82_dialog_content = "Gangs and gang-friendly guilds, predatory mercenaries... Even Lumopolis wouldn't stand a chance!",
  ui_story_5071_50710601_83_dialog_content = "Once we remove these blights from Umbraton, it'll become a pure paradise for all kinds of business.",
  ui_story_5071_50710601_84_dialog_content = "And then... I'll lead my very own guild to even more distant lands!",
  ui_story_5071_50710601_85_dialog_content = "And how would you do that?",
  ui_story_5071_50710601_86_dialog_content = "With vehicles, I suppose... Or wait, even better! I'll buy a Colossus from Eraveil and establish my guild on top of it!",
  ui_story_5071_50710601_87_dialog_content = "Together, we'll sail through the skies with the wind in our faces, traveling and trading freely across the continent!",
  ui_story_5071_50710601_88_dialog_content = "My guild won't discriminate based on wealth or status. Anyone can join and prosper, so long as they're willing to work hard for it!",
  ui_story_5071_50710601_89_dialog_content = "...",
  ui_story_5071_50710601_90_dialog_content = "What is it, Kade? Did I say something wrong?",
  ui_story_5071_50710601_91_dialog_content = "Not at all, Valon, it's a beautiful dream. Perhaps the only way to truly be free of the shadows... is to fly into the sky.",
  ui_story_5071_50710601_92_dialog_content = "I'll do whatever it takes to make that dream come true.",
  ui_story_5071_50710601_93_dialog_content = "I'll do the same too!",
  ui_story_5071_50710601_94_dialog_content = "But I thought you didn't care for business?",
  ui_story_5071_50710601_95_dialog_content = "Hmm... I can draw pretty well. Why don't I design a beautiful Colossus for your guild instead?",
  ui_story_5071_50710601_96_dialog_content = "Haha, I don't think designing the Colossus is up to us.",
  ui_story_5071_50710601_97_dialog_content = "Unfortunately, this peaceful atmosphere was not meant to last...",
  ui_story_5071_50710601_98_dialog_content = "Why do you look so upset?",
  ui_story_5071_50710601_99_dialog_content = "Father had a meeting with a business partner today and brought me with him.",
  ui_story_5071_50710601_100_dialog_content = "That's a good thing. It means he's finally willing to teach you about guild matters. This will bring us one step closer to realizing our dream.",
  ui_story_5071_50710601_101_dialog_content = "Y-You don't understand... The person he introduced me to...",
  ui_story_5071_50710601_102_dialog_content = "... was a poison dealer. If father is meeting with him, it can only mean—",
  ui_story_5071_50710601_103_dialog_content = "My family isn't innocent either, which explains why father keeps trying to stop me.",
  ui_story_5071_50710601_104_dialog_content = "I don't know how I'm supposed to face my father now. What should I do...",
  ui_story_5071_50710601_X104_dialog_content = "We can always use your father's resources to make our dreams come true.",
  ui_story_5071_50710601_105_dialog_content = "Using that kind of resource...? No, you must be joking, Kade...",
  ui_story_5071_50710601_106_dialog_content = "... I didn't realize you felt that way.",
  ui_story_5071_50710601_107_dialog_content = "You'll always be at my side no matter what, right?",
  ui_story_5071_50710601_108_dialog_content = "...",
  ui_story_5071_50710601_109_dialog_content = "Let's keep playing. You can be white this time, and I'll be black.",
  ui_story_5071_50710601_110_dialog_content = "What Valon did not know was that Kade had already made the first move.",
  ui_story_5071_50710601_111_dialog_content = "Burn every drop of poison!",
  ui_story_5071_50710601_112_dialog_content = "Understood!",
  ui_story_5071_50710601_113_dialog_content = "Ouch—",
  ui_story_5071_50710601_114_dialog_content = "Don't move!",
  ui_story_5071_50710601_115_dialog_content = "Why are you doing this to me? When have I ever wronged you?",
  ui_story_5071_50710601_116_dialog_content = "If you sold all of this poison, there's no telling how many families would perish because of it.",
  ui_story_5071_50710601_117_dialog_content = "Hah! Not even the Lumopolis Hall of Justice would care about this!",
  ui_story_5071_50710601_118_dialog_content = "... Who exactly are you?",
  ui_story_5071_50710601_119_dialog_content = "Me? I'm just... a roving shadow passing through the town, that's all.",
  ui_story_5071_50710601_120_dialog_content = "Not long afterwards and much to everyone's surprise, Valon's father convinced Kade to become his adopted son. However, Valon was not present during Kade's oath ceremony.",
  ui_story_5071_50710601_121_dialog_content = "Kade refused to show any hint of concern on his face. With his two black horns held proudly in the air, he made his vows loud enough for all to hear—",
  ui_story_5071_50710601_122_dialog_content = "\"... I hereby swear that I shall not harm my own family.\"",
  ui_story_5071_50710601_123_dialog_content = "\"Nor shall I bring harm to my family's interests...\"",
  ui_story_5071_50710701_1_dialog_content = "Valon's dreams? You have the gall to bring it up?",
  ui_story_5071_50710701_2_dialog_content = "You're the one who destroyed it all—",
  ui_story_5071_50710701_3_dialog_content = "I'm very sorry, Ms. Hanstie...",
  ui_story_5071_50710701_4_dialog_content = "But I'll still give you some advice... about choosing the right partner.",
  ui_story_5071_50710701_5_dialog_content = "I admit I know very little about running a business.",
  ui_story_5071_50710701_6_dialog_content = "But if you're interested in making money in Umbraton legally, see Lady Sheol.",
  ui_story_5071_50710701_7_dialog_content = "I can promise I'll do anything I'm able to do to help you.",
  ui_story_5071_50710701_8_dialog_content = "I don't need your promise, so save it, Shadowlord.",
  ui_story_5071_50710701_9_dialog_content = "I believe you have the wrong idea about me.",
  ui_story_5071_50710701_10_dialog_content = "Maybe we can sit down and talk about old times later when we get a chance.",
  ui_story_5071_50710701_11_dialog_content = "Shadowlord, it's time for the next meeting...",
  ui_story_5071_50710701_12_dialog_content = "Got it.",
  ui_story_5071_50710701_13_dialog_content = "I'm very glad to see you again, Ms. Hanstie.",
  ui_story_5071_50710701_14_dialog_content = "I hope you'll be mindful when dealing with those in the shadows and avoid unnecessary trouble.",
  ui_story_5071_50710701_15_dialog_content = "Thanks for the reminder, Shadowlord. I know what I am doing.",
  ui_story_5071_50710701_16_dialog_content = "Unlike some people who only talk about a certain other's dream all the time.",
  ui_story_5071_50710701_17_dialog_content = "Without actually measuring...",
  ui_story_5071_50710701_18_dialog_content = "How much has he done for it all these years?",
  ui_story_5071_50710701_19_dialog_content = "...",
  ui_story_5071_50710701_20_dialog_content = "Strange, where did my manuscript go...",
  ui_story_5071_50710701_21_dialog_content = "Could I have left it in the room?",
  ui_story_5071_50710701_22_dialog_content = "It's your turn, Ms. Yvonne!",
  ui_story_5071_50710701_23_dialog_content = "Ms. Hanstie, please follow me.",
  ui_story_5071_50710701_24_dialog_content = "Yes, I'll be right there... Hmm?",
  ui_story_5071_50710701_25_dialog_content = "My lady... Though you are clearly still quite young, your eyes have already beheld the vicissitudes of life.",
  ui_story_5071_50710701_26_dialog_content = "Your leg... My apologies, a result of my occupation, I'm afraid. Forgive me if I've offended you in any way.",
  ui_story_5071_50710701_27_dialog_content = "It's okay. I don't mind.",
  ui_story_5071_50710701_28_dialog_content = "You give me the impression of someone with many stories to tell. I find myself deeply curious to learn more about you.",
  ui_story_5071_50710701_29_dialog_content = "Also... That rich scent of lilies—",
  ui_story_5071_50710701_30_dialog_content = "It reminds me of a certain person. She used to wear a bewitching fragrance just like it.",
  ui_story_5071_50710701_31_dialog_content = "Heheh. I'm very happy to hear you say that—because I idolize Mrs. Red Mercury.",
  ui_story_5071_50710701_32_dialog_content = "I love how you portray her: mysterious, strong, uninhibited.",
  ui_story_5071_50710701_33_dialog_content = "My admiration of her silent keeper role is the reason I love lilies so much.",
  ui_story_5071_50710701_34_dialog_content = "Eternal memories, insurmountable love, and profound blessings. That is what lilies symbolize, right?",
  ui_story_5071_50710701_35_dialog_content = "But I don't like what happened to Mrs. Red Mercury in the sequels. She deserved a better ending.",
  ui_story_5071_50710701_36_dialog_content = "... Have we met before?",
  ui_story_5071_50710701_37_dialog_content = "I don't think so.",
  ui_story_5071_50710701_38_dialog_content = "Ms. Yvonne—",
  ui_story_5071_50710701_39_dialog_content = "Is someone calling my name?",
  ui_story_5071_50710701_40_dialog_content = "Ms. Yvonne, please don't make the Shadowlord wait too long.",
  ui_story_5071_50710701_41_dialog_content = "Ah! My apologies, I'll be right there.",
  ui_story_5071_50710701_42_dialog_content = "I was too late and couldn't return the manuscript to her.",
  ui_story_5071_50710701_43_dialog_content = "The guard doggies are here!",
  ui_story_5071_50710701_44_dialog_content = "No eavesdropping!",
  ui_story_5071_50710701_45_dialog_content = "Could you help us give this stack of papers to Ms. Yvonne?",
  ui_story_5071_50710701_46_dialog_content = "Good doggies shall not disturb the Shadowlord!",
  ui_story_5071_50710701_47_dialog_content = "How stubborn...",
  ui_story_5071_50710701_48_dialog_content = "Guess I'll just have to wait for her to come out.",
  ui_story_5071_50710701_49_dialog_content = "Should we...",
  ui_story_5071_50710701_X49_dialog_content = "Read just a little bit more?",
  ui_story_5071_50710701_50_dialog_content = "...",
  ui_story_5071_50710701_51_dialog_content = "Though the chessboard between the two men is spotless, a thick scent of blood and battle hangs heavily in the air.",
  ui_story_5071_50710701_52_dialog_content = "Valon makes his next move with full confidence, and the game is decided. \"Checkmate,\" he says triumphantly.",
  ui_story_5071_50710701_53_dialog_content = "\"You've lost to me yet again,\" he adds as Kade quietly gathers the chess pieces.",
  ui_story_5071_50710701_54_dialog_content = "Valon notices the lily in his friend's hand and seizes the opportunity to ask him a question. \"I heard your empire of shadows has taken in a few more people?\"",
  ui_story_5071_50710701_55_dialog_content = "Lady Melissa's people had nowhere to go after she passed away. I simply took them in.",
  ui_story_5071_50710701_56_dialog_content = "Why didn't you tell me about this sooner?",
  ui_story_5071_50710701_57_dialog_content = "I didn't think you would be interested to know.",
  ui_story_5071_50710701_58_dialog_content = "The young demi-human continues resetting the chessboard. Valon's face still does not betray the loneliness he feels in his heart.",
  ui_story_5071_50710701_59_dialog_content = "They play chess in silence, and things appear to be fine between them.",
  ui_story_5071_50710701_60_dialog_content = "I haven't had a chance to tell you how things have been lately. After all this time away from home, I've finally made some progress.",
  ui_story_5071_50710701_61_dialog_content = "I managed to unify all of the smaller businesses in the surrounding area, and the poor people here really seem to support us now. At this rate, it won't be long before I realize my dream of having a powerful guild.",
  ui_story_5071_50710701_62_dialog_content = "Congratulations.",
  ui_story_5071_50710701_63_dialog_content = "... How has father been?",
  ui_story_5071_50710701_64_dialog_content = "Fine, I suppose... But he still misses you very much.",
  ui_story_5071_50710701_65_dialog_content = "Haha, I can't help but feel a little strange when I ask about our father. I guess that makes you a better child of the Istvan family than myself.",
  ui_story_5071_50710701_66_dialog_content = "...",
  ui_story_5071_50710701_67_dialog_content = "I realize now that I can't make it on my own, Kade... I need father's Shepherd's Staff.",
  ui_story_5071_50710701_68_dialog_content = "It's a symbol of authority that has been in our family for generations. With it, I can finally take control of our family's assets.",
  ui_story_5071_50710701_69_dialog_content = "Only then can I consolidate my power and bring together the bosses of Umbraton... so that I can wipe them all out.",
  ui_story_5071_50710701_70_dialog_content = "The blue-haired young man picks up another piece and murmurs softly, \"Checkmate.\"",
  ui_story_5071_50710701_71_dialog_content = "Kade stares at the board for a few moments before turning his gaze upward. \"Your methods are too extreme.\"",
  ui_story_5071_50710701_72_dialog_content = "For Umbraton's sake, and for the sake of the weak, we must not compromise. Not even a speck of dirt shall be left behind.",
  ui_story_5071_50710701_73_dialog_content = "This isn't fair to those people.",
  ui_story_5071_50710701_74_dialog_content = "Remind me of your promise again, Kade.",
  ui_story_5071_50710701_75_dialog_content = "You said you would never betray me, right? That you would always support me and stand by my side?",
  ui_story_5071_50710701_76_dialog_content = "The young demi-human hesitates for a moment as the wind howls outside. In that brief pause, a messenger arrives with an ominous message:",
  ui_story_5071_50710701_77_dialog_content = "\"A large horde of Eclipsites has gathered and is marching straight towards Umbraton.\"",
  ui_story_5071_50710701_78_dialog_content = "In response to the looming threat, Lumopolis has begun discussing whether or not to assist Umbraton. Some believe that this is an opportunity to finally incorporate the town as part of their own.",
  ui_story_5071_50710701_79_dialog_content = "The chess players have begun to make their moves... Only natural, I suppose. Until we escape from the shadow of Lumopolis, this will continue to be the fate of our town.",
  ui_story_5071_50710701_80_dialog_content = "There is always an alternative option... If they wish to negotiate, then we should reach out to them.",
  ui_story_5071_50710701_81_dialog_content = "I'll be your rook and continue paving the way, so maintain your confidence, king.",
  ui_story_5071_50710701_X81_dialog_content = "A loud clack signaled another new game.",
  ui_story_5071_50710701_X82_dialog_content = "It was a black rook, yet it fought for the white king.",
  ui_story_5071_50710701_82_dialog_content = "Burp! Is Miss Goldie's room this way?",
  ui_story_5071_50710701_83_dialog_content = "Miss Goldie, can I have your autograph?",
  ui_story_5071_50710701_84_dialog_content = "The guard doggies are here!",
  ui_story_5071_50710701_85_dialog_content = "Ready to attack!",
  ui_story_5071_50710701_86_dialog_content = "W-W-Wait! Just let us handle this...",
  ui_story_5071_50710701_87_dialog_content = "We can't make any more trouble than we already have...",
  ui_story_5071_50710701_88_dialog_content = "Who are you?",
  ui_story_5071_50710701_89_dialog_content = "I want Miss Goldie! Miss Goldie!",
  ui_story_5071_50710702_1_dialog_content = "These people are crazy... Working security here sure is tough...",
  ui_story_5071_50710702_2_dialog_content = "There are just too many of them. It's out of our hands now, so let's keep reading!",
  ui_story_5071_50710702_3_dialog_content = "After many years, I finally found the will to continue writing this biography.",
  ui_story_5071_50710702_4_dialog_content = "At first, I considered my earlier writing to be too flattering, and possibly a misinterpretation of the objective truth. Coupled with the poor reviews of my previous works, I felt the need to stop writing indefinitely.",
  ui_story_5071_50710702_5_dialog_content = "However, a friend's account of the past immersed me in a flood of inspiration. Considering the poor reception of \"Mrs. Red Mercury\" sequels, I decided to base most of my writing on the original story rather than pure fiction.",
  ui_story_5071_50710702_6_dialog_content = "Perhaps the ending is not what my readers once imagined, but a truth this tragic deserves to be told nonetheless—",
  ui_story_5071_50710702_7_dialog_content = "This is taken straight from the true story behind Mrs. Red Mercury?",
  ui_story_5071_50710702_8_dialog_content = "I'm even more excited to read it now!",
  ui_story_5071_50710702_9_dialog_content = "With a sword like a falling star, Melissa gracefully struck at the demi-human standing before her.",
  ui_story_5071_50710702_10_dialog_content = "\"Surrender,\" she commanded coldly. \"I know you're the shadow who has been wreaking havoc in Umbraton.\"",
  ui_story_5071_50710702_11_dialog_content = "For kidnapping and selling children, you will be shown no mercy!",
  ui_story_5071_50710702_12_dialog_content = "Melissa's child was like a lost jewel to her, one that she had clung to for many years.",
  ui_story_5071_50710702_13_dialog_content = "Silently, her opponent parried the flurry of blades. It seemed he had his reasons for maintaining his stubborn silence as well.",
  ui_story_5071_50710702_14_dialog_content = "Though Melissa did not find her long-lost daughter here, she had no intention of letting this kidnapper go free.",
  ui_story_5071_50710702_15_dialog_content = "Amid the sweeping swords and shadows, the demi-human soon found himself forced into a corner of the room. Suddenly, a nearby commotion rang out.",
  ui_story_5071_50710702_16_dialog_content = "Dad—",
  ui_story_5071_50710702_17_dialog_content = "Look out!",
  ui_story_5071_50710702_18_dialog_content = "A crowd of fearful children ran out in front of the two combatants. Stunned, Melissa slowly lowered her weapon.",
  ui_story_5071_50710702_19_dialog_content = "Realizing that she had been given the wrong information, Melissa stowed her blade with a look of disappointment on her face.",
  ui_story_5071_50710702_20_dialog_content = "\"I can help you find your daughter,\" said the demi-human known as Kade, after hearing her story.",
  ui_story_5071_50710702_21_dialog_content = "But in exchange, please stay out of my affairs. Do nothing to stop me from defeating the gangs here.",
  ui_story_5071_50710702_22_dialog_content = "Almost every person in this town is corrupt in one way or another. Why bother with any of this?",
  ui_story_5071_50710702_23_dialog_content = "So that these children can grow up healthy and strong, even if we are no longer there to protect them.",
  ui_story_5071_50710702_24_dialog_content = "That... sounds a lot like the story of Lady Sheol's mother.",
  ui_story_5071_50710702_25_dialog_content = "But isn't it still a work of fiction? Maybe we should... read a little more?",
  ui_story_5071_50710702_26_dialog_content = "When Kade saw Melissa for the last time, she had already fallen terminally ill.",
  ui_story_5071_50710702_27_dialog_content = "Her disease had robbed her of her beauty and left her in a sad and haggard state.",
  ui_story_5071_50710702_28_dialog_content = "When their eyes finally met once more, Kade saw vulnerability in this once-powerful woman's gaze.",
  ui_story_5071_50710702_29_dialog_content = "\"Please help me find my daughter.\"",
  ui_story_5071_50710702_30_dialog_content = "It was her last and only request. In exchange, she had shut down any of her businesses that engaged in dark dealings.",
  ui_story_5071_50710702_31_dialog_content = "I know you'll keep your promise.",
  ui_story_5071_50710702_32_dialog_content = "Kade fell silent before her. Behind his back, a razor-sharp dagger in his hand glinted with pale coldness.",
  ui_story_5071_50710702_33_dialog_content = "Rest assured, I will do all that I can for her.",
  ui_story_5071_50710702_34_dialog_content = "Freed from all of her worries, Melissa let out a long sigh of relief.",
  ui_story_5071_50710702_35_dialog_content = "\"One last thing,\" she suddenly said. \"What are you holding behind your back?\"",
  ui_story_5071_50710702_36_dialog_content = "\"Nothing,\" Kade said as he slowly approached her, his face obscured by the shadows. \"Just a small parting gift.\"",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>The text ends abruptly here. The ink is still fresh, so it seems to be written not too long ago.</color>",
  ui_story_5071_50710702_38_dialog_content = "Huh? But how?",
  ui_story_5071_50710702_39_dialog_content = "This...",
  ui_story_5071_50710702_40_dialog_content = "What's going on with you two kids?",
  ui_story_5071_50710702_41_dialog_content = "It's time for the auction. You should go and see if there's anything you want to buy, PlayerName darling.",
  ui_story_5071_50710702_42_dialog_content = "My auction is different from the ones in Umbraton. It's transparent and open. You should check it out!",
  ui_story_5071_50710702_43_dialog_content = "The Shadowlord and I worked very hard to make this happen.",
  ui_story_5071_50710702_44_dialog_content = "All the good stuff will be gone if you don't move quickly.",
  ui_story_5071_50710702_45_dialog_content = "But I don't have much spending money... Wait, that's not important! Take a look at this, Lady Sheol!",
  ui_story_5071_50710702_46_dialog_content = "There's a woman in Ms. Yvonne's manuscript who has the same name as your mother...",
  ui_story_5071_50710702_47_dialog_content = "What? Let me see... Ms. Yvonne has always based her stories on Umbraton. This is nothing new.",
  ui_story_5071_50710702_48_dialog_content = "It's a murder... But fictions aren't real. Descriptions in a novel are usually made up.",
  ui_story_5071_50710702_49_dialog_content = "But then why would she use a real name?",
  ui_story_5071_50710702_50_dialog_content = "Don't read too much into it, darling. You can ask Ms. Yvonne after the auction is over.",
  ui_story_5071_50710702_51_dialog_content = "What's important is that the auction's about to start. You can't stay here...",
  ui_story_5071_50710702_52_dialog_content = "At least not Vergil, he still has to appraise items for me!",
  ui_story_5071_50710702_53_dialog_content = "Maybe I can get treasure on the cheap...",
  ui_story_5071_50710702_54_dialog_content = "Wait for me, Lady Sheol!",
  ui_story_5071_50710801_1_dialog_content = "I don't have any other requests save for one, Shadowlord. I only wish to publish a biography about you.",
  ui_story_5071_50710801_2_dialog_content = "That's fine. You don't have to get my permission.",
  ui_story_5071_50710801_3_dialog_content = "Umbraton welcomes creative freedom.",
  ui_story_5071_50710801_4_dialog_content = "I understand... And I'm relieved to hear you say that, but I still wish to ask you about certain details from that time...",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>At the scene of the auction on the Cloudrover Airship</color>",
  ui_story_5071_50710801_6_dialog_content = "Ahem... The item we brought for auction is \"A Corner of Rediesel Desert,\" a work of Master Finch in his travel.",
  ui_story_5071_50710801_7_dialog_content = "Master Finch is a renowned traveling artist with many famous artworks to his credit, this among them.",
  ui_story_5071_50710801_8_dialog_content = "As we can see, Master Finch portrayed the desert under a brilliant sun in layers through his unique romantic style.",
  ui_story_5071_50710801_9_dialog_content = "He unconventionally highlighted the sand in blue to make it seem like ocean waves—",
  ui_story_5071_50710801_10_dialog_content = "Huh? I thought the Cloudrover Guild was in charge of hosting auctions?",
  ui_story_5071_50710801_11_dialog_content = "We advocate free trade and equal transparency, so everybody gets to pitch their own.",
  ui_story_5071_50710801_12_dialog_content = "A lot of people in Umbraton ran underground auctions in the past. But the origins of goods were always in doubt, and the price was often unreasonable.",
  ui_story_5071_50710801_13_dialog_content = "We're different though. You can buy or sell in our auctions safely, with free appraisals to boot.",
  ui_story_5071_50710801_14_dialog_content = "Excuse me, but this painting is a counterfeit... Selling it as a genuine article would be defrauding.",
  ui_story_5071_50710801_15_dialog_content = "(This little guy seems like a totally different person when he's talking about his profession.)",
  ui_story_5071_50710801_16_dialog_content = "*noisy sounds*",
  ui_story_5071_50710801_17_dialog_content = "Everyone, please calm down! What proof have you got to call this a forgery?",
  ui_story_5071_50710801_18_dialog_content = "Exactly, are your senses more keen than ours?",
  ui_story_5071_50710801_19_dialog_content = "Well, it's pretty obvious who the seller is now...",
  ui_story_5071_50710801_20_dialog_content = "Master Finch is famous for his depictions of local customs which he saw during his travels...",
  ui_story_5071_50710801_21_dialog_content = "As a result... All of his artwork makes use of locally-sourced paints and pigments.",
  ui_story_5071_50710801_22_dialog_content = "But the color scheme in this painting does look rough and wild.",
  ui_story_5071_50710801_23_dialog_content = "The grittier highlights of \"A Corner in the Rediesel Desert\" should have been painted with bright blue pigments extracted from the subterranean layers of the desert—",
  ui_story_5071_50710801_24_dialog_content = "But this painting utilizes crushed gemstones, an uncommon luxury in the Rediesel Desert.",
  ui_story_5071_50710801_25_dialog_content = "The counterfeiter failed to take into account the absorptive properties of sand when used to extract pigments...",
  ui_story_5071_50710801_26_dialog_content = "Furthermore, the sand in the original painting created a lighter tone, as Master Finch wanted it to resemble the ocean's waves.",
  ui_story_5071_50710801_27_dialog_content = "The canvas used for this forgery was baked in order to replicate the texture of the original. In doing so, the colors were accidentally made darker...",
  ui_story_5071_50710801_28_dialog_content = "It's all your fault! Didn't I say to stay away from all the fancy tricks—",
  ui_story_5071_50710801_29_dialog_content = "Who are you blaming? You couldn't make a decent copy without me!",
  ui_story_5071_50710801_30_dialog_content = "Security, please escort them out—oh, and make sure they take their painting with them.",
  ui_story_5071_50710801_31_dialog_content = "Wow, Vergil... You really know your stuff!",
  ui_story_5071_50710801_32_dialog_content = "You think so? It's just something I'm really passionate about, that's all...",
  ui_story_5071_50710801_33_dialog_content = "Of course he does. My little employee's professionalism is never in question.",
  ui_story_5071_50710801_34_dialog_content = "And this is certainly beyond the level of a child, darling.",
  ui_story_5071_50710801_35_dialog_content = "Hmm...",
  ui_story_5071_50710801_36_dialog_content = "Hi everyone, and welcome to the auction. I'll be showing you the next item.",
  ui_story_5071_50710801_37_dialog_content = "This is an oil painting from an anonymous client of mine. The artist is also unknown.",
  ui_story_5071_50710801_38_dialog_content = "This is a masterpiece from a technical point of view. I hope you'll all like it.",
  ui_story_5071_50710801_39_dialog_content = "This painting is called—\"The Lady's Death\"!",
  ui_story_5071_50710801_40_dialog_content = "Since the value cannot be determined, the bidding will start at fifty hundred thousand.",
  ui_story_5071_50710801_41_dialog_content = "Is that... Mrs. Red Mercury in the painting? And the murderer standing at the side looks like...",
  ui_story_5071_50710801_42_dialog_content = "No, that seems to be Lady Melissa...",
  ui_story_5071_50710801_43_dialog_content = "What's this? Why does that look like the Shadowlord's back?",
  ui_story_5071_50710801_44_dialog_content = "That painting... But how could this be?",
  ui_story_5071_50710801_45_dialog_content = "PlayerName darling, would you place a bid on that painting for me?",
  ui_story_5071_50710801_46_dialog_content = "I do not know whose request it is, but I cannot bid as the guild leader, so please... Just call out the price.",
  ui_story_5071_50710801_47_dialog_content = "Sixty hundred thousand.",
  ui_story_5071_50710801_48_dialog_content = "A million.",
  ui_story_5071_50710801_49_dialog_content = "Make a move, darling!",
  ui_story_5071_50710801_50_dialog_content = "A million two!",
  ui_story_5071_50710801_51_dialog_content = "A million four!",
  ui_story_5071_50710801_52_dialog_content = "*chatters*",
  ui_story_5071_50710801_53_dialog_content = "This...",
  ui_story_5071_50710801_54_dialog_content = "(How long will it take me to save up again?)",
  ui_story_5071_50710801_55_dialog_content = "Don't just sit there, darling. Bid it up, money is no object!",
  ui_story_5071_50710801_56_dialog_content = "T-Two million!",
  ui_story_5071_50710801_57_dialog_content = "*silence*",
  ui_story_5071_50710801_58_dialog_content = "Two million going once... Any more bids? Two million going twice!",
  ui_story_5071_50710801_59_dialog_content = "Two million three times... Sold to the Caelestite!",
  ui_story_5071_50710801_60_dialog_content = "I sure am surprised that an unknown work could fetch such a price. Let's applaud the Caelestite for having such a discerning eye.",
  ui_story_5071_50710801_61_dialog_content = "Lady Sheol has good taste indeed.",
  ui_story_5071_50710801_62_dialog_content = "I didn't expect you to be into the painting enough to break the rules and get a proxy.",
  ui_story_5071_50710801_63_dialog_content = "Maybe we have much more in common than realized. No wonder the Shadowlord recommended you to me.",
  ui_story_5071_50710801_64_dialog_content = "I'm flattered. You're the one truly impressive for founding a trans-Astra guild outside of Umbraton.",
  ui_story_5071_50710801_65_dialog_content = "And I see you have ties with the Shadowlord as well. I should be the one following you.",
  ui_story_5071_50710801_66_dialog_content = "... I like you, so much so I don't mind losing the painting to you.",
  ui_story_5071_50710801_67_dialog_content = "Well, thank you, Ms. Hanstie.",
  ui_story_5071_50710801_68_dialog_content = "W-We should go pay for the painting now, Lady Sheol.",
  ui_story_5071_50710801_69_dialog_content = "Did you think I would leave you hanging, PlayerName? Come, let's go see the painting.",
  ui_story_5071_50710801_70_dialog_content = "May I come with you, Lady Sheol?",
  ui_story_5071_50710801_71_dialog_content = "Of course.",
  ui_story_5071_50710801_72_dialog_content = "Huh? Hmm... I smell something—",
  ui_story_5071_50710801_73_dialog_content = "That faint aroma...",
  ui_story_5071_50710801_74_dialog_content = "Lady Sheol... I think this fake was made by \"A,\" my favorite counterfeit artist.",
  ui_story_5071_50710801_75_dialog_content = "This is the first time I've seen one of their original works after knowing about them for so long!",
  ui_story_5071_50710801_76_dialog_content = "Oh? The auction team I hired this time isn't as professional as you, I see.",
  ui_story_5071_50710801_77_dialog_content = "The origin of this painting is unknown, so how did you deduce who the artist is, my child?",
  ui_story_5071_50710801_78_dialog_content = "Well... I tend to work with a lot of fake goods, so I've gotten pretty familiar with the work of many skilled counterfeiters.",
  ui_story_5071_50710801_79_dialog_content = "But the greatest among them is an artist known as \"A.\"",
  ui_story_5071_50710801_80_dialog_content = "Aside from their unrivaled skills, they also like to hide a tiny letter \"A\" somewhere in their forgeries. It's like a trademark of their work.",
  ui_story_5071_50710801_81_dialog_content = "Sometimes it's in a person's hair or in their eyes—this time, it's on the collar of a person's shirt.",
  ui_story_5071_50710801_82_dialog_content = "... You noticed all that? You must really like A.",
  ui_story_5071_50710801_83_dialog_content = "As much as I like \"A,\" I do think they're pretty egotistical. I mean, why else would they choose to leave a sign of their presence on a forgery?",
  ui_story_5071_50710801_84_dialog_content = "\"A\" strikes me as a person who will never give up on their quest to achieve their goals.",
  ui_story_5071_50710801_85_dialog_content = "Really? That's rather... interesting.",
  ui_story_5071_50710801_86_dialog_content = "Huh?",
  ui_story_5071_50710801_87_dialog_content = "A-A stranger...",
  ui_story_5071_50710801_88_dialog_content = "I don't think there's any point in hiding behind me now...",
  ui_story_5071_50710801_89_dialog_content = "Don't be afraid. I appreciate you very much, my child.",
  ui_story_5071_50710801_90_dialog_content = "I can tell you have great potential. Would you be interested in working for me?",
  ui_story_5071_50710801_91_dialog_content = "Sorry, Ms. Hanstie, but Vergil works for me.",
  ui_story_5071_50710801_92_dialog_content = "Oh, that's unfortunate. It seems that Lady Sheol always beats me to the punch.",
  ui_story_5071_50710801_93_dialog_content = "No, you're overstating it. But how about an artwork of your choice from my private collection for compensation?",
  ui_story_5071_50710801_94_dialog_content = "That's not necessary. I don't want to deprive others of their cherished possessions—",
  ui_story_5071_50710801_95_dialog_content = "By the way, you didn't know who painted this either, so why the affinity?",
  ui_story_5071_50710801_96_dialog_content = "I doubt you'd pay such an exorbitant price simply because of the artistic technique.",
  ui_story_5071_50710801_97_dialog_content = "Well, let's say I wanted to help an old friend out.",
  ui_story_5071_50710801_98_dialog_content = "If this painting got out to Umbraton, it would probably do great damage to the rep he's been building.",
  ui_story_5071_50710801_99_dialog_content = "But since you bought it for him, I'm done here.",
  ui_story_5071_50710801_100_dialog_content = "See you later, everyone.",
  ui_story_5071_50710801_101_dialog_content = "Wait, Ms. Hanstie, I have one more question for you.",
  ui_story_5071_50710801_102_dialog_content = "Have you known the Shadowlord for a long time?",
  ui_story_5071_50710801_103_dialog_content = "Heheh... You mean the real person? Probably longer than you think.",
  ui_story_5071_50710801_104_dialog_content = "Hmm—",
  ui_story_5071_50710801_105_dialog_content = "What's wrong with you? Staring at her like that... Are you pondering her proposal?",
  ui_story_5071_50710801_106_dialog_content = "N-N-Not at all! It's just...",
  ui_story_5071_50710801_107_dialog_content = "Vergil... You also think it's too strange to be just a coincidence, right?",
  ui_story_5071_50710801_108_dialog_content = "This painting is just like the part of the story we read in that manuscript...",
  ui_story_5071_50710801_109_dialog_content = "Could it be that Ms. Yvonne's artist friend is none other than \"A\"?",
  ui_story_5071_50710801_110_dialog_content = "She did say that she started writing again after making friends with a certain artist...",
  ui_story_5071_50710801_111_dialog_content = "You're right, darling, this is too much to be a coincidence.",
  ui_story_5071_50710801_112_dialog_content = "As if it was staged for us to see.",
  ui_story_5071_50710801_113_dialog_content = "I don't get it, Lady Sheol... What could be the point of all this?",
  ui_story_5071_50710801_114_dialog_content = "Only two explanations for this chain of events—",
  ui_story_5071_50710801_115_dialog_content = "If not to tell me the truth, it can only be...",
  ui_story_5071_50710801_116_dialog_content = "What's the follow-up for this manuscript, darling?",
  ui_story_5071_50710801_117_dialog_content = "Take a look at what comes after—",
  ui_story_5071_50710901_1_dialog_content = "Gilded staff in hand, the demi-human stood at the center of the Pit. A shouting mob led by an old friend surrounded him on all sides.",
  ui_story_5071_50710901_2_dialog_content = "\"Traitor!\" they shouted. \"Why would you lead Lumopolis' army right to Umbraton's doorstep?\"",
  ui_story_5071_50710901_3_dialog_content = "The demi-human remained silent, his steely gaze focused on a single man's face. Beneath his blue locks, Valon's eyes were full of pain and sadness.",
  ui_story_5071_50710901_4_dialog_content = "After a long while, Valon finally opened his mouth to speak. \"Kade... Why? Why did you kill our father and steal the Shepherd's Staff?\"",
  ui_story_5071_50710901_5_dialog_content = "Have you turned your back on our dream? Why would you obey the will of Lumopolis?",
  ui_story_5071_50710901_6_dialog_content = "The Pit... I faced so many enemies in your place all those years ago. Do you really think you can stop me with so few people?",
  ui_story_5071_50710901_7_dialog_content = "A single question was enough to send panic coursing through the entire crowd.",
  ui_story_5071_50710901_8_dialog_content = "What... But I thought they were best friends?",
  ui_story_5071_50710901_9_dialog_content = "... Keep reading.",
  ui_story_5071_50710901_10_dialog_content = "\"You're too weak! That's why I have to replace you!\"",
  ui_story_5071_50710901_11_dialog_content = "With a roar, Kade rushed forward and drove the staff through his friend's chest. His crazed and twisted visage was no longer recognizable, even to his own sibling.",
  ui_story_5071_50710901_12_dialog_content = "Wh-Why...",
  ui_story_5071_50710901_13_dialog_content = "I refuse to be anyone's shadow.",
  ui_story_5071_50710901_14_dialog_content = "With his face still frozen in shock, the blue-haired youth crumpled to the ground. Soon the crowd was filled with despair.",
  ui_story_5071_50710901_15_dialog_content = "In their pain and fury, they leaped into the fray—",
  ui_story_5071_50710901_16_dialog_content = "F-Flip to the next page!",
  ui_story_5071_50710901_17_dialog_content = "Kade's brutal fury had finally been unleashed. For standing in his way, he quickly tore through his fellow citizens of Umbraton.",
  ui_story_5071_50710901_18_dialog_content = "To eradicate all dissent, he bathed Umbraton in an azure inferno, ensuring that none were spared from his wrath.",
  ui_story_5071_50710901_19_dialog_content = "In a peremptory way, he finally grabbed absolute authority in his hands.",
  ui_story_5071_50710901_20_dialog_content = "In order to take control of Umbraton, he betrayed his dream and surrendered his home to Lumopolis.",
  ui_story_5071_50710901_21_dialog_content = "To that end, he took his brother's life and surname, and usurped his family's prominent status—",
  ui_story_5071_50710901_22_dialog_content = "He chose to walk a path of evil and wickedness. As he rose to power, he covered up his past and the existence of Valon, his former brother.",
  ui_story_5071_50710901_23_dialog_content = "When Umbraton finally falls under his full control, no one recalls any part of his vicious past.",
  ui_story_5071_50710901_24_dialog_content = "All that they know is that he commands his gang with a bloodstained staff.",
  ui_story_5071_50710901_25_dialog_content = "Istvan, the Shadowlord of Umbraton.",
  ui_story_5071_50710901_26_dialog_content = "Wh-What?",
  ui_story_5071_50710901_27_dialog_content = "This Kade guy... He was the Shadowlord all along?",
  ui_story_5071_50710901_28_dialog_content = "That can't be right! The Shadowlord would never betray Umbraton like that!",
  ui_story_5071_50710901_29_dialog_content = "(I've always sensed something dangerous hidden in the Shadowlord's heart, but the story in this manuscript...)",
  ui_story_5071_50710901_30_dialog_content = "...",
  ui_story_5071_50710901_31_dialog_content = "Lady Sheol, the Shadowlord...",
  ui_story_5071_50710901_32_dialog_content = "People are secretive. We can't just believe what they say but—",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5071_50710901_34_dialog_content = "What's going on? Where did that explosion come from?",
  ui_story_5071_50710901_35_dialog_content = "Lady Sheol! F-For some reason, guards of Lumopolis aboard suddenly attacked us!",
  ui_story_5071_50710901_36_dialog_content = "Why would Lumopolis guards attack us?",
  ui_story_5071_50710901_37_dialog_content = "Have I run afoul of somebody?",
  ui_story_5071_50710901_38_dialog_content = "Stop it! What do you think you're doing to Lady Sheol's airship?",
  ui_story_5071_50710901_39_dialog_content = "We're still in the air! If you keep damaging the airship, everyone on board will die—",
  ui_story_5071_50710901_40_dialog_content = "Let's teach these fools a harsh lesson!",
  ui_story_5071_50710901_41_dialog_content = "Stop! Don't do this...",
  ui_story_5071_50710901_42_dialog_content = "This will put everyone in grave danger!",
  ui_story_5071_50710901_43_dialog_content = "Stop messing with my turf!",
  ui_story_5071_50710901_X43_dialog_content = "H-Huh?!",
  ui_story_5071_50710901_X44_dialog_content = "Why you ignorant louts...",
  ui_story_5071_50710901_X45_dialog_content = "How dare you try to destroy my airship!",
  ui_story_5071_50710901_X46_dialog_content = "Eek!",
  ui_story_5071_50710901_X47_dialog_content = "Wh-What an incredible drop-kick!",
  ui_story_5071_50710901_X48_dialog_content = "I can't believe that's my boss!",
  ui_story_5071_50710901_X49_dialog_content = "T-This is the first time I've seen her fight!",
  ui_story_5071_50710901_44_dialog_content = "Wh-What an incredible drop-kick—",
  ui_story_5071_50710901_45_dialog_content = "Lady Sheol...",
  ui_story_5071_50710901_46_dialog_content = "Shadowlord, there seems to be a commotion outside. Someone seems to have sneaked in.",
  ui_story_5071_50710901_47_dialog_content = "Oh?",
  ui_story_5071_50710901_48_dialog_content = "I see the \"guest\" is getting impatient. Interesting.",
  ui_story_5071_50710901_49_dialog_content = "?",
  ui_story_5071_50711001_1_dialog_content = "What's going on?",
  ui_story_5071_50711001_2_dialog_content = "Shadowlord! You're finally here! These—",
  ui_story_5071_50711001_3_dialog_content = "Shadowlord, why are you doing this? Didn't you order us to do this?",
  ui_story_5071_50711001_4_dialog_content = "You commanded us to remove these troublemakers, so why are you...",
  ui_story_5071_50711001_5_dialog_content = "!",
  ui_story_5071_50711001_6_dialog_content = "So the Shadowlord is behind this?",
  ui_story_5071_50711001_7_dialog_content = "No wonder these Lumopolis guards are...",
  ui_story_5071_50711001_8_dialog_content = "Why are they treating us like this...",
  ui_story_5071_50711001_9_dialog_content = "Be quiet. The situation isn't—",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>Countless pieces of paper suddenly fly through the air and fall like snowflakes. These are—</color>",
  ui_story_5071_50711001_11_dialog_content = "Ms. Yvonne's manuscripts?",
  ui_story_5071_50711001_12_dialog_content = "All the pages have been scattered everywhere! Who could have...",
  ui_story_5071_50711001_13_dialog_content = "Wait, these manuscript pages are all the same. Take a look.",
  ui_story_5071_50711001_14_dialog_content = "After many years, I finally returned to this place. Istvan is the ruler of Umbraton now, and Valon's dream of Umbraton Guild has become a tool of his authority.",
  ui_story_5071_50711001_15_dialog_content = "Should I continue writing for the sake of the truth? Or should I keep these stories buried deep in my heart?",
  ui_story_5071_50711001_16_dialog_content = "I have always watched as wicked events unfolded before me, wearing away at my conscience. At first, I thought I had grown used to it.",
  ui_story_5071_50711001_17_dialog_content = "If I hadn't uncovered the truth of his latest ambitions, I may have continued spectating from a distance—",
  ui_story_5071_50711001_18_dialog_content = "Through pure chance, I learned of Istvan's insatiable greed from his subordinates. Though he sits squarely at the top of the sit, he still desires more.",
  ui_story_5071_50711001_19_dialog_content = "Though he presents himself as a generous ruler, he is secretly dissatisfied with the neutral gangs and guilds.",
  ui_story_5071_50711001_20_dialog_content = "Those who operate outside of his guild's control have put him on edge... He will not suffer rebellion of any kind.",
  ui_story_5071_50711001_21_dialog_content = "For this reason, he plans to use the Cloudrover Guild to gather his would-be opposition and destroy them once and for all. By doing so, he will attain what he has always sought—absolute control over Umbraton.",
  ui_story_5071_50711001_22_dialog_content = "With what little time I have left in this world, I wish to exact justice upon a man whose past has been forgotten.",
  ui_story_5071_50711001_23_dialog_content = "—Signed, Yvonne.",
  ui_story_5071_50711001_24_dialog_content = "Is this true?",
  ui_story_5071_50711001_25_dialog_content = "Ms. Yvonne and the Shadowlord just had a meeting, right?",
  ui_story_5071_50711001_26_dialog_content = "Calm down! There's something weird about this manuscript.",
  ui_story_5071_50711001_27_dialog_content = "Since the Shadowlord is here, doesn't that mean Ms. Yvonne is...",
  ui_story_5071_50711001_28_dialog_content = "This is way too one-sided...",
  ui_story_5071_50711001_29_dialog_content = "Will we all be silenced?",
  ui_story_5071_50711001_30_dialog_content = "Do you have more? Show us!",
  ui_story_5071_50711001_31_dialog_content = "H-Hang on!",
  ui_story_5071_50711001_32_dialog_content = "Please keep your composure, everyone.",
  ui_story_5071_50711001_33_dialog_content = "Th-This is...",
  ui_story_5071_50711001_34_dialog_content = "Is this true? Is this really an account of the Shadowlord's past?",
  ui_story_5071_50711001_35_dialog_content = "*sigh* They're not listening at all—",
  ui_story_5071_50711001_36_dialog_content = "Those rumors were actually true? And he wants to kill us now?",
  ui_story_5071_50711001_37_dialog_content = "Stop arguing. This is just a novel. Do you really believe it's true?",
  ui_story_5071_50711001_38_dialog_content = "But it matches the rumors perfectly...",
  ui_story_5071_50711001_39_dialog_content = "Since you know those are rumors, how credible do you think they are?",
  ui_story_5071_50711001_40_dialog_content = "But the Umbraton Guild really does control our trade routes. How do you know that he isn't using us to make himself more powerful?",
  ui_story_5071_50711001_41_dialog_content = "All our money is deposited at the Umbraton Guild... If he really decides to kill us and take our money...",
  ui_story_5071_50711001_42_dialog_content = "Stupid merchants, bad merchants! Why do you believe everything you hear?",
  ui_story_5071_50711001_43_dialog_content = "The boss is not that kind of person!",
  ui_story_5071_50711001_44_dialog_content = "It's just an adaptation!",
  ui_story_5071_50711001_45_dialog_content = "Are you not going to explain, Shadowlord?",
  ui_story_5071_50711001_46_dialog_content = "(Shadowlord?)",
  ui_story_5071_50711001_47_dialog_content = "(Is he... watching them?)",
  ui_story_5071_50711001_48_dialog_content = "It seems the leader of the Red Panther Guild has something to say... The Gray Parrot Guild, as well...",
  ui_story_5071_50711001_49_dialog_content = "(No, that's not it...)",
  ui_story_5071_50711001_50_dialog_content = "The Rusted Falcon Gang, too... I see.",
  ui_story_5071_50711001_51_dialog_content = "(He's sizing up his prey.)",
  ui_story_5071_50711001_52_dialog_content = "Reporting in! This is bad, Lady Sheol!",
  ui_story_5071_50711001_53_dialog_content = "Ms. Yvonne is...",
  ui_story_5071_50711001_54_dialog_content = "<size=45>Ms. Yvonne is dead in the temporary reception room!</size>",
  ui_story_5071_50711101_1_dialog_content = "The cleaner responsible for cleaning this temporary reception room is the one who made the discovery.",
  ui_story_5071_50711101_2_dialog_content = "Everything is neat and tidy at the scene. No struggle took place between the victim and the murderer.",
  ui_story_5071_50711101_3_dialog_content = "The only thing we found was some hair on the rug that Ms. Yvonne was lying on.",
  ui_story_5071_50711101_4_dialog_content = "This isn't the hair of an ordinary Aurorian. In fact, it looks more like the hair of a beast, but it has been kept in excellent condition...",
  ui_story_5071_50711101_5_dialog_content = "Shadowlord, this temporary reception room was lent to you... right?",
  ui_story_5071_50711101_6_dialog_content = "Remind us where you were just now, my lord?",
  ui_story_5071_50711101_7_dialog_content = "Watch what you're saying. Are you doubting my boss?",
  ui_story_5071_50711101_8_dialog_content = "Seleucid.",
  ui_story_5071_50711101_9_dialog_content = "But boss...",
  ui_story_5071_50711101_10_dialog_content = "You ought to be more thoughtful if it was only a conjecture and not an outright accusation.",
  ui_story_5071_50711101_11_dialog_content = "Until a moment ago, I was discussing Ms. Yvonne's books with her.",
  ui_story_5071_50711101_12_dialog_content = "I only came to see what the commotion was.",
  ui_story_5071_50711101_13_dialog_content = "But she was excited at the time, stating she'd just been struck by sudden inspiration.",
  ui_story_5071_50711101_14_dialog_content = "So I left her alone, not wanting to disturb her.",
  ui_story_5071_50711101_15_dialog_content = "And then she died. How is that possible?",
  ui_story_5071_50711101_16_dialog_content = "We just heard that Ms. Yvonne has some incriminating material about the Shadowlord's past.",
  ui_story_5071_50711101_17_dialog_content = "It's fishy how she died...",
  ui_story_5071_50711101_18_dialog_content = "Everyone, please don't propagate rumors among the crowd.",
  ui_story_5071_50711101_19_dialog_content = "Who is it? Who's starting rumors? Show yourself!",
  ui_story_5071_50711101_20_dialog_content = "Maybe we'll also be devoured by the shadows, just like her.",
  ui_story_5071_50711101_21_dialog_content = "May I ask who you are, sir? It seems you truly wish to <color=#FFB400>speak your mind</color>, so why not take a step closer for all of us to hear?",
  ui_story_5071_50711101_22_dialog_content = "Enough, Kleken.",
  ui_story_5071_50711101_23_dialog_content = "Do not ruin Sheol's important day.",
  ui_story_5071_50711101_24_dialog_content = "Ah... How could this be...",
  ui_story_5071_50711101_25_dialog_content = "Ms. Yvonne...",
  ui_story_5071_50711101_26_dialog_content = "She looks so peaceful with that smile on her face, as if she's just sleeping...",
  ui_story_5071_50711101_27_dialog_content = "She doesn't have any injuries, so we can rule out an ambush.",
  ui_story_5071_50711101_28_dialog_content = "Is it possible... that she was poisoned?",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5071_50711101_30_dialog_content = "Th-The airship is shaking!",
  ui_story_5071_50711101_31_dialog_content = "It's probably due to the attack just now. Do not panic, everyone.",
  ui_story_5071_50711101_32_dialog_content = "This airship is sturdy and dependable—",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5071_50711101_34_dialog_content = "... Contact the engineering lead and tell them to check for damage.",
  ui_story_5071_50711101_35_dialog_content = "Yes, ma'am!",
  ui_story_5071_50711101_36_dialog_content = "Everybody, please remain calm and listen to me.",
  ui_story_5071_50711101_37_dialog_content = "Today is an important day for my friend. I'm here strictly to celebrate her dream come true.",
  ui_story_5071_50711101_38_dialog_content = "I will not sabotage this cheerful occasion, or tolerate anyone to do so.",
  ui_story_5071_50711101_39_dialog_content = "The Guardians will board and investigate as soon as we land.",
  ui_story_5071_50711101_40_dialog_content = "Of course, they'll also scrutinize me. I accept all consequences should they find me involved in any way.",
  ui_story_5071_50711101_41_dialog_content = "But don't the Guardians follow the orders of the Umbraton Guild...?",
  ui_story_5071_50711101_42_dialog_content = "And they're all from the Istvan Gang.",
  ui_story_5071_50711101_43_dialog_content = "Isn't your daughter the head of the Umbraton Guild?",
  ui_story_5071_50711101_44_dialog_content = "I don't know you at all, but it seems you have a strong opinion of me.",
  ui_story_5071_50711101_45_dialog_content = "Is that a threat?",
  ui_story_5071_50711101_46_dialog_content = "I'm curious, Shadowlord. Would you really be punished?",
  ui_story_5071_50711101_47_dialog_content = "The so-called Umbraton Security Regulation was just announced. Your promise is too hollow!",
  ui_story_5071_50711101_48_dialog_content = "I never expected Ms. Yvonne's death. What a shame...",
  ui_story_5071_50711101_49_dialog_content = "As your old friend, I thought you might have changed.",
  ui_story_5071_50711101_50_dialog_content = "Even after all these years, it seems you and Umbraton still haven't forgotten about the scars from the past.",
  ui_story_5071_50711101_51_dialog_content = "Istvan... no, <color=#FFB400>Kade</color>, are you really not going to let us live?",
  ui_story_5071_50711101_52_dialog_content = "Will you do as you did all those years ago...",
  ui_story_5071_50711101_53_dialog_content = "and destroy all who disobey you once again?",
  ui_story_5071_50711101_54_dialog_content = "...",
  ui_story_5071_50711101_55_dialog_content = "*whispers*",
  ui_story_5071_50711101_56_dialog_content = "I heard that the Shadowlord removed everyone who opposed him to...",
  ui_story_5071_50711101_57_dialog_content = "You're talking about that Pit incident in the manuscripts, right?",
  ui_story_5071_50711101_58_dialog_content = "The Pit was packed full of Umbraton leaders before the Darkover Crisis hit us. I heard the Shadowlord fought one against a hundred in there.",
  ui_story_5071_50711101_59_dialog_content = "That's right. They were just like us. They were also leaders of Umbraton...",
  ui_story_5071_50711101_60_dialog_content = "He's so powerful. That's why he's the Shadowlord.",
  ui_story_5071_50711101_61_dialog_content = "Do you hear that, <color=#FFB400>Kade</color>? Your past hasn't been completely obscured.",
  ui_story_5071_50711101_62_dialog_content = "You murdered your friend and your adoptive father, and I know I'm not the only one who remembers!",
  ui_story_5071_50711101_63_dialog_content = "So those manuscripts...",
  ui_story_5071_50711101_64_dialog_content = "I'm afraid the past is far crueler than what is documented. He may have adopted even more shameless and unscrupulous means to get where he is now—",
  ui_story_5071_50711101_65_dialog_content = "He's definitely capable of doing something like that!",
  ui_story_5071_50711101_66_dialog_content = "His methods are totally unacceptable. Can we still trust him?",
  ui_story_5071_50711101_67_dialog_content = "I heard a long time ago that he betrayed his friend and surrendered to Lumopolis to attain his current status...",
  ui_story_5071_50711101_68_dialog_content = "He's the legendary demonic son...",
  ui_story_5071_50711101_69_dialog_content = "All these so-called reforms completely ignore our interests. What are they intended to...",
  ui_story_5071_50711101_70_dialog_content = "Does he really want to eliminate all of us?",
  ui_story_5071_50711101_71_dialog_content = "I'm truly happy to see you again today... <color=#FFB400>Ava</color>.",
  ui_story_5071_50711101_72_dialog_content = "But even now I don't understand why you would pick this moment to show up.",
  ui_story_5071_50711101_73_dialog_content = "For a fleeting second, I sincerely hoped you were here for his dreams.",
  ui_story_5071_50711101_74_dialog_content = "But this is your true intent, I see.",
  ui_story_5071_50711101_75_dialog_content = "You and I are not the same. I'm the only one who truly remembers his dreams.",
  ui_story_5071_50711101_76_dialog_content = "Lady Sheol, we should land once the engineering staff is done with the inspection.",
  ui_story_5071_50711101_77_dialog_content = "The Guardians should be on their way and will handle the rest.",
  ui_story_5071_50711101_78_dialog_content = "But there is only wilderness below us now.",
  ui_story_5071_50711101_79_dialog_content = "We're not far from Eclipsite territory either.",
  ui_story_5071_50711101_80_dialog_content = "That man... might not let us leave like this.",
  ui_story_5071_50711101_81_dialog_content = "Is it possible that for the sake of the reform, he'll even...",
  ui_story_5071_50711101_82_dialog_content = "There's no need to fear, everyone!",
  ui_story_5071_50711101_83_dialog_content = "My guild has a number of smaller airships stationed nearby. If you're willing to trust me, I will gladly transport all of you back to Umbraton.",
  ui_story_5071_50711101_84_dialog_content = "Take me! I'll leave with you!",
  ui_story_5071_50711101_85_dialog_content = "Nothing will happen yet since there are still a lot of people here, but if we continue to stay on this airship...",
  ui_story_5071_50711101_86_dialog_content = "I've got a family. I don't want to die!",
  ui_story_5071_50711101_87_dialog_content = "*whispers*",
  ui_story_5071_50711101_88_dialog_content = "I-I'll come with you too.",
  ui_story_5071_50711101_89_dialog_content = "Me too!",
  ui_story_5071_50711101_90_dialog_content = "Let's get out of here now. I don't want to stay here.",
  ui_story_5071_50711101_91_dialog_content = "Come on, why are you treating us like we're some sort of villains?",
  ui_story_5071_50711101_92_dialog_content = "You're the ones who've been licking our butts all along!",
  ui_story_5071_50711101_93_dialog_content = "Hey, you might be the ones in trouble if you leave with her.",
  ui_story_5071_50711101_94_dialog_content = "After all, we can't guarantee we won't do anything similar if you stay.",
  ui_story_5071_50711101_95_dialog_content = "Run, run!",
  ui_story_5071_50711101_96_dialog_content = "Let them go.",
  ui_story_5071_50711101_97_dialog_content = "Clearly, Ms. Hanstie has her own plan.",
  ui_story_5071_50711101_98_dialog_content = "And to that end, she definitely would not harm her precious audience.",
  ui_story_5071_50711101_99_dialog_content = "But they'll surely sling mud if we let them go—",
  ui_story_5071_50711101_100_dialog_content = "Follow them in a small airship.",
  ui_story_5071_50711101_101_dialog_content = "Just keep your distance and make sure the people are safe.",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5071_50711101_103_dialog_content = "It seems this airship truly is doomed. I should warn you all—",
  ui_story_5071_50711101_104_dialog_content = "Continuing to stay at that man's side will only put you in mortal danger.",
  ui_story_5071_50711101_105_dialog_content = "Please don't talk about the Shadowlord like that, especially since he hasn't done anything yet.",
  ui_story_5071_50711101_106_dialog_content = "He may keep himself hidden in the shadows all the time, but I know who he really is.",
  ui_story_5071_50711101_107_dialog_content = "He is a man who slaughtered his brother and robbed his adoptive father of everything. Not only that, he made every effort to ensure that no one remembered them at all.",
  ui_story_5071_50711101_108_dialog_content = "A man who would abandon his own name, all for personal gain.",
  ui_story_5071_50711101_109_dialog_content = "He's nothing but a demon who tramples over anyone between him and the throne he seeks.",
  ui_story_5071_50711101_X109_dialog_content = "You're not fit to hold the <color=#FFB400>Shepherd's Staff</color>, Kade!",
  ui_story_5071_50711101_110_dialog_content = "...",
  ui_story_5071_50711101_111_dialog_content = "... No matter what you say, I still choose to believe in the Shadowlord that I've always known.",
  ui_story_5071_50711101_112_dialog_content = "Nicely put, but pardon me, Ms. Hanstie, you may leave first.",
  ui_story_5071_50711101_113_dialog_content = "Sorry. I think I'm better off staying here.",
  ui_story_5071_50711101_114_dialog_content = "I smell breaking news, so I'm not leaving either.",
  ui_story_5071_50711101_115_dialog_content = "...",
  ui_story_5071_50711101_116_dialog_content = "You'll regret it, every single one of you.",
  ui_story_5071_50711101_117_dialog_content = "Why turn a blind eye to his tyranny when you know what he's capable of?",
  ui_story_5071_50711101_118_dialog_content = "Pitiful... You're all so pitiful.",
  ui_story_5071_50711101_119_dialog_content = "Goodbye, \"Ms. Hanstie.\"",
  ui_story_5071_50711101_120_dialog_content = "Well then, you should also...",
  ui_story_5071_50711101_121_dialog_content = "I sense enemies!",
  ui_story_5071_50711101_122_dialog_content = "Lady Sheol, watch out! Those soldiers...",
  ui_story_5071_50711101_123_dialog_content = "They have accomplices! They—",
  ui_story_5071_50711101_124_dialog_content = "Shut up!",
  ui_story_5071_50711101_125_dialog_content = "Remember what the boss said. Leave no survivors.",
  ui_story_5071_50711101_126_dialog_content = "This isn't good! <size=45>Everyone, get ready for battle!</size>",
  ui_story_5071_50711102_1_dialog_content = "The security personnel are all...",
  ui_story_5071_50711102_2_dialog_content = "It looks like everyone was slaughtered. *sigh*",
  ui_story_5071_50711102_3_dialog_content = "It's a good thing we're on this side...",
  ui_story_5071_50711102_4_dialog_content = "Are you okay, boss? Look outside the window, I'm here!",
  ui_story_5071_50711102_5_dialog_content = "I sent you to make sure the people were safe. What are you doing back here?",
  ui_story_5071_50711102_6_dialog_content = "I noticed there were enemies acting suspiciously and got worried about you.",
  ui_story_5071_50711102_7_dialog_content = "So, you have it under control, boss?",
  ui_story_5071_50711102_8_dialog_content = "... Come and get everyone out of here.",
  ui_story_5071_50711102_9_dialog_content = "Disregarding PlayerName, why are you staying, Vergil?",
  ui_story_5071_50711102_10_dialog_content = "Huh? This is your ship, isn't it, boss?",
  ui_story_5071_50711102_11_dialog_content = "What's the matter? I'm still on the clock, so I should be on my best behavior, right?",
  ui_story_5071_50711102_12_dialog_content = "...",
  ui_story_5071_50711102_13_dialog_content = "I just read over those manuscripts, Shadowlord.",
  ui_story_5071_50711102_14_dialog_content = "Their contents are believable, but I still don't believe it.",
  ui_story_5071_50711102_15_dialog_content = "So I have to ask, did you really do all of those things? To Lady Melissa—",
  ui_story_5071_50711102_16_dialog_content = "PlayerName!",
  ui_story_5071_50711102_17_dialog_content = "It's wrong of you to bypass me and hold the responsible party accountable.",
  ui_story_5071_50711102_18_dialog_content = "S-Sorry...",
  ui_story_5071_50711102_19_dialog_content = "Though now is not the time to discuss this matter.",
  ui_story_5071_50711102_20_dialog_content = "We're still on the airship, and we have to deal with the malfunction first.",
  ui_story_5071_50711102_21_dialog_content = "When this is over, you bet I'll get my payback with interest.",
  ui_story_5071_50711102_22_dialog_content = "I will wait for you.",
  ui_story_5071_50711102_23_dialog_content = "By the way, you're a generous person, aren't you, Shadowlord?",
  ui_story_5071_50711102_24_dialog_content = "You've obviously put in a lot of effort for those people and did a lot of favors for them.",
  ui_story_5071_50711102_25_dialog_content = "Only for them to abandon you and run at the slightest urging.",
  ui_story_5071_50711102_26_dialog_content = "Hey! Lady Sheol, why are you making underhanded comments too?",
  ui_story_5071_50711102_27_dialog_content = "Stop it, now! This is not the time to be fighting each other. We have to come together.",
  ui_story_5071_50711102_28_dialog_content = "I'd love to interview the Shadowlord now, but this probably isn't the right time...",
  ui_story_5071_50711102_29_dialog_content = "Shadowlord, what should we do now?",
  ui_story_5071_50711102_30_dialog_content = "I appreciate all of you keeping faith in me.",
  ui_story_5071_50711102_31_dialog_content = "My people will return you safely to the ground.",
  ui_story_5071_50711102_32_dialog_content = "Seleucid, send airships to evacuate passengers.",
  ui_story_5071_50711102_33_dialog_content = "Those shadows of the past are after me.",
  ui_story_5071_50711102_34_dialog_content = "You will escort passengers off this ship.",
  ui_story_5071_50711102_35_dialog_content = "Boss...",
  ui_story_5071_50711102_36_dialog_content = "That's an order.",
  ui_story_5071_50711102_37_dialog_content = "I see...",
  ui_story_5071_50711102_38_dialog_content = "This is Bethel, coming in.",
  ui_story_5071_50711102_39_dialog_content = "Father, we spotted suspects on the freight road to Twin Pavilions Bay.",
  ui_story_5071_50711102_40_dialog_content = "They were sending weapons and mercenaries to Umbraton and have been apprehended.",
  ui_story_5071_50711102_41_dialog_content = "How is it going on your end? Did the maiden launch go without a hitch?",
  ui_story_5071_50711102_42_dialog_content = "Everything's fine over here, no worries.",
  ui_story_5071_50711102_43_dialog_content = "Bethel, our favorite naughty \"guests\" will probably show up back home.",
  ui_story_5071_50711102_44_dialog_content = "I trust you'll be a wonderful host and greet them in the most appropriate manner.",
  ui_story_5071_50711102_45_dialog_content = "Copy that. Please take care, Father.",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5071_50711102_47_dialog_content = "This is bad... The airship still hasn't regained its balance.",
  ui_story_5071_50711102_48_dialog_content = "The whole ship is shaking, and we appear to be losing momentum...",
  ui_story_5071_50711102_49_dialog_content = "You're a seasoned Colossus pilot, so please don't scare me like that, dear.",
  ui_story_5071_50711102_50_dialog_content = "This shouldn't be happening if repairs are already complete.",
  ui_story_5071_50711102_51_dialog_content = "If the airship's condition keeps deteriorating, we're going to keep losing altitude... and we'll crash into Umbraton!",
  ui_story_5071_50711102_52_dialog_content = "Lady Sheol! Lady Sheol! Terrible news—",
  ui_story_5071_50711102_53_dialog_content = "We found our engineering team down below. They've all been...",
  ui_story_5071_50711102_54_dialog_content = "What?",
  ui_story_5071_50711201_1_dialog_content = "Oh no, we have to get to the master-control room now.",
  ui_story_5071_50711201_2_dialog_content = "The pilots are still in there!",
  ui_story_5071_50711201_3_dialog_content = "This is—",
  ui_story_5071_50711201_4_dialog_content = "We're too late. The pilots are all... and the control panels are destroyed.",
  ui_story_5071_50711201_5_dialog_content = "This is going way too far...",
  ui_story_5071_50711201_6_dialog_content = "We must think of a way to turn this airship around.",
  ui_story_5071_50711201_7_dialog_content = "One step behind again...",
  ui_story_5071_50711201_8_dialog_content = "...",
  ui_story_5071_50711201_9_dialog_content = "Wait, what's this?",
  ui_story_5071_50711201_10_dialog_content = "You actually made it look like Soroz here?",
  ui_story_5071_50711201_11_dialog_content = "I thought you were only joking at the time...",
  ui_story_5071_50711201_12_dialog_content = "If you come to the ceremony as my special guest of honor...",
  ui_story_5071_50711201_13_dialog_content = "I'll make the control room a duplicate of that of the Colossus!",
  ui_story_5071_50711201_14_dialog_content = "So, are you coming?",
  ui_story_5071_50711201_X11_dialog_content = "It's not hard for me at all.",
  ui_story_5071_50711201_15_dialog_content = "Of course, you're the main gimmick in the promotion, after all.",
  ui_story_5071_50711201_16_dialog_content = "So, maybe I can pilot it?",
  ui_story_5071_50711201_17_dialog_content = "That is true! You're the expert, so do what you will.",
  ui_story_5071_50711201_18_dialog_content = "I just need to start playing, and it should work like usual—",
  ui_story_5071_50711201_19_dialog_content = "Huh—",
  ui_story_5071_50711201_20_dialog_content = "There's no response!",
  ui_story_5071_50711201_21_dialog_content = "These control systems are completely different from the ones on Soroz!",
  ui_story_5071_50711201_X21_dialog_content = "I have no idea how to fix it.",
  ui_story_5071_50711201_X22_dialog_content = "True, the panel isn't of Caelestite origin but an old antique I bought.",
  ui_story_5071_50711201_22_dialog_content = "They're also busted.",
  ui_story_5071_50711201_23_dialog_content = "That's because they're just a gimmick... *sighs* I guess this isn't gonna work.",
  ui_story_5071_50711201_24_dialog_content = "How could this be...",
  ui_story_5071_50711201_25_dialog_content = "Antique, you said?",
  ui_story_5071_50711201_26_dialog_content = "And I've seen this kind of ancient control panel before, everyone!",
  ui_story_5071_50711201_27_dialog_content = "You know how it works? Can you fix it?",
  ui_story_5071_50711201_28_dialog_content = "Give me some time, and I should be able to restore it.",
  ui_story_5071_50711201_29_dialog_content = "Do we still have time?",
  ui_story_5071_50711201_30_dialog_content = "It seems we're falling faster and faster.",
  ui_story_5071_50711201_31_dialog_content = "Wait! If this airship really is a replica of the Colossus, then its structure...",
  ui_story_5071_50711201_32_dialog_content = "I have an idea, everyone!",
  ui_story_5071_50711201_33_dialog_content = "If we can shift the orientation of the wings from outside, we should be able to slow our descent and make an emergency landing.",
  ui_story_5071_50711201_34_dialog_content = "What should we do?",
  ui_story_5071_50711201_35_dialog_content = "Please come with me!",
  ui_story_5071_50711201_36_dialog_content = "Take this, PlayerName!",
  ui_story_5071_50711201_37_dialog_content = "It's an abridged manual to introduce you to the ship's schematics.",
  ui_story_5071_50711201_38_dialog_content = "I'll stay here to protect Vergil and leave the vessel to you.",
  ui_story_5071_50711201_39_dialog_content = "Let's go.",
  ui_story_5071_50711201_40_dialog_content = "Wait, there's one more problem... The wings of the airship are exposed. We'll need a shuttle to get close!",
  ui_story_5071_50711201_41_dialog_content = "Let's check out the upper deck!",
  ui_story_5071_50711201_42_dialog_content = "PlayerName, Shadowlord, please...",
  ui_story_5071_50711201_X42_dialog_content = "What luck, there's still a shuttle left!",
  ui_story_5071_50711201_44_dialog_content = "Seleucid seems to have left one behind.",
  ui_story_5071_50711201_45_dialog_content = "Get up and tell me what to do.",
  ui_story_5071_50711201_46_dialog_content = "Let me take a look at the structural schematics first... There!",
  ui_story_5071_50711201_47_dialog_content = "Both airships and Colossi have wings. While their structures are different, the logic behind them is exactly the same.",
  ui_story_5071_50711201_48_dialog_content = "By adjusting the joint right behind the wing, we can alter the trajectory of the ship and make it turn.",
  ui_story_5071_50711201_49_dialog_content = "Hang on!",
  ui_story_5071_50711201_50_dialog_content = "Ah—",
  ui_story_5071_50711201_51_dialog_content = "Is this the \"wing\" you were talking about?",
  ui_story_5071_50711201_52_dialog_content = "Haha, it sure is bigger than it needs to be.",
  ui_story_5071_50711201_53_dialog_content = "Are you sure you can change its direction?",
  ui_story_5071_50711201_54_dialog_content = "Try to fly us a little closer so I can get a closer look at the mechanism, Shadowlord!",
  ui_story_5071_50711201_55_dialog_content = "This is...",
  ui_story_5071_50711201_56_dialog_content = "Oh no, this mechanism is way cruder than the ones on Colossi!",
  ui_story_5071_50711201_57_dialog_content = "In order to create wings that could be powered by energy, they abandoned the original design. These wings can't be manually adjusted at all...",
  ui_story_5071_50711201_58_dialog_content = "Haha! Carefree and aspiring, now this is the <color=#FFB400>dream</color> every youngster should have!",
  ui_story_5071_50711201_59_dialog_content = "Understandable—",
  ui_story_5071_50711201_60_dialog_content = "The wings carrying a dream will not yield easily!",
  ui_story_5071_50711201_61_dialog_content = "Don't get any closer, or we'll get sucked in—",
  ui_story_5071_50711201_62_dialog_content = "How am I going to change direction without getting close?",
  ui_story_5071_50711201_63_dialog_content = "Shadowlord?",
  ui_story_5071_50711201_64_dialog_content = "You, take over the piloting.",
  ui_story_5071_50711201_65_dialog_content = "Urgh!",
  ui_story_5071_50711201_66_dialog_content = "You're being way too reckless! If you shove your hand into those giant gears, you'll—",
  ui_story_5071_50711201_67_dialog_content = "Tell me which way to turn it, PlayerName!",
  ui_story_5071_50711201_68_dialog_content = "You—",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5071_50711201_70_dialog_content = "(Unbelievable! The Shadowlord is somehow bearing the weight of the entire wing...)",
  ui_story_5071_50711201_71_dialog_content = "Towards your left! Rotate that mechanism and it'll move the rest of the wing!",
  ui_story_5071_50711201_72_dialog_content = "Hyaaaah!",
  ui_story_5071_50711201_73_dialog_content = "Try not—to fall—in such a hurry!",
  ui_story_5071_50711201_74_dialog_content = "Creak—Creak—",
  ui_story_5071_50711201_75_dialog_content = "(It's moving—that gigantic wing is actually moving!)",
  ui_story_5071_50711201_76_dialog_content = "You did it, Shadowlord! We're changing course!",
  ui_story_5071_50711201_77_dialog_content = "Still not enough—",
  ui_story_5071_50711201_78_dialog_content = "Gotta get it away from Umbraton—",
  ui_story_5071_50711201_79_dialog_content = "Get moving!",
  ui_story_5071_50711201_80_dialog_content = "Boom—",
  ui_story_5071_50711201_81_dialog_content = "Oh no! The rear engine exploded!",
  ui_story_5071_50711201_82_dialog_content = "(At this rate, we won't be able to fully change directions before crashing!)",
  ui_story_5071_50711201_83_dialog_content = "Not enough. It will still crash on the edge of Umbraton...",
  ui_story_5071_50711201_84_dialog_content = "Come back, Shadowlord! Any more and you'll—",
  ui_story_5071_50711201_85_dialog_content = "Get up against the wind!",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5071_50711201_87_dialog_content = "F-Fireworks?",
  ui_story_5071_50711201_88_dialog_content = "Who the heck is setting off fireworks on the airship right now...",
  ui_story_5071_50711201_89_dialog_content = "Hey, look at that!",
  ui_story_5071_50711201_90_dialog_content = "The Cloudrover Guild's airship is flying this way!",
  ui_story_5071_50711201_91_dialog_content = "This is one of the celebrations for the maiden flight... I just didn't expect it to be so close to us!",
  ui_story_5071_50711201_92_dialog_content = "What marvelous fireworks! That airship is also really spectacular.",
  ui_story_5071_50711201_93_dialog_content = "Lady Sheol must want us to enjoy the event too!",
  ui_story_5071_50711201_94_dialog_content = "Hey, you idiots! What are you standing around for?",
  ui_story_5071_50711201_95_dialog_content = "Hurry up and get out of here! The airship's about to crash!",
  ui_story_5071_50711201_96_dialog_content = "Why is the Istvan Gang so menacing?",
  ui_story_5071_50711201_97_dialog_content = "Run! I heard the Shadowlord started a bloodbath and wiped out everyone on the airship!",
  ui_story_5071_50711201_98_dialog_content = "They want to crash the Cloudrover Airship in our slums!",
  ui_story_5071_50711201_99_dialog_content = "Follow us! We need to take shelter outside of the town—",
  ui_story_5071_50711201_100_dialog_content = "Stay away from us! We haven't offended you in any way!",
  ui_story_5071_50711201_101_dialog_content = "We're going to start attacking if you get any closer!",
  ui_story_5071_50711201_102_dialog_content = "Why are you so scared of us? Hey, stop throwing rocks!",
  ui_story_5071_50711201_103_dialog_content = "The Istvan Gang is attacking civilians!",
  ui_story_5071_50711201_104_dialog_content = "<size=45>Hey!</size>",
  ui_story_5071_50711201_105_dialog_content = "Calm down, everyone... Attack us one more time and we'll have no choice but to retaliate.",
  ui_story_5071_50711201_106_dialog_content = "Why are these jerks suddenly...",
  ui_story_5071_50711201_107_dialog_content = "It must be the woman who tried to stir the pot on the airship!",
  ui_story_5071_50711201_108_dialog_content = "Stop right there!",
  ui_story_5071_50711201_109_dialog_content = "*sigh* Reckless as ever, huh? This is gonna be a headache to deal with.",
  ui_story_5071_50711201_110_dialog_content = "This is—",
  ui_story_5071_50711201_111_dialog_content = "Is the airship changing directions?",
  ui_story_5071_50711201_112_dialog_content = "It would appear they fixed the control panel.",
  ui_story_5071_50711201_113_dialog_content = "Let's head back.",
  ui_story_5071_50711201_114_dialog_content = "Hang on.",
  ui_story_5071_50711201_115_dialog_content = "This button sets off the fireworks, this one is for broadcasting, and this one is...",
  ui_story_5071_50711201_116_dialog_content = "Vergil! You actually managed to fix the control panel?",
  ui_story_5071_50711201_117_dialog_content = "Not really. The directional controls are working again, but we still can't regain altitude.",
  ui_story_5071_50711201_118_dialog_content = "Oh... That's probably because one of the engines exploded...",
  ui_story_5071_50711201_119_dialog_content = "It will still crash this way...",
  ui_story_5071_50711201_120_dialog_content = "If we aim it right and land on Gold River, maybe the airship can remain intact.",
  ui_story_5071_50711201_121_dialog_content = "Which way should I fly, Lady Sheol? Toward the river?",
  ui_story_5071_50711201_122_dialog_content = "But won't the people on both sides of the river suffer?",
  ui_story_5071_50711201_123_dialog_content = "Let's move it toward the valley. No one lives there.",
  ui_story_5071_50711201_124_dialog_content = "But if I do that, this airship will be reduced to a pile of scrap.",
  ui_story_5071_50711201_125_dialog_content = "It's all my fault that your airship...",
  ui_story_5071_50711201_126_dialog_content = "What are you saying, Shadowlord? You make it sound like you're the mastermind behind all this.",
  ui_story_5071_50711201_127_dialog_content = "...",
  ui_story_5071_50711201_128_dialog_content = "Explain to me how to fly it and you guys can leave.",
  ui_story_5071_50711201_129_dialog_content = "Lady Sheol?",
  ui_story_5071_50711201_130_dialog_content = "Someone has to fly this thing, right? Not to mention it's mine.",
  ui_story_5071_50711201_131_dialog_content = "So you guys should—",
  ui_story_5071_50711201_132_dialog_content = "Leave and let me fly it.",
  ui_story_5071_50711201_133_dialog_content = "Shadowlord?",
  ui_story_5071_50711201_134_dialog_content = "What are you doing—",
  ui_story_5071_50711201_135_dialog_content = "Stop trying to do other people's jobs, Lady Sheol.",
  ui_story_5071_50711201_136_dialog_content = "Not to mention I've got experience with this already.",
  ui_story_5071_50711201_137_dialog_content = "Leave. Those who yearned to fly should not have their dreams shattered in the sky.",
  ui_story_5071_50711201_138_dialog_content = "Shadowlord...",
  ui_story_5071_50711201_139_dialog_content = "Take the two kids and return to safety.",
  ui_story_5071_50711201_140_dialog_content = "... Do you still remember the favor you owe me?",
  ui_story_5071_50711201_141_dialog_content = "I don't forget my promises.",
  ui_story_5071_50711201_142_dialog_content = "Good. I will keep them safe.",
  ui_story_5071_50711201_143_dialog_content = "In exchange, I hope you keep your promise and fulfill my request.",
  ui_story_5071_50711201_144_dialog_content = "My wish is to stay alive, simple as that.",
  ui_story_5071_50711201_145_dialog_content = "... I promise.",
  ui_story_5071_50711201_146_dialog_content = "Let's not waste any more time. Go!",
  ui_story_5071_50711201_147_dialog_content = "May the Shadow watch over you.",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>Valon</color>, old friend... Let's put more into this dream...",
  ui_story_5071_50711202_1_dialog_content = "You're finally back, Mr. Borriman.",
  ui_story_5071_50711202_2_dialog_content = "I don't think an introduction is in order.",
  ui_story_5071_50711202_3_dialog_content = "L-Lady Bethel? Ah, why have you suddenly come?",
  ui_story_5071_50711202_4_dialog_content = "You didn't even notify us—",
  ui_story_5071_50711202_5_dialog_content = "I caught a band of armed mercenaries outside the town. They were trying to invade Umbraton.",
  ui_story_5071_50711202_6_dialog_content = "Judging from their vehicles, support personnel, and this testimony...",
  ui_story_5071_50711202_7_dialog_content = "We suspect your Red Panther Guild, the Gray Parrot Guild, and the Rust Falcon Gang...",
  ui_story_5071_50711202_8_dialog_content = "...are among the minimum three accomplices in this incident.",
  ui_story_5071_50711202_9_dialog_content = "Here's the photo proof of you trafficking weapons illegally.",
  ui_story_5071_50711202_10_dialog_content = "I'd like you to come with us under the Umbraton Security Regulation.",
  ui_story_5071_50711202_11_dialog_content = "W-Wait a second. There must have been some kind of misunderstanding.",
  ui_story_5071_50711202_12_dialog_content = "You can't take me away like this!",
  ui_story_5071_50711202_13_dialog_content = "Just one more hour. No! Maybe even another half an hour or so...",
  ui_story_5071_50711202_14_dialog_content = "What do you mean by that?",
  ui_story_5071_50711202_15_dialog_content = "It's as if you have something planned...",
  ui_story_5071_50711202_16_dialog_content = "<size=45>Ah!</size>",
  ui_story_5071_50711202_17_dialog_content = "What's going on out there?",
  ui_story_5071_50711202_18_dialog_content = "Why is there chaos everywhere?",
  ui_story_5071_50711202_19_dialog_content = "Take him into custody.",
  ui_story_5071_50711202_20_dialog_content = "Yes, ma'am!",
  ui_story_5071_50711202_21_dialog_content = "Bethel to the guild. What is going on?",
  ui_story_5071_50711202_22_dialog_content = "Lady Bethel, you're back!",
  ui_story_5071_50711202_23_dialog_content = "The Shadowlord is...",
  ui_story_5071_50711202_24_dialog_content = "Calm down. What happened to my father? Tell me!",
  ui_story_5071_50711202_25_dialog_content = "The airship that Lady Sheol and he are on is about to crash!",
  ui_story_5071_50711202_26_dialog_content = "What?",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5071_50711202_28_dialog_content = "Is that... the sound of the airship crashing?",
  ui_story_5071_50711202_29_dialog_content = "Lady Bethel, what should we do?",
  ui_story_5071_50711202_30_dialog_content = "The thing that fell from the airship seemed to have landed in the town.",
  ui_story_5071_50711202_31_dialog_content = "Someone is hiding amongst the people in the town and inciting a riot. Meanwhile, many mercenaries outside the town are...",
  ui_story_5071_50711202_32_dialog_content = "Seleucid would like us to assist the Shadowlord, but without your approval—",
  ui_story_5071_50711202_33_dialog_content = "Father...",
  ui_story_5071_50711202_34_dialog_content = "I see.",
  ui_story_5071_50711202_35_dialog_content = "He sent me away because he sensed imminent peril.",
  ui_story_5071_50711202_36_dialog_content = "Lady Bethel?",
  ui_story_5071_50711202_37_dialog_content = "Calm down, I think nothing will happen to the Shadowlord.",
  ui_story_5071_50711202_38_dialog_content = "Also, give my order to everyone in the guild.",
  ui_story_5071_50711202_39_dialog_content = "Yes, ma'am!",
  ui_story_5071_50711202_40_dialog_content = "Someone's setting their sights on Umbraton. We cannot panic and give them an opening.",
  ui_story_5071_50711202_41_dialog_content = "I'll turn the list and proof over to the Guardians. Send Kleken to their HQ—",
  ui_story_5071_50711202_42_dialog_content = "Tell him to assist the Guardians in apprehending the culprits, and be alert since they will take the opportunity to escape or resist.",
  ui_story_5071_50711202_43_dialog_content = "Yes, ma'am!",
  ui_story_5071_50711202_44_dialog_content = "Tell Seleucid to assemble the Guardians' combat units and send half to defend the outskirts.",
  ui_story_5071_50711202_45_dialog_content = "Summon Patty and Patsy. Send them to help me with the chaos in the town.",
  ui_story_5071_50711202_46_dialog_content = "Also, dispatch the main reinforcement to assist the residents. Then send two units to search for the Shadowlord!",
  ui_story_5071_50711202_47_dialog_content = "Before he returns, we must maintain order and defend this place on his behalf, understand?",
  ui_story_5071_50711202_48_dialog_content = "Yes, Lady Bethel!",
  ui_story_5071_50711202_49_dialog_content = "I believe in you, father, to be your usual self...",
  ui_story_5071_50711202_50_dialog_content = "And make another <color=#FFB400>golden comeback</color>!",
  ui_story_5071_50711301_1_dialog_content = "Such a beautiful airship... gone just like that...",
  ui_story_5071_50711301_2_dialog_content = "The Shadowlord made it! It crash-landed in an empty part of the wilderness—",
  ui_story_5071_50711301_3_dialog_content = "Get closer before you land, darling.",
  ui_story_5071_50711301_4_dialog_content = "We were just in the air, but now...",
  ui_story_5071_50711301_5_dialog_content = "The dreams of people in Umbraton never last. Nothing you can do about that.",
  ui_story_5071_50711301_6_dialog_content = "The fire is so vicious... There's nothing left except scorched remains...",
  ui_story_5071_50711301_7_dialog_content = "Nothing is spared, not even the precious works of art... Wh-What will we do now, Lady Sheol?",
  ui_story_5071_50711301_8_dialog_content = "I don't care for my personal collection as much as the auction items from clients, some of which can't even be reproduced... I'll have to pay for them out of my pocket.",
  ui_story_5071_50711301_9_dialog_content = "Lady Sheol...",
  ui_story_5071_50711301_10_dialog_content = "I'm fine, darling. You win some, and you lose some in business.",
  ui_story_5071_50711301_11_dialog_content = "And I'm not totally in the red yet. Let's go look for the Shadowlord.",
  ui_story_5071_50711301_12_dialog_content = "I-It's so hot... Could the Shadowlord really have survived something like this?",
  ui_story_5071_50711301_13_dialog_content = "Lurking in places unseen is what the Shadow does best. He must be alive.",
  ui_story_5071_50711301_14_dialog_content = "Watch out, Lady Sheol! The flames are too strong over there!",
  ui_story_5071_50711301_15_dialog_content = "(Still nothing... I can't sense the Shadowlord's presence anywhere.)",
  ui_story_5071_50711301_16_dialog_content = "Shadowlord? Shadowlord?",
  ui_story_5071_50711301_17_dialog_content = "Are you hard of hearing due to old age? Stop playing games.",
  ui_story_5071_50711301_18_dialog_content = "(What's gonna happen to Umbraton? And Bethel... What am I supposed to tell her...)",
  ui_story_5071_50711301_19_dialog_content = "This isn't gonna work, Lady Sheol! Please come out before it all burns down...",
  ui_story_5071_50711301_20_dialog_content = "He still has debts to settle with me. His credit is too good to bail!",
  ui_story_5071_50711301_21_dialog_content = "But Lady Sheol...",
  ui_story_5071_50711301_22_dialog_content = "I don't understand... Is the Shadowlord a good person, or a bad one?",
  ui_story_5071_50711301_23_dialog_content = "Vergil...",
  ui_story_5071_50711301_24_dialog_content = "It's never just black or white for grownups.",
  ui_story_5071_50711301_25_dialog_content = "But he risked himself to save us—that's an indisputable fact.",
  ui_story_5071_50711301_26_dialog_content = "But the blaze... We've got to get someone to put out the fire.",
  ui_story_5071_50711301_27_dialog_content = "Should we tell Bethel?",
  ui_story_5071_50711301_28_dialog_content = "*sigh* Bethel must be told of this.",
  ui_story_5071_50711301_29_dialog_content = "Especially when I smelled conspiracy all over it.",
  ui_story_5071_50711301_30_dialog_content = "Ms. Yvonne likely died of poison, and Lumo Guards attacked us on the ship...",
  ui_story_5071_50711301_31_dialog_content = "The mastermind wasn't targeting me but Umbraton—or more specifically, the Shadowlord.",
  ui_story_5071_50711301_32_dialog_content = "The Shadowlord mentioned \"Shadows of the past.\" Maybe he figured out who's behind it?",
  ui_story_5071_50711301_33_dialog_content = "Shadow of the past? Then I believe Ms. Hanstie has something to say about that.",
  ui_story_5071_50711301_34_dialog_content = "Wait, someone's coming!",
  ui_story_5071_50711301_35_dialog_content = "Hoot—Hoot—",
  ui_story_5071_50711301_36_dialog_content = "Is that... an owl?",
  ui_story_5071_50711301_37_dialog_content = "Good, you found them. Come back to me now.",
  ui_story_5071_50711301_38_dialog_content = "Hoot—Hoot—",
  ui_story_5071_50711301_39_dialog_content = "Are you... Ms. Hanstie?",
  ui_story_5071_50711301_40_dialog_content = "(That owl... Something seems really familiar about it...)",
  ui_story_5071_50711301_41_dialog_content = "Can't believe this is the place... There was an impressive Pit here ages ago.",
  ui_story_5071_50711301_42_dialog_content = "It's also the place where that traitor killed his brother.",
  ui_story_5071_50711301_43_dialog_content = "!",
  ui_story_5071_50711301_44_dialog_content = "Could this be fate? I'm at your side once more, Valon.",
  ui_story_5071_50711301_45_dialog_content = "And that traitor managed to crash-land in this place too!",
  ui_story_5071_50711301_46_dialog_content = "It appears even Umbraton won't save him from this final retribution he deserves!",
  ui_story_5071_50711301_47_dialog_content = "I won't have to dirty my hands any longer...",
  ui_story_5071_50711301_48_dialog_content = "Heh... Heheheh.",
  ui_story_5071_50711301_49_dialog_content = "I knew it. You're the Shadowlord's \"shadow of the past,\" aren't you, Ms. Hanstie?",
  ui_story_5071_50711301_50_dialog_content = "What in the world happened back then? This place...",
  ui_story_5071_50711301_51_dialog_content = "Was that writer's account not clear enough for you?",
  ui_story_5071_50711301_52_dialog_content = "\"In cold blood, the traitor known as Kade murdered Valon, his dearest brother. In doing so, he robbed him of all that he was, and betrayed Umbraton.\"",
  ui_story_5071_50711301_53_dialog_content = "As part of the past he sought to eradicate, I've been forced to live outside of the town all these years.",
  ui_story_5071_50711301_54_dialog_content = "I suffered unspeakable humiliation as I clawed my way to the top of the business world, all so that I could return to my hometown one day—",
  ui_story_5071_50711301_55_dialog_content = "And tear off that traitor's mask with my own two hands!",
  ui_story_5071_50711301_56_dialog_content = "He isn't worthy of Valon's surname! He doesn't deserve to call himself \"Istvan\"!",
  ui_story_5071_50711301_57_dialog_content = "Sorry to interrupt—",
  ui_story_5071_50711301_58_dialog_content = "Things were so crazy before that I didn't have a chance to speak...",
  ui_story_5071_50711301_59_dialog_content = "I've been wondering about something all this time. Did Ms. Yvonne really write those manuscripts we saw with her own hand?",
  ui_story_5071_50711301_60_dialog_content = "What are you saying, Vergil?",
  ui_story_5071_50711301_61_dialog_content = "Ms. Yvonne was very passionate about writing, and her penmanship reflects that. Her handwriting is usually very free-spirited, and every word is written with very little concern for aesthetics.",
  ui_story_5071_50711301_62_dialog_content = "But those last few manuscripts were written meticulously, and the ink was much darker. Not only that, the form and intent behind the words were completely different.",
  ui_story_5071_50711301_63_dialog_content = "There was... a certain level of craftsmanship to them.",
  ui_story_5071_50711301_64_dialog_content = "There was also a faint aroma lingering on the pages of those manuscripts.",
  ui_story_5071_50711301_65_dialog_content = "... Those clues tell me they were the work of \"A,\" the master counterfeiter.",
  ui_story_5071_50711301_66_dialog_content = "An aroma...",
  ui_story_5071_50711301_67_dialog_content = "It smells like <color=#FFB400>lilies</color>!",
  ui_story_5071_50711301_68_dialog_content = "\"I love how you portray her: mysterious, strong, uninhibited.\"",
  ui_story_5071_50711301_69_dialog_content = "\"My admiration of her silent keeper role is the reason I love lilies so much.\"",
  ui_story_5071_50711301_70_dialog_content = "\"Eternal memories, insurmountable love, and profound blessings. That is what lilies symbolize.\"",
  ui_story_5071_50711301_71_dialog_content = "Ms. Hanstie...",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>Ms. Hanstie smiles slightly, neither denying nor acknowledging anything.</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>The truth lies soaked in the ink. At this point, does it matter if Yvonne or Hanstie wrote it?</color>",
  ui_story_5071_50711301_74_dialog_content = "We all wear different masks. Whether or not I'm \"A\" has no effect on the outcome.",
  ui_story_5071_50711301_75_dialog_content = "*sniffling* But why would you do this? I... I've always admired you...",
  ui_story_5071_50711301_76_dialog_content = "Well, Ms. Yvonne did mention she got the inspiration from an \"artist friend.\"",
  ui_story_5071_50711301_77_dialog_content = "I see that friend is you.",
  ui_story_5071_50711301_78_dialog_content = "You really are the hands-on type, doing it all for an old grudge.",
  ui_story_5071_50711301_79_dialog_content = "As the collateral damage in your scheme, I'd like to know if you would compensate me for the airship and my huge losses.",
  ui_story_5071_50711301_80_dialog_content = "If your stolen dream dies here, I have no qualms about it.",
  ui_story_5071_50711301_81_dialog_content = "Oh, my darling Ms. Hanstie, that was actually my dream.",
  ui_story_5071_50711301_82_dialog_content = "It's nothing like the tall tales you made up—",
  ui_story_5071_50711301_83_dialog_content = "You have been taking liberty starting with how my mother died, haven't you?",
  ui_story_5071_50711301_84_dialog_content = "Perhaps it's true—",
  ui_story_5071_50711301_85_dialog_content = "Or perhaps it's nothing but hearsay.",
  ui_story_5071_50711301_86_dialog_content = "Either way, such rumors wouldn't have been spread in the first place if there hadn't been any proof.",
  ui_story_5071_50711301_87_dialog_content = "I have absolutely no interest in the truth about Lady Melissa. I'm satisfied so long as I can continue to use the rumors about her.",
  ui_story_5071_50711301_88_dialog_content = "Yes, you should all be able to see Kade's true face now.",
  ui_story_5071_50711301_89_dialog_content = "No—",
  ui_story_5071_50711301_90_dialog_content = "This... This doesn't make sense!",
  ui_story_5071_50711301_91_dialog_content = "And what would you know, child?",
  ui_story_5071_50711301_92_dialog_content = "You constantly talk about showing people the truth about the past. Why should Lady Mercury's past be any different?",
  ui_story_5071_50711301_93_dialog_content = "You know how important it is for Lady Sheol to learn about her mother...",
  ui_story_5071_50711301_94_dialog_content = "But you're just using that knowledge as a bargaining chip to hurt other people—",
  ui_story_5071_50711301_95_dialog_content = "How could you be so selfish!",
  ui_story_5071_50711301_96_dialog_content = "PlayerName...",
  ui_story_5071_50711301_97_dialog_content = "Enough!",
  ui_story_5071_50711301_98_dialog_content = "You earn your living by making counterfeit goods, but you just can't resist leaving your own mark on them.",
  ui_story_5071_50711301_99_dialog_content = "To get your revenge, you resort to the cruelest, most despicable means—",
  ui_story_5071_50711301_100_dialog_content = "You may want to expose the Shadowlord's past, but there isn't a shred of truth behind your actions.",
  ui_story_5071_50711301_101_dialog_content = "Someone as selfish and arrogant as you would only target the Shadowlord to serve their own interests...",
  ui_story_5071_50711301_102_dialog_content = "I said enough, you worthless brat!",
  ui_story_5071_50711301_103_dialog_content = "Come on now, that's beneath you, Ms. Hanstie.",
  ui_story_5071_50711301_104_dialog_content = "See, you scared even Vergil.",
  ui_story_5071_50711301_105_dialog_content = "Ms. Yvonne was poisoned to death.",
  ui_story_5071_50711301_106_dialog_content = "I've seen a similar kind of poison before...",
  ui_story_5071_50711301_107_dialog_content = "I've grown tired of listening to your words.",
  ui_story_5071_50711301_108_dialog_content = "It seems there is no dissuading you stubborn fools from this erroneous path.",
  ui_story_5071_50711301_109_dialog_content = "I have no choice but to bury a few more of Kade's underlings in Valon's resting place.",
  ui_story_5071_50711301_110_dialog_content = "Come out, men!",
  ui_story_5071_50711301_111_dialog_content = "Getting serious now, I see.",
  ui_story_5071_50711301_112_dialog_content = "We've been surrounded...",
  ui_story_5071_50711301_113_dialog_content = "I think it's time for you to do what you do best, darling.",
  ui_story_5071_50711301_114_dialog_content = "I've only seen you navigate others before. Let me experience it in person today!",
  ui_story_5071_50711301_115_dialog_content = "Get Vergil and stand behind me!",
  ui_story_5071_50711301_116_dialog_content = "I can't afford to lose my best client and employee.",
  ui_story_5071_50711302_1_dialog_content = "They're getting more reinforcement. That's not good.",
  ui_story_5071_50711302_2_dialog_content = "We're not going to last even with you around, darling.",
  ui_story_5071_50711302_3_dialog_content = "Bethel and the others must've noticed a commotion this big. I'm sure they're already on their way...",
  ui_story_5071_50711302_4_dialog_content = "I'm afraid we can't hold out until then.",
  ui_story_5071_50711302_5_dialog_content = "I'm a businesswoman, not a fighter, but we're out of options...",
  ui_story_5071_50711302_6_dialog_content = "PlayerName, Vergil, you two go find the Shadowlord. I'll handle them.",
  ui_story_5071_50711302_7_dialog_content = "But—",
  ui_story_5071_50711302_8_dialog_content = "Have faith in him! I've never seen anyone beholden to their promises more than him in all my years in business.",
  ui_story_5071_50711302_9_dialog_content = "Please believe in him and yourself, PlayerName.",
  ui_story_5071_50711302_10_dialog_content = "Only you can find him in this chaos. Don't give up!",
  ui_story_5071_50711302_11_dialog_content = "... I understand.",
  ui_story_5071_50711302_12_dialog_content = "Let's go, Vergil.",
  ui_story_5071_50711302_13_dialog_content = "Leaving so soon?",
  ui_story_5071_50711302_14_dialog_content = "What's the hurry, Ms. Hanstie? We still have unfinished business.",
  ui_story_5071_50711302_15_dialog_content = "It's low to fib about someone's mother, you know.",
  ui_story_5071_50711302_16_dialog_content = "As expected of Mrs. Red Mercury's daughter, your temperament is no different than hers.",
  ui_story_5071_50711302_17_dialog_content = "Though I admired her greatly, I've never once cared for you in my life.",
  ui_story_5071_50711302_18_dialog_content = "So what did I do wrong, and should I apologize?",
  ui_story_5071_50711302_19_dialog_content = "You really are an impudent fool.",
  ui_story_5071_50711302_20_dialog_content = "You may know a bit of business now, but your sight is as poor as ever.",
  ui_story_5071_50711302_21_dialog_content = "Ever since the last time, you've done nothing but get in my way.",
  ui_story_5071_50711302_22_dialog_content = "Last time? Now I have to ask when that was.",
  ui_story_5071_50711302_23_dialog_content = "... Those were trivial slights, but your greatest sin was thinking you could shamelessly steal another person's dream.",
  ui_story_5071_50711302_24_dialog_content = "I'm the only person who can carry on Valon's dream!",
  ui_story_5071_50711302_25_dialog_content = "You are not worthy!",
  ui_story_5071_50711302_26_dialog_content = "PlayerName is right. You're already a guild leader, yet still more egotistical than a child.",
  ui_story_5071_50711302_27_dialog_content = "You and Kade truly are no different from one another—I won't hold back against you no matter how much you look like your mother.",
  ui_story_5071_50711302_28_dialog_content = "I will destroy you, along with Kade and your precious Cloudrover Guild—",
  ui_story_5071_50711302_29_dialog_content = "I'll bring you all crashing into the <color=#FFB400>ground</color>!",
  ui_story_5071_50711302_30_dialog_content = "Alright... Since you've already ripped into me, what more harm could I do to my image?",
  ui_story_5071_50711302_31_dialog_content = "(Shadowlord... Are you really alive out there? If so, where are you?)",
  ui_story_5071_50711302_32_dialog_content = "(Or was Lady Sheol just trying to buy us time to escape?)",
  ui_story_5071_50711302_33_dialog_content = "(Please let me hear your voice... or else—)",
  ui_story_5071_50711302_34_dialog_content = "*coughing* Th-The smoke—it's getting too thick—",
  ui_story_5071_50711302_35_dialog_content = "Sorry, Vergil... But I have to keep looking for the Shadowlord. You should go back to Umbraton and call for backup instead.",
  ui_story_5071_50711302_36_dialog_content = "I can't do that. Lady Sheol asked both of us to look for him.",
  ui_story_5071_50711302_37_dialog_content = "She said the Shadowlord always keeps his promises, so I'd believe in him too!",
  ui_story_5071_50711302_38_dialog_content = "Vergil... Huh?",
  ui_story_5071_50711302_39_dialog_content = "(I sense a mix of powerful, chaotic emotions, and it's coming from deep inside the flames!)",
  ui_story_5071_50711302_40_dialog_content = "Vergil, we need to get through these flames—",
  ui_story_5071_50711302_41_dialog_content = "Ouch—W-Wait for me!",
  ui_story_5071_50711302_42_dialog_content = "(Shadowlord... If you're really out there, please say something—)",
  ui_story_5071_50711302_43_dialog_content = "Shadowlord... Shadowlord!",
  ui_story_5071_50711302_44_dialog_content = "Shadowlord—",
  ui_story_5071_50711302_45_dialog_content = "PlayerName?",
  ui_story_5071_50711302_46_dialog_content = "It's really you! Thank goodness you're... Huh?",
  ui_story_5071_50711302_47_dialog_content = "Look out behind you!",
  ui_story_5071_50711302_48_dialog_content = "No—",
  ui_story_5071_50711302_49_dialog_content = "Don't worry, they're out.",
  ui_story_5071_50711302_50_dialog_content = "Those guys were really persistent. Were they hiding here all along?",
  ui_story_5071_50711302_51_dialog_content = "Can't believe they even found you before us.",
  ui_story_5071_50711302_52_dialog_content = "Ms. Hanstie's desire to eradicate everything is terrifying. She's going all-out against us.",
  ui_story_5071_50711302_53_dialog_content = "Let her do her thing...",
  ui_story_5071_50711302_54_dialog_content = "Shadowlord?",
  ui_story_5071_50711302_55_dialog_content = "I'm feeling... a bit tired—",
  ui_story_5071_50711302_56_dialog_content = "You look like you're in a lot of pain. Are you hurt?",
  ui_story_5071_50711302_57_dialog_content = "*coughs*",
  ui_story_5071_50711302_58_dialog_content = "Come with us! The smoke is getting too dense over here!",
  ui_story_5071_50711302_59_dialog_content = "It's not smoke.",
  ui_story_5071_50711302_60_dialog_content = "Not smoke? Then what are these black vapors?",
  ui_story_5071_50711302_61_dialog_content = "(Wait, this black mist... Is it the same as <color=#FFB400>Arte's poison</color> from before?)",
  ui_story_5071_50711302_62_dialog_content = "Heheh, so you've finally figured it out?",
  ui_story_5071_50711302_63_dialog_content = "I left you alive so I could eventually hear you confess—",
  ui_story_5071_50711302_64_dialog_content = "So skip the small talk.",
  ui_story_5071_50711302_65_dialog_content = "This is just... Ms. Hanstie's way of knocking on the door.",
  ui_story_5071_50711302_66_dialog_content = "The vapors have been lingering ever since we started fighting each other.",
  ui_story_5071_50711302_67_dialog_content = "The harder you fought, the more of it you inhaled.",
  ui_story_5071_50711302_68_dialog_content = "Even though most of it was burned away by the fire, there's no telling how much you've breathed in already—",
  ui_story_5071_50711302_69_dialog_content = "Hand over the antidote!",
  ui_story_5071_50711302_70_dialog_content = "I thought the Black Wolves were wiped out? How are you guys still producing this poison?",
  ui_story_5071_50711302_71_dialog_content = "\"Poison\"? Hahaha—I think you're mistaken, pal.",
  ui_story_5071_50711302_72_dialog_content = "Besides, the Black Wolves were just a bunch of worthless runts.",
  ui_story_5071_50711302_73_dialog_content = "What's your connection to the Black Wolves? And Arte and Hanstie...",
  ui_story_5071_50711302_74_dialog_content = "Never mind, just give us the antidote—",
  ui_story_5071_50711302_75_dialog_content = "Worry not, PlayerName... They inhaled the mist too.",
  ui_story_5071_50711302_76_dialog_content = "If it was toxic, they would die quicker given how weak they are.",
  ui_story_5071_50711302_77_dialog_content = "Heh, as expected of the famous Shadowlord. Even in this condition, you're still perfectly calm.",
  ui_story_5071_50711302_78_dialog_content = "I think you're about to reach the soliloquy part where you reveal the plot.",
  ui_story_5071_50711302_79_dialog_content = "Don't let your chance to be heard slip by, clumsy clown.",
  ui_story_5071_50711302_80_dialog_content = "Humph—We were only following Ms. Hanstie's orders, but this is exactly what we all want.",
  ui_story_5071_50711302_81_dialog_content = "You can feel it now, can't you? A sense of restlessness coming from deep inside—a sense of violence.",
  ui_story_5071_50711302_82_dialog_content = "That's the effect of our modified black mist. It doesn't kill you anymore—it just fills you with rage and makes you heed your most savage urges.",
  ui_story_5071_50711302_83_dialog_content = "In that condition, no one can possibly suppress their deepest desires.",
  ui_story_5071_50711302_84_dialog_content = "Don't tell me you guys—",
  ui_story_5071_50711302_85_dialog_content = "That's right! Our goal is to use it to unleash the beast hiding beneath Istvan's mask!",
  ui_story_5071_50711302_86_dialog_content = "<size=50>The demon of the Pit—Kade!</size>",
  ui_story_5071_50711302_87_dialog_content = "We're going to bring out the monster buried deep in your heart!",
  ui_story_5071_50711302_88_dialog_content = "All of those people who come to your rescue will know exactly what you are!",
  ui_story_5071_50711302_89_dialog_content = "Now show them! Show the people you claim to love the hideous madness of your soul!",
  ui_story_5071_50711302_90_dialog_content = "You people... You're the only madmen around here!",
  ui_story_5071_50711302_91_dialog_content = "Hand over the antidote—never mind, I'll just take it from you myself...",
  ui_story_5071_50711302_92_dialog_content = "With my power, I'll have no problem finding the antidote on your person—",
  ui_story_5071_50711302_93_dialog_content = "Huh?",
  ui_story_5071_50711302_94_dialog_content = "(His presence... It disappeared completely!)",
  ui_story_5071_50711302_95_dialog_content = "Hey! Wake up! You—",
  ui_story_5071_50711302_96_dialog_content = "...",
  ui_story_5071_50711302_97_dialog_content = "You can stop now, PlayerName.",
  ui_story_5071_50711302_98_dialog_content = "He ended his life.",
  ui_story_5071_50711302_99_dialog_content = "They didn't carry antidote with them because they were ready to die.",
  ui_story_5071_50711302_100_dialog_content = "There are still others! We need to stop them from...",
  ui_story_5071_50711302_101_dialog_content = "(What's happening? Even though we're surrounded by a raging inferno... the flames of life are going out, one by one...)",
  ui_story_5071_50711302_102_dialog_content = "Stop! Don't do this anymore, or you'll all—",
  ui_story_5071_50711302_103_dialog_content = "Waaah—",
  ui_story_5071_50711302_104_dialog_content = "PlayerName, I'm very happy that—",
  ui_story_5071_50711302_105_dialog_content = "A youngster like you would mourn the enemy.",
  ui_story_5071_50711302_106_dialog_content = "But I'm also sorry to say most of the people here are probably...",
  ui_story_5071_50711302_107_dialog_content = "How... How could they do this to themselves without hesitation? And in such a horrible way—",
  ui_story_5071_50711302_108_dialog_content = "I believe you already knew the answer.",
  ui_story_5071_50711302_109_dialog_content = "This is...",
  ui_story_5071_50711302_110_dialog_content = "The Gambi family crest... from back then...",
  ui_story_5071_50711302_111_dialog_content = "A family that I destroyed—",
  ui_story_5071_50711302_112_dialog_content = "They're all carrying something similar.",
  ui_story_5071_50711302_113_dialog_content = "This one is Colo, that's Luka, and that one belongs to the Bonas...",
  ui_story_5071_50711302_114_dialog_content = "I see the leaders who drowned in the Pit all left their shadows behind—",
  ui_story_5071_50711302_115_dialog_content = "This is where the shadows of the past finally reach.",
  ui_story_5071_50711302_116_dialog_content = "Urgh... There's a burning sensation in my chest...",
  ui_story_5071_50711302_117_dialog_content = "An impulse driving me to burn down... to destroy everything...",
  ui_story_5071_50711302_118_dialog_content = "Your face...",
  ui_story_5071_50711302_119_dialog_content = "I imagine I don't seem pleasant. So, do I look barbaric?",
  ui_story_5071_50711302_120_dialog_content = "(What a terrifying expression... Even his veins are completely visible. He looks nothing like the Shadowlord from before...)",
  ui_story_5071_50711302_121_dialog_content = "We should go, Shadowlord—",
  ui_story_5071_50711302_122_dialog_content = "If we can't find the antidote here, I'm sure we can find something in Umbraton...",
  ui_story_5071_50711302_123_dialog_content = "Either way, we need to get away from these flames!",
  ui_story_5071_50711302_124_dialog_content = "You're right, but... Urgh—",
  ui_story_5071_50711302_125_dialog_content = "Just lean on me! I'll get us out of here!",
  ui_story_5071_50711302_126_dialog_content = "The fire in me is burning hotter than the blaze here.",
  ui_story_5071_50711302_127_dialog_content = "I... don't think I can hold on much longer.",
  ui_story_5071_50711302_128_dialog_content = "This is destined. My past is catching up to me—",
  ui_story_5071_50711302_129_dialog_content = "Leave me and get out of here. I can't let you get hurt...",
  ui_story_5071_50711302_130_dialog_content = "Stop saying something like that!",
  ui_story_5071_50711302_131_dialog_content = "That's right! We still need you to rescue Lady Sheol!",
  ui_story_5071_50711302_132_dialog_content = "I would like to keep my promise too, but... Urgh—",
  ui_story_5071_50711302_133_dialog_content = "They're right. I feel like I want to destroy something...",
  ui_story_5071_50711302_134_dialog_content = "Quickly! I'm not kidding about this. I...",
  ui_story_5071_50711302_135_dialog_content = "No way, I'm not leaving you behind! I'm sure there's another way—",
  ui_story_5071_50711302_136_dialog_content = "I said, get out of here! Now!",
  ui_story_5071_50711302_137_dialog_content = "Leave me alone!",
  ui_story_5071_50711302_138_dialog_content = "This is it... I know myself better than you do.",
  ui_story_5071_50711302_139_dialog_content = "No...",
  ui_story_5071_50711302_140_dialog_content = "There's gotta be another way.",
  ui_story_5071_50711302_141_dialog_content = "(There has to be! Even if—)",
  ui_story_5071_50711302_142_dialog_content = "I'm sorry. I know you'll probably blame me for this later, but I don't have any other choice now.",
  ui_story_5071_50711302_143_dialog_content = "PlayerName...",
  ui_story_5071_50711302_144_dialog_content = "Keep an eye on us, Vergil! We're counting on you!",
  ui_story_5071_50711302_145_option_content = "Force Boost!",
  ui_story_5071_50711401_1_dialog_content = "So this is the Shadowlord's inner world? There are so many conflicting emotions here...",
  ui_story_5071_50711401_2_dialog_content = "I remember here, this is—",
  ui_story_5071_50711401_3_dialog_content = "Was that the Shadowlord's voice?",
  ui_story_5071_50711401_4_dialog_content = "When the Darkover Crisis came, I represented father and the interim association of guilds to negotiate for reinforcement from Lumopolis. Then...",
  ui_story_5071_50711401_5_dialog_content = "Where are you, Shadowlord?",
  ui_story_5071_50711401_6_dialog_content = "I never imagined I would see that day again.",
  ui_story_5071_50711401_7_dialog_content = "He can't hear me... If I can't reach him like this, then I have no choice but to find a break in his emotions.",
  ui_story_5071_50711401_8_dialog_content = "But where did he go...",
  ui_story_5071_50711401_9_dialog_content = "This place... Is it some kind of arena?",
  ui_story_5071_50711401_10_dialog_content = "... Why are so many people gathered here?",
  ui_story_5071_50711401_11_dialog_content = "I got a big fright too... Can you remember the last time so many bosses gathered together?",
  ui_story_5071_50711401_12_dialog_content = "Are... Are all of these people gang members?",
  ui_story_5071_50711401_13_dialog_content = "Since everyone is willing to come and talk individually, I want to hear what everyone has to say.",
  ui_story_5071_50711401_14_dialog_content = "I heard that old Istvan and several guilds have colluded to betray Umbraton, and <color=#FFB400>his adopted son will pass by with that staff as proof</color>.",
  ui_story_5071_50711401_15_dialog_content = "I want to get that staff and order the association of guilds to distribute supplies and arm everyone to fight the Eclipsites.",
  ui_story_5071_50711401_16_dialog_content = "So they are the ones who called over all those nobles from Lumopolis? Those guys are fully armed and stationed outside in such an emergency. I think they want to keep us here.",
  ui_story_5071_50711401_17_dialog_content = "Those guys from Lumopolis have always been looking for a chance to occupy Umbraton. Let's just give them what they want and leave this place.",
  ui_story_5071_50711401_18_dialog_content = "But this is our home!",
  ui_story_5071_50711401_19_dialog_content = "Don't say that. I don't think of these stinky sewers as my home.",
  ui_story_5071_50711401_20_dialog_content = "Do you want to fight me in the Pit?",
  ui_story_5071_50711401_21_dialog_content = "I don't agree with those guys from Lumopolis waltzing into our territory like this! Didn't they already abandon Umbraton and go home because they were scared of the Eclipsite army? Why have they returned?",
  ui_story_5071_50711401_22_dialog_content = "We already saw them off once, and now they want to garrison their forces here? Is that fair?",
  ui_story_5071_50711401_23_dialog_content = "Let's stop arguing! If you ask me, we should work together to make some money out of this! Those poor people in the town have nothing to do with us, so let's squeeze as much money as we can out of them and use that money to butter up those guys from Lumopolis!",
  ui_story_5071_50711401_24_dialog_content = "You're right. Since we're all here, we should just rob those guilds—",
  ui_story_5071_50711401_25_dialog_content = "My backer is among them!",
  ui_story_5071_50711401_26_dialog_content = "This is the Pit. I propose that we use the oldest rules to decide who gets the staff.",
  ui_story_5071_50711401_27_dialog_content = "Can't we all work together? We still don't know how many people will be escorting the staff.",
  ui_story_5071_50711401_28_dialog_content = "Whoever survives to the end can lead our men to take it. It's as simple as that.",
  ui_story_5071_50711401_29_dialog_content = "In your eyes, is that staff more important than Umbraton?",
  ui_story_5071_50711401_30_dialog_content = "Of course! The Shepherd's Staff represents old Istvan's clan and even becomes the token of the association of guilds...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>That's enough!</size>",
  ui_story_5071_50711401_32_dialog_content = "The most important thing right now is the whereabouts of that brat Kade and the staff. What's taking him so long?",
  ui_story_5071_50711401_33_dialog_content = "Were these people in charge of Umbraton back then? What a horrible place to be...",
  ui_story_5071_50711401_34_dialog_content = "I need to use my powers to find the Shadowlord, and quickly...",
  ui_story_5071_50711401_35_dialog_content = "I heard that old Istvan's son Valon is doing quite well and is already managing several guilds.",
  ui_story_5071_50711401_36_dialog_content = "He has even given us a lot of benefits. I wonder what he thinks about this Eclipsite attack.",
  ui_story_5071_50711401_37_dialog_content = "There! A younger version of the Shadowlord is hiding in that corner—",
  ui_story_5071_50711401_38_dialog_content = "Huh? Who is that in front of him?",
  ui_story_5071_50711401_39_dialog_content = "Did you hear it, Kade?",
  ui_story_5071_50711401_40_dialog_content = "These are the Umbraton bosses you wish to save.",
  ui_story_5071_50711401_41_dialog_content = "I don't have the time to talk about that, Valon. We got to go, time waits for no one!",
  ui_story_5071_50711401_X41_dialog_content = "Valon? Why is there only a vague recollection of Valon in the Shadowlord's memory?",
  ui_story_5071_50711401_42_dialog_content = "That young City Lord told me he would help us through the crisis!",
  ui_story_5071_50711401_43_dialog_content = "The reinforcement is outside the gate but hasn't yet made any move, so they're giving us more respect than usual.",
  ui_story_5071_50711401_44_dialog_content = "I just have to go sign the pact, and they will fight alongside Umbraton against the Eclipsite army!",
  ui_story_5071_50711401_45_dialog_content = "If you show yourself right now, they'll only attack you. Stay and talk with me for a while, and I'll help you come up with a plan.",
  ui_story_5071_50711401_46_dialog_content = "Don't worry, we're safe here. No one will overhear us.",
  ui_story_5071_50711401_47_dialog_content = "What are the terms of this pact, Kade? What are you prepared to give Lumopolis in exchange for their help?",
  ui_story_5071_50711401_48_dialog_content = "People of Umbraton? Free trading? Or is it even more taxes? They've already left Umbraton behind and will only get worse if they come back!",
  ui_story_5071_50711401_49_dialog_content = "Why would you betray Umbraton just to go groveling to Lumopolis? Have you truly given up on our dream?",
  ui_story_5071_50711401_50_dialog_content = "It was approved by our father as well as the association of guilds. This staff in my hand and the signed letter are the proof.",
  ui_story_5071_50711401_51_dialog_content = "This represents their unanimous consent.",
  ui_story_5071_50711401_52_dialog_content = "The people at the bottom of Umbraton's society, the ones who have been oppressed by both Lumopolis and the larger guilds—did you ever ask how they felt about this?",
  ui_story_5071_50711401_53_dialog_content = "Our intelligence says that the Eclipsite horde will be here in a day, but the independent forces of Umbraton each have their own agendas.",
  ui_story_5071_50711401_54_dialog_content = "In spite of everything, father and the association were the first to reach out to Lumopolis for protection. Meanwhile, the Gambi family and their allies started hiking up the ticket price for transportation out of the town...",
  ui_story_5071_50711401_55_dialog_content = "The poorer people of this town have no way of defending themselves or escaping. All they can do is sit and wait for death to come.",
  ui_story_5071_50711401_56_dialog_content = "We will defend it together!",
  ui_story_5071_50711401_57_dialog_content = "That's nothing more than wishful thinking on your part. Most people want to leave Umbraton, but I've gotten word that a number of gangs have started robbing them as they make their escapes.",
  ui_story_5071_50711401_58_dialog_content = "Anyone with even a hint of strength continues to turn a blind eye to the weak and the suffering. I don't know why Umbraton has to be this way, but this is what our hometown is...",
  ui_story_5071_50711401_59_dialog_content = "Thankfully, these thugs are people of Umbraton through and through. All it takes is a little provocation to get their blood boiling.",
  ui_story_5071_50711401_60_dialog_content = "That's why I've been nudging them from the shadows, just so that they could find this place. With a few choice words and the promise of rewards, they should become cooperative enough.",
  ui_story_5071_50711401_61_dialog_content = "What is it exactly you want?",
  ui_story_5071_50711401_62_dialog_content = "I told you before, Kade. I've been working hard to build up my strength.",
  ui_story_5071_50711401_63_dialog_content = "I'm going to use the Eclipsite invasion to rid Umbraton of its blight, once and for all.",
  ui_story_5071_50711401_64_dialog_content = "All we have to do is sacrifice these people, and we'll be able to lead the innocent safely out of the town.",
  ui_story_5071_50711401_65_dialog_content = "You should be by my side, purging their rotten pus from the town instead of begging the filth of Lumopolis for help. This is what Umbraton truly needs right now.",
  ui_story_5071_50711401_66_dialog_content = "Why, Valon? You've changed...",
  ui_story_5071_50711401_67_dialog_content = "Why couldn't you unite them against the Eclipsites instead of dividing them with infighting?",
  ui_story_5071_50711401_68_dialog_content = "What's the difference between this you and those bloodthirsty nobles who were here?",
  ui_story_5071_50711401_69_dialog_content = "These men are the scum of Umbraton, the leaders of the foulest criminals who corrupted our town. Letting them live will only bring harm to other people.",
  ui_story_5071_50711401_70_dialog_content = "This is our only chance, Kade! Help me get rid of them so we can lead the innocent to safety...",
  ui_story_5071_50711401_71_dialog_content = "Their deaths are necessary for the survival of Umbraton's most vulnerable people!",
  ui_story_5071_50711401_72_dialog_content = "... So what if they fled?",
  ui_story_5071_50711401_73_dialog_content = "Lumopolis would rule Umbraton, and the people here in the future would run into the same problems we did.",
  ui_story_5071_50711401_74_dialog_content = "And there would be another demonic son like me, born in the shadow and shunned by everyone.",
  ui_story_5071_50711401_75_dialog_content = "Then the cycle would begin again.",
  ui_story_5071_50711401_76_dialog_content = "It hasn't been easy to reach an accord with Lumopolis, and I must seize this opportunity for equal dialogue...",
  ui_story_5071_50711401_77_dialog_content = "It seems there's no changing your mind now...",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>Listen up, everyone, Kade is here!</color></size>",
  ui_story_5071_50711401_79_dialog_content = "*sudden silence*",
  ui_story_5071_50711401_80_dialog_content = "Valon! How could you!",
  ui_story_5071_50711401_81_dialog_content = "Do you hear the sound of all those footsteps? Now you have no choice but to fight them all and help me rid this town of their filth!",
  ui_story_5071_50711401_82_dialog_content = "But don't worry. My men and I will fight by your side, just like allies.",
  ui_story_5071_50711401_83_dialog_content = "Let's not be impulsive. We can still work together. We'll make that kid hand over the staff, then we'll transfer some supplies for defense!",
  ui_story_5071_50711401_84_dialog_content = "Urgh! W-Who—",
  ui_story_5071_50711401_85_dialog_content = "Someone has been attacked! Drats, you guys have ulterior motives and don't want to work together, I knew it!",
  ui_story_5071_50711401_86_dialog_content = "Let's kill that demon child first and fight for the staff later!",
  ui_story_5071_50711401_87_dialog_content = "Out of the way, I've got no time for you.",
  ui_story_5071_50711401_88_dialog_content = "Hands off my mark!",
  ui_story_5071_50711401_89_dialog_content = "I say, get out of the way—",
  ui_story_5071_50711401_90_dialog_content = "You'll die if you don't fight back, Kade. If that happens, all of our dreams will die with you.",
  ui_story_5071_50711401_91_dialog_content = "Drat! Out of my way!",
  ui_story_5071_50711401_92_dialog_content = "Don't you shortsighted people try to stop me!",
  ui_story_5071_50711401_93_dialog_content = "I stabbed him. Quickly! Help me—",
  ui_story_5071_50711401_94_dialog_content = "Urgh!",
  ui_story_5071_50711401_95_dialog_content = "Is this what you want, you pests? Well, you got it!",
  ui_story_5071_50711401_96_dialog_content = "No, stop! This fighting is pointless—",
  ui_story_5071_50711401_97_dialog_content = "Turn to ashes, all of you!",
  ui_story_5071_50711401_98_dialog_content = "No one can hear me...",
  ui_story_5071_50711401_99_dialog_content = "It's a massacre... I didn't know the Shadowlord had such a brutal side to him... Has he completely lost control?",
  ui_story_5071_50711401_100_dialog_content = "Is that how he ended up killing his best friend?",
  ui_story_5071_50711401_101_dialog_content = "Wait a second, what am I thinking? The break in the Shadowlord's emotions should be right here!",
  ui_story_5071_50711401_102_dialog_content = "Please listen to me! You have to come to your senses—",
  ui_story_5071_50711402_1_dialog_content = "The bosses are all...",
  ui_story_5071_50711402_2_dialog_content = "Look! I think the Lumopolis army is moving. It looks like they are coming this way... right?",
  ui_story_5071_50711402_3_dialog_content = "You and I are the only ones left now...",
  ui_story_5071_50711402_4_dialog_content = "Congratulations on surviving the Pit for the second time, Kade.",
  ui_story_5071_50711402_5_dialog_content = "*roars*",
  ui_story_5071_50711402_6_dialog_content = "Out of the way, Valon! I have to go cement the pact with proof...",
  ui_story_5071_50711402_7_dialog_content = "Even after all of this, you still believe in Lumopolis' lies?",
  ui_story_5071_50711402_8_dialog_content = "Do you remember the <color=#FFB400>dream</color> I once told you about, Kade?",
  ui_story_5071_50711402_9_dialog_content = "The foundation has already been laid. Come with me, and with the power of the Shepherd's Staff, we can unite the association of guilds and the weak people of Umbraton under us.",
  ui_story_5071_50711402_10_dialog_content = "We'll make a new home for ourselves, a safe haven for lost souls like us.",
  ui_story_5071_50711402_11_dialog_content = "A place where we can live in happiness and equality, where we can travel anywhere and do business with anyone in the <color=#FFB400>land</color>—",
  ui_story_5071_50711402_12_dialog_content = "(A traveling guild... Could this be how the <color=#FFB400>Continental Guild</color> started? And the notion of free trade sounds just like the <color=#FFB400>Cloudrover Guild</color>!)",
  ui_story_5071_50711402_13_dialog_content = "(Mr. Valon's dream... It's no different than Lady Sheol's! That's why Ms. Hanstie kept saying that she stole someone else's dream!)",
  ui_story_5071_50711402_14_dialog_content = "But what about father? What about the guild workers who don't want to leave?",
  ui_story_5071_50711402_15_dialog_content = "What about those kids tricked into joining a gang? If they don't want to leave either—",
  ui_story_5071_50711402_16_dialog_content = "... Father and those people aren't willing to leave. It may have more to do with not wanting to give up their prospects, not some kind of love.",
  ui_story_5071_50711402_17_dialog_content = "So many people have been deprived of good lives here, and they want nothing more than to leave. Would you really force them to stay here and die for this rotten town?",
  ui_story_5071_50711402_18_dialog_content = "You weep for the children by the street, but those working for the guilds might be their parents or siblings!",
  ui_story_5071_50711402_19_dialog_content = "The connection between us and our hometown is tighter than you think, and no one can severe the bond.",
  ui_story_5071_50711402_20_dialog_content = "People may love or hate their home, but should never abandon it—",
  ui_story_5071_50711402_21_dialog_content = "I'm staying with father and defending our home our way.",
  ui_story_5071_50711402_22_dialog_content = "The Eclipsite horde will be here soon, and the Lumopolis military is also preparing for battle. Before long, this place will be plunged into total chaos.",
  ui_story_5071_50711402_23_dialog_content = "The people of Lumopolis won't care if you stay here to die!",
  ui_story_5071_50711402_24_dialog_content = "At least we die for our home.",
  ui_story_5071_50711402_25_dialog_content = "Father and I have never seen eye to eye...",
  ui_story_5071_50711402_26_dialog_content = "I've never had his approval, unlike you. In the end, it seems you really are the better child of Istvan.",
  ui_story_5071_50711402_27_dialog_content = "But you're different than him. Ever since you started encouraging me to pursue my dream, I knew you were the only person who could truly understand me.",
  ui_story_5071_50711402_28_dialog_content = "So please, for our dream's sake, just come with me—",
  ui_story_5071_50711402_29_dialog_content = "Our dream is to change this place! If we can't hold on, the dream becomes a lie.",
  ui_story_5071_50711402_30_dialog_content = "It was hard to finally convince them to unite. I can't give up now...",
  ui_story_5071_50711402_31_dialog_content = "It's all a lie, Kade! These people are only interested in benefitting themselves! They'll start fighting amongst each other soon enough!",
  ui_story_5071_50711402_32_dialog_content = "I understand the gangs let people down. But they're not necessarily beyond help.",
  ui_story_5071_50711402_33_dialog_content = "Many of them didn't have a choice. But if even I could get a righteous aspiration, other people could too!",
  ui_story_5071_50711402_34_dialog_content = "As long as we persist, we'll leave the seed.",
  ui_story_5071_50711402_35_dialog_content = "Even if it's not us, someday somehow, someone will complete our dream.",
  ui_story_5071_50711402_36_dialog_content = "Kade... You've been struggling in the present all this time. You're being reckless and only focusing on offense, just like when we play chess.",
  ui_story_5071_50711402_37_dialog_content = "Punishing evil like this will only destroy everything before us. Since when did you... see beyond that?",
  ui_story_5071_50711402_38_dialog_content = "Umbraton will rely on itself in the future, but that doesn't mean we can't make allies. We can't fight alone but ask Lumopolis for aid.",
  ui_story_5071_50711402_39_dialog_content = "You're the one who made me understand the meaning of friendship, Valon. Why have you changed?",
  ui_story_5071_50711402_40_dialog_content = "Lumopolis is the source of Umbraton's darkness... While they arrogantly bask in the light, they leave the rest of us trapped in the shadows.",
  ui_story_5071_50711402_41_dialog_content = "I envy you for letting your hate go and moving on so effortlessly.",
  ui_story_5071_50711402_42_dialog_content = "But I can never forgive those people. Compromising with filth like them is no different than turning a blind eye to their injustices, and I refuse to do that.",
  ui_story_5071_50711402_43_dialog_content = "Protecting the people I care about... already demands all of my strength.",
  ui_story_5071_50711402_44_dialog_content = "Valon...",
  ui_story_5071_50711402_45_dialog_content = "Not once did you ever best me in chess, Kade. What makes you think you can best all of Lumopolis?",
  ui_story_5071_50711402_46_dialog_content = "When it comes to deception, no one is better than they are—",
  ui_story_5071_50711402_47_dialog_content = "Please, Kade, I'm begging you. Give me the Shepherd's Staff, and come with me...",
  ui_story_5071_50711402_48_dialog_content = "I... decline.",
  ui_story_5071_50711402_49_dialog_content = "Is this how it has to end between us? Can there really only be one victor in the Pit?",
  ui_story_5071_50711402_50_dialog_content = "I never thought our blades would cross someday... But I...",
  ui_story_5071_50711402_51_dialog_content = "What's happening here? Where is our liaison, Mr. Kade?",
  ui_story_5071_50711402_52_dialog_content = "!",
  ui_story_5071_50711402_53_dialog_content = "You're not allowed inside!",
  ui_story_5071_50711402_54_dialog_content = "I don't have time to deal with you guys. Where is Mr. Kade?",
  ui_story_5071_50711402_55_dialog_content = "Lumopolis scum! How dare you drag your army into our home!",
  ui_story_5071_50711402_56_dialog_content = "Drive them out of here!",
  ui_story_5071_50711402_57_dialog_content = "Don't act so smugly, you lowlifes who live in Umbraton ditches.",
  ui_story_5071_50711402_58_dialog_content = "Defeat them and find where Kade is. Don't let him be killed by these scum.",
  ui_story_5071_50711402_59_dialog_content = "Curse these Lumopolis dwellers! Urgh!",
  ui_story_5071_50711402_60_dialog_content = "Are you there, Mr. Kade? Because it's been some time since our agreed meeting time, we...",
  ui_story_5071_50711402_61_dialog_content = "Is this truly your plan, Kade?",
  ui_story_5071_50711402_62_dialog_content = "Are you really willing to stoop this low? What a disgrace!",
  ui_story_5071_50711402_63_dialog_content = "Back up. You can't go into Umbraton like that.",
  ui_story_5071_50711402_64_dialog_content = "Mr. Kade, I don't think you have a sufficient understanding of what a commitment is. An agreement is more important than anything.",
  ui_story_5071_50711402_65_dialog_content = "Back up!",
  ui_story_5071_50711402_66_dialog_content = "You betrayed all of Umbraton by letting these dogs into our home!",
  ui_story_5071_50711402_67_dialog_content = "Umbraton dweller! Watch your language!",
  ui_story_5071_50711402_68_dialog_content = "I won't let you defile my home!",
  ui_story_5071_50711402_69_dialog_content = "Do not attack. Put the weapon down, Valon!",
  ui_story_5071_50711402_70_dialog_content = "Fall back! Fall back! Drats, that guy's Luminatics—",
  ui_story_5071_50711402_71_dialog_content = "The commander has been hurt! Retaliate! Hit back at them!",
  ui_story_5071_50711402_72_dialog_content = "You arrogant fools won't escape so easily! I—",
  ui_story_5071_50711402_73_dialog_content = "(Oh, no, the Lumopolis soldiers are firing indiscriminately... Gotta stop them!)",
  ui_story_5071_50711402_74_dialog_content = "(Rats, I just can't stop all this...)",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>Bang—</color>",
  ui_story_5071_50711402_76_dialog_content = "Y-You scum... Kade—",
  ui_story_5071_50711402_77_dialog_content = "<size=40>Valon!</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>Ahhhh!</size>",
  ui_story_5071_50711402_79_dialog_content = "Out! All of you, out!",
  ui_story_5071_50711402_80_dialog_content = "Let's retreat now! This guy has gone crazy and doesn't care about the agreement anymore. Retreat!",
  ui_story_5071_50711402_81_dialog_content = "Retreat! Get back, now!",
  ui_story_5071_50711402_82_dialog_content = "Valon...",
  ui_story_5071_50711402_83_dialog_content = "Kade... Things always seem to go from bad to worse here in Umbraton. How are we supposed to save this place now?",
  ui_story_5071_50711402_84_dialog_content = "The shadow of Lumopolis... will put out the flames... And Umbraton will never be purified...",
  ui_story_5071_50711402_85_dialog_content = "Now who will be... the savior of the oppressed...",
  ui_story_5071_50711402_86_dialog_content = "It's possible! It's possible, Valon. Just give me more time. We just have to make it through the crisis...",
  ui_story_5071_50711402_87_dialog_content = "Your dream can still become reality, and this place will thrive!",
  ui_story_5071_50711402_88_dialog_content = "Heheh... You really are... too naive...",
  ui_story_5071_50711402_89_dialog_content = "Don't tell father what I did... not because I'm ashamed... but because I don't want him to suffer...",
  ui_story_5071_50711402_90_dialog_content = "... I promise.",
  ui_story_5071_50711402_91_dialog_content = "Come closer, brother... I still have something to tell you...",
  ui_story_5071_50711402_92_dialog_content = "*coughing* ... We're men of Umbraton, through and through. Violence will never be gone from our hearts...",
  ui_story_5071_50711402_93_dialog_content = "Since I can't stop you from doing all of this, at least keep your promise to me...",
  ui_story_5071_50711402_94_dialog_content = "From now on, you'll have to do whatever it takes to keep Umbraton alive...",
  ui_story_5071_50711402_95_dialog_content = "I... promise.",
  ui_story_5071_50711402_96_dialog_content = "My brother.",
  ui_story_5071_50711402_97_dialog_content = "...",
  ui_story_5071_50711402_98_dialog_content = "No... No... You didn't do it at all, did you, Shadowlord?",
  ui_story_5071_50711402_99_dialog_content = "... Those people were drawn by the uproar and only entered Umbraton to ensure the pact to be carried out.",
  ui_story_5071_50711402_100_dialog_content = "They were too aloof to show us respect, but we were a little too sensitive. We didn't learn to cooperate until we paid the price.",
  ui_story_5071_50711402_101_dialog_content = "But does that absolve me of my sins?",
  ui_story_5071_50711402_102_dialog_content = "A wise person once said, \"The power of words can bind the soul.\"",
  ui_story_5071_50711402_103_dialog_content = "So I just cannot free myself from Valon's words.",
  ui_story_5071_50711501_1_dialog_content = "To preserve our alliance with Lumopolis, I never explained Valon's death to anyone. Regardless, it was all my fault.",
  ui_story_5071_50711501_2_dialog_content = "But that clearly isn't the truth...",
  ui_story_5071_50711501_3_dialog_content = "When I became a child of Istvan, I vowed never to harm my own family or bring harm to the interests of our family...",
  ui_story_5071_50711501_4_dialog_content = "But in the end, I broke that vow. No matter how anyone saw it, I had no right to face our father.",
  ui_story_5071_50711501_5_dialog_content = "Yet just before he died, our father chose to leave everything in my hands. And so, \"Istvan\" became my new name.",
  ui_story_5071_50711501_6_dialog_content = "Shadowlord...",
  ui_story_5071_50711501_7_dialog_content = "I decided to become a shadow—",
  ui_story_5071_50711501_8_dialog_content = "I will live in the dark as a shadow and resort to anything to make sure Umbraton survives.",
  ui_story_5071_50711501_9_dialog_content = "I've hidden the past from myself for so long that I can hardly recall it... But the sins of my past still haunt me as nightmares.",
  ui_story_5071_50711501_10_dialog_content = "A fair price in exchange for my survival.",
  ui_story_5071_50711501_11_dialog_content = "No... It's not fair at all.",
  ui_story_5071_50711501_12_dialog_content = "For Umbraton's future, I'm willing to sacrifice everything. This is how I've always done things.",
  ui_story_5071_50711501_13_dialog_content = "Like the arrogant man that I am, I'll sacrifice everything and bear responsibility for it all. Valon... He was the first price I had to pay.",
  ui_story_5071_50711501_14_dialog_content = "You didn't do anything wrong... You know that, right? But you still choose to punish yourself like this.",
  ui_story_5071_50711501_15_dialog_content = "... I made this decision for Umbraton's sake, and the consequences are mine to bear. Regardless of right or wrong, I only wish to protect this town.",
  ui_story_5071_50711501_16_dialog_content = "I've always believed that someone will stand atop this place of darkness someday, a person who will ultimately succeed me.",
  ui_story_5071_50711501_17_dialog_content = "I'm happy to say that I can see that wish coming true soon.",
  ui_story_5071_50711501_18_dialog_content = "If you really feel that way, then why are you still trapped in these memories?",
  ui_story_5071_50711501_19_dialog_content = "Why, indeed... When I wake up in the middle of the night, I sometimes ask myself the very same question.",
  ui_story_5071_50711501_20_option_content = "It's because of your guilt.",
  ui_story_5071_50711501_21_dialog_content = "You're saying that I still blame myself?",
  ui_story_5071_50711501_22_option_content = "It's because of your regret.",
  ui_story_5071_50711501_23_dialog_content = "Regret... You think that's what I feel?",
  ui_story_5071_50711501_24_dialog_content = "I think that, somewhere deep in your heart, you've always felt remorse about these things.",
  ui_story_5071_50711501_X24_dialog_content = "That's why you were unable to remember what Valon looked like.",
  ui_story_5071_50711501_X25_dialog_content = "...",
  ui_story_5071_50711501_25_dialog_content = "Have you really not considered telling people the truth?",
  ui_story_5071_50711501_26_dialog_content = "The truth can cut deeper than any blade at times. For the sake of peace, I must continue this charade no matter how superficial it may be.",
  ui_story_5071_50711501_27_dialog_content = "I regret nothing—",
  ui_story_5071_50711501_28_dialog_content = "You should have realized it by now... You've been living in guilt and remorse all this time.",
  ui_story_5071_50711501_29_dialog_content = "Remorse over not telling Mr. Valon and the old Istvan the truth.",
  ui_story_5071_50711501_30_dialog_content = "Perceptive as always, but those old shadows are long gone now. I'll never have a chance to reconcile with them again.",
  ui_story_5071_50711501_31_dialog_content = "Which is why you started punishing yourself... and trapping yourself in this nightmare...",
  ui_story_5071_50711501_32_dialog_content = "I've played my part for so long that I can hardly tell the difference anymore. Have I become one with the shadows, or are the shadows simply playing my role?",
  ui_story_5071_50711501_33_dialog_content = "All that I've done... Is it truly enough?",
  ui_story_5071_50711501_34_dialog_content = "You've already given up so much for Umbraton...",
  ui_story_5071_50711501_35_dialog_content = "If only I hadn't hesitated, if only I had stopped Valon when I had the chance, maybe things would have been different—",
  ui_story_5071_50711501_36_dialog_content = "I never wanted to pay the price with his life.",
  ui_story_5071_50711501_37_dialog_content = "Heh... If I can still feel this way, then it appears the old Kade still exists within me. After all this time, I'm still desperate for your forgiveness, my brother, my friend...",
  ui_story_5071_50711501_38_dialog_content = "Heh—",
  ui_story_5071_50711501_39_dialog_content = "Hahahahaha—",
  ui_story_5071_50711501_40_dialog_content = "Shadowlord?",
  ui_story_5071_50711501_41_dialog_content = "Perhaps I really have grown old. Have I truly lost the resolve of my youth already?",
  ui_story_5071_50711501_42_dialog_content = "How could I allow myself to indulge in such thoughts?",
  ui_story_5071_50711501_43_dialog_content = "You're finally back to your senses, Shadowlord!",
  ui_story_5071_50711501_44_dialog_content = "Not enough, still not enough!",
  ui_story_5071_50711501_45_dialog_content = "There's more fiery rage to be unleashed!",
  ui_story_5071_50711501_46_dialog_content = "(The Shadowlord's emotions are beginning to stabilize, but I sense something else in his heart. Something faint...)",
  ui_story_5071_50711501_47_dialog_content = "If it wasn't for your help just now, I would have forgotten the lessons of the past. Their shadows exist to remind me not to make the same mistakes again.",
  ui_story_5071_50711501_48_dialog_content = "No more waffling!",
  ui_story_5071_50711501_49_dialog_content = "If they want brutality, then brutality is what they'll receive! I'm not going to hold back anymore!",
  ui_story_5071_50711501_50_dialog_content = "You're almost there, Shadowlord! Wake up!",
  ui_story_5071_50711501_51_dialog_content = "(Did it work? My body... My consciousness is getting fuzzy... like I'm getting pulled out of here...)",
  ui_story_5071_50711501_52_dialog_content = "Shadowlord... I'll be waiting for you outside...",
  ui_story_5071_50711501_53_dialog_content = "Thank you, kind Caelestite.",
  ui_story_5071_50711501_54_dialog_content = "I should also...",
  ui_story_5071_50711501_55_dialog_content = "Kade.",
  ui_story_5071_50711501_56_dialog_content = "!",
  ui_story_5071_50711501_57_dialog_content = "Honestly... it's been a long time.",
  ui_story_5071_50711501_58_dialog_content = "Valon?",
  ui_story_5071_50711501_59_dialog_content = "Kade... I have a question I want you to answer again.",
  ui_story_5071_50711501_60_dialog_content = "Can you look into my eyes and answer truthfully?",
  ui_story_5071_50711501_61_dialog_content = "...",
  ui_story_5071_50711501_62_dialog_content = "What price are you willing to pay to save Umbraton?",
  ui_story_5071_50711501_63_dialog_content = "... Do you truly have to ask?",
  ui_story_5071_50711501_64_dialog_content = "Everything! I'll pay everything!",
  ui_story_5071_50711501_65_dialog_content = "It's just like you... to say that, Kade...",
  ui_story_5071_50711501_66_dialog_content = "Now go, my brother! Show all the enemies of Umbraton your resolve!",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5071_50711501_68_dialog_content = "Heh, I didn't think I could last this long.",
  ui_story_5071_50711501_69_dialog_content = "The airship is about to explode. Do you honestly believe Kade will come back?",
  ui_story_5071_50711501_70_dialog_content = "Yes—and PlayerName also promised me to come back with the Shadowlord.",
  ui_story_5071_50711501_71_dialog_content = "Kade is nothing but a hypocrite... Even if he survives, he couldn't possibly save you now.",
  ui_story_5071_50711501_72_dialog_content = "His true face will only fill you all with despair.",
  ui_story_5071_50711501_73_dialog_content = "Ms. Hanstie, we're here—",
  ui_story_5071_50711501_74_dialog_content = "More reinforcement even now?",
  ui_story_5071_50711501_75_dialog_content = "And even got Eclipsites fighting for her? This has taken a turn for the worse.",
  ui_story_5071_50711501_76_dialog_content = "Concentrate your attacks! Don't give her a chance to catch her breath!",
  ui_story_5071_50711501_77_dialog_content = "Shadowlord...",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5071_50711501_79_dialog_content = "What's happening?",
  ui_story_5071_50711501_80_dialog_content = "There was a sudden big explosion...",
  ui_story_5071_50711501_81_dialog_content = "W-Wait! What's that?",
  ui_story_5071_50711501_82_dialog_content = "There's someone in the fire... C-Could it be—",
  ui_story_5071_50711501_83_dialog_content = "Shadowlord!",
  ui_story_5071_50711501_84_dialog_content = "Thousands of scars... and ferocious blue flames. That's him—",
  ui_story_5071_50711501_85_dialog_content = "<size=45>That's the demon of the Pit!</size>",
  ui_story_5071_50711501_86_dialog_content = "He can't be defeated... He's an undefeatable legend... How can we possibly...",
  ui_story_5071_50711501_87_dialog_content = "No running, you cowards! Our goal is to exact our vengeance on that man!",
  ui_story_5071_50711501_88_dialog_content = "As old as he is now, there's no way he could possibly defeat this many opponents...",
  ui_story_5071_50711501_89_dialog_content = "Even after all of this, you still want to run away?",
  ui_story_5071_50711501_90_dialog_content = "W-We won't let you!",
  ui_story_5071_50711501_91_dialog_content = "You're tardy, Shadowlord. Is old age getting to you?",
  ui_story_5071_50711501_92_dialog_content = "Forgive me, Lady Sheol. You are right—I've been trapped behind such a sad and weary mask all along.",
  ui_story_5071_50711501_93_dialog_content = "But now, I think it's time to let my old shadow return.",
  ui_story_5071_50711501_94_dialog_content = "Ava... My hesitation is what caused me to lose Valon.",
  ui_story_5071_50711501_95_dialog_content = "But I won't hesitate any longer—even if you're my enemy.",
  ui_story_5071_50711501_96_dialog_content = "Silence! You have no right to speak Valon's name!",
  ui_story_5071_50711501_97_dialog_content = "When this incident began, I knew you had a hand in it all along—",
  ui_story_5071_50711501_98_dialog_content = "You're free to seek vengeance against me, but you should've left the innocents alone.",
  ui_story_5071_50711501_99_dialog_content = "Shut up! Shut your mouth! You have no idea how much I've suffered!",
  ui_story_5071_50711501_100_dialog_content = "I've done so many unspeakable things, all for this moment!",
  ui_story_5071_50711501_101_dialog_content = "I painted so many disgusting forgeries for money... And to expose you, I performed so many disgusting experiments...",
  ui_story_5071_50711501_102_dialog_content = "All of the strength and people I've gathered over the years, just so that I could have my revenge!",
  ui_story_5071_50711501_103_dialog_content = "Your plan failed. The Shadowlord's mind is perfectly stable now. He won't lose control ever again!",
  ui_story_5071_50711501_104_dialog_content = "Is that so? Very well then... If you insist on maintaining your pointless disguise...",
  ui_story_5071_50711501_105_dialog_content = "Then I'll appease Valon's spirit by killing you myself!",
  ui_story_5071_50711501_106_dialog_content = "All of you, attack!",
  ui_story_5071_50711501_107_dialog_content = "Are these pathetic sellouts all the help you could get?",
  ui_story_5071_50711501_108_dialog_content = "Urgh—",
  ui_story_5071_50711501_109_dialog_content = "Don't underestimate us, Ava!",
  ui_story_5071_50711501_110_dialog_content = "W-We're no match for him. Run!",
  ui_story_5071_50711501_111_dialog_content = "The darkness that Valon and I conquered in the past is far greater than anything you've ever seen!",
  ui_story_5071_50711501_112_dialog_content = "Y-You monster...",
  ui_story_5071_50711501_113_dialog_content = "The Shadowlord is going wild—",
  ui_story_5071_50711501_114_dialog_content = "Now that all grace has been cast aside, prepare to beg for mercy!",
  ui_story_5071_50711501_115_dialog_content = "H-How could this be? His body is covered in wounds, so why is he...",
  ui_story_5071_50711501_116_dialog_content = "Keep attacking! He must be losing strength by now!",
  ui_story_5071_50711501_117_dialog_content = "Losing strength? I'm just warming up!",
  ui_story_5071_50711501_118_dialog_content = "E-Everything has been burned into ashes... This guy is ageless...",
  ui_story_5071_50711501_119_dialog_content = "Aaahhhh—",
  ui_story_5071_50711501_120_dialog_content = "This is what he's been hiding, an appearance blazing in chaos...",
  ui_story_5071_50711501_121_dialog_content = "Are you happy now?",
  ui_story_5071_50711501_122_dialog_content = "Congratulations, this is the beast you wanted, isn't it?",
  ui_story_5071_50711501_123_dialog_content = "H-Hurry! Bring that thing out right now!",
  ui_story_5071_50711501_124_dialog_content = "I'll pay any cost, so just bring it out...",
  ui_story_5071_50711501_125_dialog_content = "<size=50>Ava!</size>",
  ui_story_5071_50711502_1_dialog_content = "Did you all see that? Even that Eclipsite couldn't stop him. Istvan is the real monster!",
  ui_story_5071_50711502_2_dialog_content = "Running away, are we?",
  ui_story_5071_50711502_3_dialog_content = "Don't come closer—",
  ui_story_5071_50711502_4_dialog_content = "!",
  ui_story_5071_50711502_5_dialog_content = "Valon...",
  ui_story_5071_50711502_6_dialog_content = "Would you want me to spare her?",
  ui_story_5071_50711502_7_dialog_content = "Help—",
  ui_story_5071_50711502_8_dialog_content = "You're pathetic, Ava!",
  ui_story_5071_50711502_9_dialog_content = "No...",
  ui_story_5071_50711502_10_dialog_content = "Give up. I won't hurt you, but you'll get the justice you deserve.",
  ui_story_5071_50711502_11_dialog_content = "I'll continue Valon's dream, our dream.",
  ui_story_5071_50711502_12_dialog_content = "That dream... obviously shattered...",
  ui_story_5071_50711502_13_dialog_content = "It's a pity, Ava, I never thought you would fall this far.",
  ui_story_5071_50711502_14_dialog_content = "Especially when you were Valon's...",
  ui_story_5071_50711502_15_dialog_content = "Don't say that to me. I don't need your sympathy!",
  ui_story_5071_50711502_16_dialog_content = "You can't reach this far without a lot of help.",
  ui_story_5071_50711502_17_dialog_content = "Those who hate me took advantage of you... How unforgivable!",
  ui_story_5071_50711502_18_dialog_content = "...",
  ui_story_5071_50711502_19_dialog_content = "If you're not willing to divulge, I'll find out who they are on my own.",
  ui_story_5071_50711502_20_dialog_content = "But I promise you, you'll get a fair trial.",
  ui_story_5071_50711502_21_dialog_content = "Stop crying alligator tears. It's disgusting!",
  ui_story_5071_50711502_22_dialog_content = "You killed Valon and took everything from him, yet you weren't judged.",
  ui_story_5071_50711502_23_dialog_content = "Why should we be your sacrificial lamb?",
  ui_story_5071_50711502_24_dialog_content = "I curse you! May your heart be trapped forever in the abyss!",
  ui_story_5071_50711502_25_dialog_content = "... A very long time ago, Valon and I both held out hope for laws and rules in Umbraton.",
  ui_story_5071_50711502_26_dialog_content = "He craved a new order and entrusted that dream to me.",
  ui_story_5071_50711502_27_dialog_content = "If possible, I'd rather not hold it over you.",
  ui_story_5071_50711502_28_dialog_content = "Valon...",
  ui_story_5071_50711502_29_dialog_content = "You founded the Continental Guild for Valon, didn't you?",
  ui_story_5071_50711502_30_dialog_content = "Even when you're full of hatred, out of love you still retain that pure...",
  ui_story_5071_50711502_31_dialog_content = "Enough, stop...",
  ui_story_5071_50711502_32_dialog_content = "I've hidden in the shadows long enough to tell what kind of person is beyond help.",
  ui_story_5071_50711502_33_dialog_content = "Ava, there's still purity in your heart.",
  ui_story_5071_50711502_34_dialog_content = "That is the shadow from your past.",
  ui_story_5071_50711502_35_dialog_content = "Therefore, I promise you here and now—",
  ui_story_5071_50711502_36_dialog_content = "One day, when you've atoned for your crimes and I'm done reforming Umbraton...",
  ui_story_5071_50711502_37_dialog_content = "You're welcome to take my life.",
  ui_story_5071_50711502_38_dialog_content = "You...",
  ui_story_5071_50711502_39_dialog_content = "There there, I see the Guardians come with rescue squads.",
  ui_story_5071_50711502_40_dialog_content = "Say whatever you got left to them.",
  ui_story_5071_50711502_41_dialog_content = "... Let me go!",
  ui_story_5071_50711502_42_dialog_content = "Why me?",
  ui_story_5071_50711502_43_dialog_content = "The real butcher is right in front of you!",
  ui_story_5071_50711502_44_dialog_content = "Look at him, look at those ugly scars! Don't you get it?",
  ui_story_5071_50711502_45_dialog_content = "He's Umbraton's biggest sinner and enemy!",
  ui_story_5071_50711502_46_dialog_content = "Have you forgotten how your mother died?",
  ui_story_5071_50711502_47_dialog_content = "...",
  ui_story_5071_50711502_48_dialog_content = "I'm really not cut out for this. Hurry up, Guardians!",
  ui_story_5071_50711502_49_dialog_content = "You all saw through him, right?",
  ui_story_5071_50711502_50_dialog_content = "Tremble in fear, everyone and all those who wish to remain by him!",
  ui_story_5071_50711502_51_dialog_content = "The truth will come out one day!",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>I curse you, Kade!</color>",
  ui_story_5071_50711601_1_dialog_content = "The cause of Ms. Yvonne's death is finally made public, and it is venom. She was still at her pinnacle when Hanstie murdered her.",
  ui_story_5071_50711601_2_dialog_content = "I regret not having more conversations with her.",
  ui_story_5071_50711601_3_dialog_content = "She was such a good person...",
  ui_story_5071_50711601_4_dialog_content = "Vergil took it very hard as well and hasn't slept or eaten for days. I'll have to assign more work to get his mind off it.",
  ui_story_5071_50711601_5_dialog_content = "I don't think you should overwork him like that, Lady Sheol...",
  ui_story_5071_50711601_6_dialog_content = "In memory of Ms. Yvonne, we're releasing her books. This is the first batch.",
  ui_story_5071_50711601_7_dialog_content = "Please deliver a few copies to the Shadowlord.",
  ui_story_5071_50711601_8_dialog_content = "I'm sure that would make the Shadowlord really happy... Huh? What are all those books behind you?",
  ui_story_5071_50711601_9_dialog_content = "Oh, that! That's the new printing of \"Mrs. Red Mercury,\" my favorite series.",
  ui_story_5071_50711601_X9_dialog_content = "The lilies on the cover are so simple and beautiful... How fitting for Mrs. Red Mercury... and your mother too...",
  ui_story_5071_50711601_X10_dialog_content = "Eternal memories, insurmountable love, and profound blessings. That is what lilies symbolize.",
  ui_story_5071_50711601_X11_dialog_content = "... No questions?",
  ui_story_5071_50711601_X12_dialog_content = "You already told me about my mother, right?",
  ui_story_5071_50711601_X13_dialog_content = "Yes.",
  ui_story_5071_50711601_X14_dialog_content = "Then what's there to ask?",
  ui_story_5071_50711601_X15_dialog_content = "... The truth is a double-edged sword. Sometimes, I opted for white lies.",
  ui_story_5071_50711601_X16_dialog_content = "Your mother did die of illness, from the depression she fell into trying to find you.",
  ui_story_5071_50711601_X17_dialog_content = "I visited her on her deathbed and heard her last request.",
  ui_story_5071_50711601_X18_dialog_content = "It was the great love a mother had for her daughter. I didn't want you to feel guilty, so...",
  ui_story_5071_50711601_X19_dialog_content = "Can I count that as another favor you owe me?",
  ui_story_5071_50711601_X20_dialog_content = "... Only kidding. Thank you, uncle.",
  ui_story_5071_50711601_X21_dialog_content = "Just don't do that anymore.",
  ui_story_5071_50711601_X22_dialog_content = "Honesty should be the policy for doing business in Umbraton.",
  ui_story_5071_50711601_X23_dialog_content = "Haha, I'll keep that advice in mind, Lady Sheol.",
  ui_story_5071_50711601_X24_dialog_content = "Mother will be happy to know the lilies are a perfect fit for me too!",
  ui_story_5071_50711601_10_dialog_content = "Too bad I'm too occupied to read it again in peace.",
  ui_story_5071_50711601_11_dialog_content = "It's a shame what happened to the airship...",
  ui_story_5071_50711601_12_dialog_content = "It's okay, not the first time that's happened to me. You win some, you lose some. That's how business goes.",
  ui_story_5071_50711601_13_dialog_content = "I'm free to do business anywhere without an airship anyway.",
  ui_story_5071_50711601_14_dialog_content = "I'm relieved to hear that and to see how optimistic you are about everything, Lady Sheol! Take care!",
  ui_story_5071_50711601_15_dialog_content = "I'm glad my dear PlayerName is consoling me, but doing that with your Colossus in tow does miff me a little.",
  ui_story_5071_50711601_16_dialog_content = "Sorry—",
  ui_story_5071_50711601_17_dialog_content = "Alright...",
  ui_story_5071_50711601_18_dialog_content = "You go and fly proudly with our dreams in tow...",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>Knock, knock—</color>",
  ui_story_5071_50711601_20_dialog_content = "Enter.",
  ui_story_5071_50711601_21_dialog_content = "It's me, Shadowlord. I came to deliver some books—huh?",
  ui_story_5071_50711601_22_dialog_content = "What is it? Did my appearance frighten you?",
  ui_story_5071_50711601_23_dialog_content = "What's going on?",
  ui_story_5071_50711601_24_dialog_content = "The smoke in the shadows has yet to subside. Something tells me that the fighting isn't over yet and I have to be prepared.",
  ui_story_5071_50711601_25_dialog_content = "... I'll just leave these books here.",
  ui_story_5071_50711601_26_dialog_content = "Sheol really enjoys sending you on errands like this... Thank you.",
  ui_story_5071_50711601_27_dialog_content = "Are you still having nightmares nowadays?",
  ui_story_5071_50711601_28_dialog_content = "Haha, that all depends on how you define \"nightmares.\" I used to be a prisoner of my guilt, and my dreams were full of distorted memories of the past.",
  ui_story_5071_50711601_29_dialog_content = "But now I only dream of the unadorned truth. Would you call my dreams \"nightmares\" now?",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>Knock, knock, knock—</color>",
  ui_story_5071_50711601_31_dialog_content = "Please stay here. There's no need to leave.",
  ui_story_5071_50711601_32_dialog_content = "Come in.",
  ui_story_5071_50711601_33_dialog_content = "Lord Istvan! Lord Istvan!",
  ui_story_5071_50711601_34_dialog_content = "My dear Lord Istvan... Please accept my respect. You should remember me. We were partners.",
  ui_story_5071_50711601_35_dialog_content = "If you remember our friendship, please listen to my heartfelt confession—",
  ui_story_5071_50711601_36_dialog_content = "Speak.",
  ui_story_5071_50711601_37_dialog_content = "I did waver on the Cloudrover Airship and acted inappropriately with some bad friends...",
  ui_story_5071_50711601_38_dialog_content = "When the Umbraton Guild closes them down, our guild is also... Please believe me! I'm sincerely repenting!",
  ui_story_5071_50711601_39_dialog_content = "So... Please show mercy and allow me to return to the Umbraton Guild.",
  ui_story_5071_50711601_40_dialog_content = "You say that we're partners.",
  ui_story_5071_50711601_41_dialog_content = "But when the reforms began, you hid from the shadows for fear of involving yourself with me.",
  ui_story_5071_50711601_42_dialog_content = "No, that's not what happened.",
  ui_story_5071_50711601_43_dialog_content = "Behind my back, you and your associates made a fortune through your underground business...",
  ui_story_5071_50711601_44_dialog_content = "In your most glorious moments, you never took my advice into consideration.",
  ui_story_5071_50711601_45_dialog_content = "It was only after the Umbraton Guild sanctioned your business that you came to me seeking forgiveness.",
  ui_story_5071_50711601_46_dialog_content = "I-It's because...",
  ui_story_5071_50711601_47_dialog_content = "Spare me your excuses—not once have you ever respected me or seen me as a business partner.",
  ui_story_5071_50711601_48_dialog_content = "In your eyes, the Shadowlord is nothing but an obstacle to overcome.",
  ui_story_5071_50711601_49_dialog_content = "No... that's not it. Please listen to me!",
  ui_story_5071_50711601_50_dialog_content = "I'll turn over a new leaf! I won't collude with those people again. I'll give up on my underground business!",
  ui_story_5071_50711601_51_dialog_content = "Please ask your guild to be lenient with us! Leave us a way out. I'm begging you, Shadowlord!",
  ui_story_5071_50711601_52_dialog_content = "Leave.",
  ui_story_5071_50711601_53_dialog_content = "Then... what about my guild... Shadowlord?",
  ui_story_5071_50711601_54_dialog_content = "...",
  ui_story_5071_50711601_55_dialog_content = "Yes! Yes! I'll get lost now! I'm leaving now...",
  ui_story_5071_50711601_56_dialog_content = "I'm sorry you had to witness that.",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>(He's even more menacing than before!)</color>",
  ui_story_5071_50711601_58_dialog_content = "To be honest, even I feel a little scared seeing you like this...",
  ui_story_5071_50711601_59_dialog_content = "Haha! Please take it from your mind, my friend—I only wish to play a game of chess with you.",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>Knock, knock—</color>",
  ui_story_5071_50711601_61_dialog_content = "Father—",
  ui_story_5071_50711601_62_dialog_content = "... Come in.",
  ui_story_5071_50711601_63_dialog_content = "The poll results are out. Nobody opposed the reform bill.",
  ui_story_5071_50711601_64_dialog_content = "Am I truly giving off such a tyrannical appearance?",
  ui_story_5071_50711601_65_dialog_content = "It wasn't my intention to do so, but I won't deny its usefulness in negotiations.",
  ui_story_5071_50711601_66_dialog_content = "Haha, I suppose it does make complicated matters much more simple.",
  ui_story_5071_50711601_67_dialog_content = "Also, father, we have preliminary findings on who's behind Hanstie...",
  ui_story_5071_50711601_68_dialog_content = "It seems they'll be up to more shenanigans. Here are the files.",
  ui_story_5071_50711601_69_dialog_content = "Let them come.",
  ui_story_5071_50711601_70_dialog_content = "I'm prepared for any battle they bring us. I won't hide any longer.",
  ui_story_5071_50711601_71_dialog_content = "Umbraton is no longer as weak as it once was. Our town is ready to welcome guests like them at any time.",
  ui_story_5071_50711601_72_dialog_content = "Kleken.",
  ui_story_5071_50711601_73_dialog_content = "Yes, my lord?",
  ui_story_5071_50711601_74_dialog_content = "Tell them to begin preparations. We have plenty of work ahead of us.",
  ui_story_5071_50711601_75_dialog_content = "Understood. I'll start preparing for the banquet—",
  ui_story_5071_50711601_76_dialog_content = "Please take it easy, father.",
  ui_story_5071_50711601_77_dialog_content = "You're hurt and poisoned. You must get as much rest as you can.",
  ui_story_5071_50711601_78_dialog_content = "(Huh? Even Bethel's attitude seems a little more relaxed now. They almost seem like a normal father and daughter...)",
  ui_story_5071_50711601_79_dialog_content = "I'm still not that old, Bethel. Let me continue with my work.",
  ui_story_5071_50711601_80_dialog_content = "Sorry, but I should get going—",
  ui_story_5071_50711601_81_dialog_content = "I'm sure you guys have plenty of work to do, so I'll just see myself out.",
  ui_story_5071_50711601_82_dialog_content = "Please forgive me, I only wanted to play a match with you today.",
  ui_story_5071_50711601_83_dialog_content = "Until next time, my friend.",
  ui_story_5071_50711601_84_dialog_content = "Bye—",
  ui_story_5071_50711601_85_dialog_content = "What did you do to my father?",
  ui_story_5071_50711601_86_dialog_content = "We are all amazed by the changes in him.",
  ui_story_5071_50711601_87_dialog_content = "I didn't do anything! The Shadowlord just came to a few realizations on his own, I promise!",
  ui_story_5071_50711601_88_dialog_content = "... Is that so?",
  ui_story_5071_50711601_89_dialog_content = "Okay. He seems more candid and personable now. I like that very much.",
  ui_story_5071_50711601_90_dialog_content = "Lady Bethel, there are more incoming communications and new meetings that you need to host.",
  ui_story_5071_50711601_91_dialog_content = "I'm coming. Thank you, PlayerName, and until next time.",
  ui_story_5071_50711601_92_dialog_content = "Don't mention it. See you soon!",
  ui_story_5071_50711601_93_dialog_content = "Hurry, put some elbow grease into it! The boss is waiting for us!",
  ui_story_5071_50711601_94_dialog_content = "Go, go, go!",
  ui_story_5071_50711601_95_dialog_content = "(They seem pretty full of energy...)",
  ui_story_5071_50711601_96_dialog_content = "Still no idea who we're after, but charge!",
  ui_story_5071_50711601_97_dialog_content = "(The sun is so bright today. Has it ever been this bright in Umbraton?)",
  ui_story_5071_50711601_98_dialog_content = "Be careful! Please pay attention to the traffic even if you're transporting school building materials!",
  ui_story_5071_50711601_99_dialog_content = "(Umbraton looks beautiful in the sunlight—)",
  ui_story_5071_50711601_100_dialog_content = "Hurry up and take the things the guests want to the delivery vehicle—",
  ui_story_5071_50711601_101_dialog_content = "Don't give people the impression that the Umbraton Guild is slow!",
  ui_story_5071_50711601_102_dialog_content = "Looks like everyone wants to enjoy the good weather today.",
  ui_story_5071_50711601_103_dialog_content = "Maybe I should go see a movie with Vice? Hopefully there are still a few tickets left...",
  ui_story_5071_50711601_104_dialog_content = "This book...",
  ui_story_5071_50711601_105_dialog_content = "Yes... This is perfect for reading in the sunlight.",
  ui_story_5071_50711601_106_dialog_content = "Heh, the sun happens to be shining especially brightly today, and so does our hometown...",
  ui_story_5071_50711601_107_dialog_content = "Just like how we always dreamed—",
  ui_story_5071_50711601_108_dialog_content = "Isn't that right, my old friend?",
  ui_story_5071_50711601_109_dialog_content = "It looks like everything has been handled well. Things are finally in order now.",
  ui_story_5071_50711601_110_dialog_content = "I've learned much after all these years—",
  ui_story_5071_50711601_111_dialog_content = "It looks like I'm a good teacher.",
  ui_story_5071_50711601_112_dialog_content = "So beautiful... I never realized our hometown could be this bright...",
  ui_story_5071_50711601_113_dialog_content = "After today, our dreams for Umbraton will only grow stronger, and...",
  ui_story_5071_50711601_114_dialog_content = "They'll definitely be able to spread wings and fly one day...",
  ui_story_5071_50711601_115_dialog_content = "I look forward to that day."
}
return config
